window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s7-23","number":23,"surah":7,"verses":[4],"references":[{"surah":7,"verses":[4]}],"verseLabel":"الأعراف: 4","question":"لماذا صُوّر البأس بأنه يأتي القرية؟","answer":"شُبه البأس بوافد يأتي القرية ويداهمها، تجسيمًا لشدة وقوعه ومباغتته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص723، تحت «بلاغة الاستعارة في الفعل (فجاءها)»","url":""}]},{"id":"s7-24","number":24,"surah":7,"verses":[4],"references":[{"surah":7,"verses":[4]}],"verseLabel":"الأعراف: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿بياتًا أو هم قائلون﴾، فعبّر مرة بالمصدر ومرة بالجملة؟","answer":"جاء ﴿بياتًا﴾ حالًا مفردة تبين وقت مباغتتهم، ثم جاءت ﴿هم قائلون﴾ جملة اسمية تصف هيئتهم عند نزول البأس وقت القيلولة. وفي الانتقال إلى الجملة زيادة تصوير لحالهم، مع تنويع التعبير عن الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص724–725، تحت «نكتة التعبير بالحال المفرد ﴿بياتًا﴾ والحال الجملة ﴿هم قائلون﴾»","url":""}]},{"id":"s7-25","number":25,"surah":7,"verses":[4],"references":[{"surah":7,"verses":[4]}],"verseLabel":"الأعراف: 4","question":"لماذا اختير وقتا الليل والقيلولة لنزول البأس؟","answer":"لأنهما وقتا سكون وغفلة واطمئنان، فيكون مجيء البأس فيهما أشد مباغتة وأوقع في التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص725، تحت «سر اختيار وقتي البيات والقيلولة دون غيرهما»","url":""}]},{"id":"s7-26","number":26,"surah":7,"verses":[5],"references":[{"surah":7,"verses":[5]}],"verseLabel":"الأعراف: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿فما كان دعواهم﴾، وسمّى اعترافهم دعوى؟","answer":"تحتمل الدعوى معنى الدعاء؛ فلم يجدوا عند البأس دعاء ينجيهم، وانتهى قولهم إلى الاعتراف بالظلم. وتحتمل الادعاء؛ أي انقطعت دعاواهم الباطلة في آلهتهم ولم يبق إلا الإقرار ببطلانها وبظلم أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص727–728، تحت «معنى الدعوى ونكتتها في نوع الاستثناء بين الاتصال والانقطاع»","url":""}]},{"id":"s7-27","number":27,"surah":7,"verses":[5],"references":[{"surah":7,"verses":[5]}],"verseLabel":"الأعراف: 5","question":"لماذا جاء التعبير بطريق القصر: ﴿إلا أن قالوا إنا كنا ظالمين﴾؟","answer":"القصر يصور انقطاع كل حجة؛ فلم يبق عند معاينة البأس إلا الاعتراف بالظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص726، تحت «بلاغة القصر في الاستثناء بعد النفي»","url":""}]},{"id":"s7-28","number":28,"surah":7,"verses":[5],"references":[{"surah":7,"verses":[5]}],"verseLabel":"الأعراف: 5","question":"لماذا أكدوا اعترافهم بـ﴿إنّا﴾؟","answer":"أكدوا بـ﴿إنّا﴾ لأن المقام إقرار حاسم بعد طول إنكار، فثبتوا الظلم على أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729، تحت «بلاغة المؤكدات في قوله تعالى: ﴿إنا كنا ظالمين﴾»","url":""}]},{"id":"s7-29","number":29,"surah":7,"verses":[5],"references":[{"surah":7,"verses":[5]}],"verseLabel":"الأعراف: 5","question":"ما الغرض من قولهم عند نزول البأس: ﴿إنا كنا ظالمين﴾؟","answer":"هو اعتراف بالذنب ممتزج بالندم والتحسر؛ فقد انهارت حجتهم وأقروا بالظلم حين لم يعد الاعتراف ينجيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729، تحت عنوان «غرض الخبر ﴿إنا كنا ظالمين﴾ في الآية الكريمة»","url":""}]},{"id":"s7-30","number":30,"surah":7,"verses":[6],"references":[{"surah":7,"verses":[6]}],"verseLabel":"الأعراف: 6","question":"لماذا عُطف سؤال المرسلين على سؤال الأمم في قوله: ﴿ولنسألن المرسلين﴾؟","answer":"ليكتمل مشهد الحساب من الطرفين: تُسأل الأمم عن استجابتها، ويُسأل الرسل عن تبليغهم، فيظهر العدل وتقوم الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص737، تحت عنوان «دلالة العطف في قوله تعالى: ﴿ولنسألن المرسلين﴾»","url":""}]},{"id":"s7-31","number":31,"surah":7,"verses":[6],"references":[{"surah":7,"verses":[6]}],"verseLabel":"الأعراف: 6","question":"ما سرّ تقديم سؤال الأمم على سؤال المرسلين؟","answer":"قُدمت الأمم لأن السياق في تهديد المكذبين، ولأن سؤالهم عن الاستجابة هو المقصود الأول في المحاسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص736، تحت «فائدة تقديم ذكر ﴿أرسل إليهم﴾ على ﴿المرسلين﴾»","url":""}]},{"id":"s7-32","number":32,"surah":7,"verses":[6],"references":[{"surah":7,"verses":[6]}],"verseLabel":"الأعراف: 6","question":"لماذا عُبر عن الأمم بقوله تعالى: ﴿الذين أرسل إليهم﴾؟","answer":"ليجعل إرسال الرسل أساس مساءلتهم؛ فقد بلغتهم الحجة، فصار موقفهم من الرسالة هو موضع السؤال والحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص735–736، تحت عنوان «غرض التعبير بالاسم الموصول في ﴿الذين أرسل إليهم﴾»","url":""}]},{"id":"s7-33","number":33,"surah":7,"verses":[6],"references":[{"surah":7,"verses":[6]}],"verseLabel":"الأعراف: 6","question":"ما أثر المؤكدات في قوله تعالى: ﴿فلنسألن الذين أرسل إليهم﴾؟","answer":"تقطع الشك في وقوع السؤال يوم القيامة، وتصور الحساب وعدًا ووعيدًا محققًا لا احتمالًا بعيدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص735، تحت عنوان «دلالة المؤكدات في قوله تعالى: ﴿فلنسألن الذين أرسل إليهم﴾»","url":""}]},{"id":"s7-34","number":34,"surah":7,"verses":[7],"references":[{"surah":7,"verses":[7]}],"verseLabel":"الأعراف: 7","question":"لماذا يسأل الله الذين أرسل إليهم مع علمه بالجواب؟","answer":"ليس السؤال لاكتساب علم، بل لتقريرهم وإقامة الحجة عليهم وإظهار عدله حين يشهدون على أنفسهم بما فعلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص737، تحت عنوان «نكتة السؤال لـ﴿الذين أرسل إليهم﴾ مع علم الله بالجواب»","url":""}]},{"id":"s7-35","number":35,"surah":7,"verses":[7],"references":[{"surah":7,"verses":[7]}],"verseLabel":"الأعراف: 7","question":"لم قدم ﴿عليهم﴾ على ﴿بعلم﴾ في قوله: ﴿فلنقصن عليهم بعلم﴾؟","answer":"لزيادة الاهتمام بالرسل وأممهم الذين يقع عليهم السؤال والقص، فهم المقصودون بهذه المواجهة. فالتقديم يبرز المخاطبين بنتيجة أعمالهم قبل بيان أن القص قائم على العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص739، تحت «سر تقديم شبه الجملة ﴿عليهم﴾ في قوله: ﴿عليهم بعلم﴾»","url":""}]},{"id":"s7-36","number":36,"surah":7,"verses":[7],"references":[{"surah":7,"verses":[7]}],"verseLabel":"الأعراف: 7","question":"ما دلالة تنكير ﴿علم﴾ في قوله تعالى: ﴿فلنقصن عليهم بعلم﴾؟","answer":"يفيد علمًا عظيمًا كاملًا محيطًا بتفاصيل أحوالهم، فيأتي القص والحساب على الحقيقة من غير نقص أو ظن.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص740، تحت عنوان «نكتة تنكير لفظ ﴿بعلم﴾ وتنوينه»","url":""}]},{"id":"s7-37","number":37,"surah":7,"verses":[7],"references":[{"surah":7,"verses":[7]}],"verseLabel":"الأعراف: 7","question":"ما دلالة دخول ﴿كان﴾ في قوله تعالى: ﴿وما كنا غائبين﴾؟","answer":"تفيد دوام انتفاء الغيبة وعدم انقطاعه، لا نفيها في زمن مضى فقط؛ فعلم الله محيط في كل وقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص740، تحت عنوان «نكتة دخول (كان) في قوله تعالى: ﴿وما كنا غائبين﴾»","url":""}]},{"id":"s7-1560","number":1560,"surah":7,"verses":[7],"references":[{"surah":7,"verses":[7]}],"verseLabel":"الأعراف: 7","question":"لماذا عُبّر بنون العظمة في أفعال قوله تعالى: ﴿فلنقصن عليهم بعلم وما كنا غائبين﴾؟","answer":"لإبراز كمال علم الله وقدرته على إحصاء الأعمال وعرضها بالحق، فيجيء الحساب من الإله العظيم الذي لا يخفى عليه شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص741، تحت عنوان «بلاغة التعبير بنون العظمة في أفعال الآية»","url":""}]},{"id":"s7-38","number":38,"surah":7,"verses":[8],"references":[{"surah":7,"verses":[8]}],"verseLabel":"الأعراف: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿والوزن يومئذ الحق﴾، وما الذي يوزن؟","answer":"الوزن يوم القيامة عدل لا جور فيه، والميزان محمول هنا على الحقيقة. ومن شواهده وزن صحائف العمل، كما في حديث البطاقة والسجلات؛ فتظهر حقيقة الأعمال ومقاديرها في الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص745–746، تحت «لفظ الوزن بين الحقيقة والمجاز»","url":""}]},{"id":"s7-39","number":39,"surah":7,"verses":[8],"references":[{"surah":7,"verses":[8]}],"verseLabel":"الأعراف: 8","question":"لماذا عُرّف ﴿الوزن﴾ في قوله تعالى: ﴿والوزن يومئذ الحق﴾؟","answer":"للدلالة على الوزن المعهود في يوم القيامة، وهو وزن الأعمال الذي ينتظره السياق، لا أي وزن آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص745، تحت عنوان «دلالة (الـ) في لفظ الوزن»","url":""}]},{"id":"s7-1561","number":1561,"surah":7,"verses":[8],"references":[{"surah":7,"verses":[8]}],"verseLabel":"الأعراف: 8","question":"لماذا عُرّف ﴿الحق﴾ في قوله تعالى: ﴿والوزن يومئذ الحق﴾؟","answer":"ليدل على أن ذلك الوزن هو الحق الكامل المطابق للعدل، لا يدخله محاباة ولا نقص ولا باطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص747، تحت عنوان «دلالة (الـ) في لفظ ﴿الحق﴾ من قوله: ﴿والوزن يومئذ الحق﴾»","url":""}]},{"id":"s7-40","number":40,"surah":7,"verses":[8],"references":[{"surah":7,"verses":[8]}],"verseLabel":"الأعراف: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿ثقلت موازينه﴾ بالجمع؟","answer":"جمع الموازين باعتبار تعدد الموزونات أو الصحائف أو موازين الخلق، مع اتحاد حقيقة العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص748–749، تحت «إيراد لفظ الموازين بالجمع»","url":""}]},{"id":"s7-41","number":41,"surah":7,"verses":[8],"references":[{"surah":7,"verses":[8]}],"verseLabel":"الأعراف: 8","question":"لماذا أظهر ضمير الفصل: ﴿فأولئك هم المفلحون﴾؟","answer":"ضمير الفصل يقوي الحكم ويفيد القصر: أصحاب الموازين الثقيلة هم المحققون للفلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص750–751، تحت «بلاغة أساليب القصر في قوله: ﴿فأولئك هم المفلحون﴾»","url":""}]},{"id":"s7-42","number":42,"surah":7,"verses":[9],"references":[{"surah":7,"verses":[9]}],"verseLabel":"الأعراف: 9","question":"هل ثقل الموازين وخفتها في الآية حقيقة أم مجاز؟ وما أثر الصورة؟","answer":"يحتمل الحقيقة في ميزان الأعمال، ويحتمل المجاز عن رجحان الحسنات أو فقدها؛ وفي الحالتين تجعل الصورة قيمة العمل ونتيجته محسوسة أمام القارئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص748، تحت عنوان «بلاغة ثقل الموازين وخفتها بين الحقيقة والمجاز»","url":""}]},{"id":"s7-43","number":43,"surah":7,"verses":[9],"references":[{"surah":7,"verses":[9]}],"verseLabel":"الأعراف: 9","question":"ما سرّ التعبير في قوله تعالى عن أصحاب الموازين الخفيفة: ﴿خسروا أنفسهم﴾؟","answer":"جعل أنفسهم رأس مالهم، فلما أوردوها موارد العذاب كانوا كمن أضاع رأس ماله وخسر كل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص752، تحت «بلاغة المجاز في قوله تعالى: ﴿خسروا أنفسهم﴾»","url":""}]},{"id":"s7-44","number":44,"surah":7,"verses":[9],"references":[{"surah":7,"verses":[9]}],"verseLabel":"الأعراف: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿بما كانوا بآياتنا يظلمون﴾ بتقديم ﴿بآياتنا﴾؟","answer":"قُدم ﴿بآياتنا﴾ للاهتمام بالآيات؛ إذ تكون بحسب موقف الناس منها سببًا في النجاة أو الهلاك، وفي التقديم كذلك مراعاة للفاصلة القرآنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص753، تحت «بلاغة تقديم شبه الجملة ﴿بآياتنا﴾»","url":""}]},{"id":"s7-45","number":45,"surah":7,"verses":[9],"references":[{"surah":7,"verses":[9]}],"verseLabel":"الأعراف: 9","question":"لماذا عُدّ تكذيب الآيات ظلمًا في قوله تعالى: ﴿بآياتنا يظلمون﴾؟","answer":"لأنهم جحدوا الآيات بعد قيام الحجة، فجمع فعلهم التكذيب ووضع الحق في غير موضعه؛ ولذلك ضُمّن الظلم معنى الجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص754، تحت عنوان «التضمين في فعل ﴿يظلمون﴾ وتعديته بالباء»","url":""}]},{"id":"s7-46","number":46,"surah":7,"verses":[10],"references":[{"surah":7,"verses":[10]}],"verseLabel":"الأعراف: 10","question":"ما دلالة قوله تعالى: ﴿ولقد مكناكم في الأرض﴾، ولماذا هو أوسع من الإسكان؟","answer":"التمكين يجعل الأرض قرارًا مع القدرة على التصرف والانتفاع والتعمير، لا مجرد وجود الإنسان فيها؛ فهو نعمة ومسؤولية معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص759، تحت عنوان «بلاغة المجاز أو الكناية في ﴿مكناكم﴾»","url":""}]},{"id":"s7-47","number":47,"surah":7,"verses":[10],"references":[{"surah":7,"verses":[10]}],"verseLabel":"الأعراف: 10","question":"لم قدم ﴿لكم﴾ على ﴿فيها﴾ في قوله: ﴿وجعلنا لكم فيها معايش﴾؟","answer":"للعناية بالمخاطبين الذين قصد إكرامهم بالمعايش، والمسارعة إلى بيان أن المنفعة لهم. ثم ذكر الأرض موضعًا لهذه النعمة، فقدم من أنعم عليهم على محل الانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص761–762، تحت «معنى اللام وعلة تقديم ﴿لكم﴾ على ﴿فيها﴾»","url":""}]},{"id":"s7-48","number":48,"surah":7,"verses":[10],"references":[{"surah":7,"verses":[10]}],"verseLabel":"الأعراف: 10","question":"ما نكتة التعبير بالجمع ﴿معايش﴾؟","answer":"للدلالة على تنوع أسباب العيش من طعام وشراب وزراعة وتجارة وصناعة وسائر ما تقوم به الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص762، تحت عنوان «نكتة التعبير بـ﴿معايش﴾»","url":""}]},{"id":"s7-49","number":49,"surah":7,"verses":[10],"references":[{"surah":7,"verses":[10]}],"verseLabel":"الأعراف: 10","question":"لماذا خُتمت بـ﴿قليلًا ما تشكرون﴾، لا: تذكرون كما في الآية 3؟","answer":"لأن المقام تعداد نعم التمكين والمعايش فناسبه الشكر؛ أما الآية 3 فمقام أمر ونهي يناسب التذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص764، تحت «نكتة التعبير بالشكر في هذا الموضع والتذكر في الموضع السابق»","url":""}]},{"id":"s7-50","number":50,"surah":7,"verses":[11],"references":[{"surah":7,"verses":[11]}],"verseLabel":"الأعراف: 11","question":"لماذا تعلّق فعلا الخلق والتصوير بضمير المخاطبين مع أن الخلق الأول كان لآدم؟","answer":"لأن خلق أصلهم وتصويره نعمة جارية على ذريته، ولأنهم كانوا مقدرين فيه؛ فنُسب إلى الجميع ما بدأ بأصلهم وشمل أثره وجودهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص770–771، تحت عنوان «نكتة تعلق فعلي الخلق والتصوير بضمير المخاطبين»","url":""}]},{"id":"s7-51","number":51,"surah":7,"verses":[11],"references":[{"surah":7,"verses":[11]}],"verseLabel":"الأعراف: 11","question":"لماذا عُطف التصوير على الخلق في قوله تعالى: ﴿خلقناكم ثم صورناكم﴾؟","answer":"لأن الخلق إيجاد الأصل والبنية، أما التصوير فمنحها الهيئة المميزة؛ فذكر التصوير بعد الخلق يلفت إلى تمام النعمة ودقة الإبداع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص771، تحت عنوان «فائدة عطف التصوير على الخلق»","url":""}]},{"id":"s7-52","number":52,"surah":7,"verses":[11],"references":[{"surah":7,"verses":[11]}],"verseLabel":"الأعراف: 11","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم قلنا للملائكة اسجدوا لآدم﴾؟","answer":"تفيد التراخي في الرتبة والانتقال من نعمة الخلق والتصوير إلى مشهد التكريم بالسجود، لا ترتيب خلق كل فرد زمنيًا قبل الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص772، تحت عنوان «دلالة (ثم) في قوله: ﴿ثم قلنا للملائكة﴾»","url":""}]},{"id":"s7-53","number":53,"surah":7,"verses":[11],"references":[{"surah":7,"verses":[11]}],"verseLabel":"الأعراف: 11","question":"ما مناسبة قصة خلق آدم وسجود الملائكة لما قبلها من تذكير بالتمكين والمعايش؟","answer":"بعد تذكير البشر بنعم الأرض أعادهم إلى أصل خلقهم وتكريم أبيهم، ليصل النعمة الأولى بمسؤوليتهم ويحذرهم من عداوة إبليس.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص767، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-55","number":55,"surah":7,"verses":[11],"references":[{"surah":7,"verses":[11]}],"verseLabel":"الأعراف: 11","question":"لماذا قيل عن إبليس: ﴿لم يكن من الساجدين﴾ بدل: لم يسجد؟","answer":"لينفي دخوله في زمرة المطيعين، لا مجرد صدور سجدة منه؛ فالتعبير يصور انفصاله عن الجماعة التي امتثلت أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص773، تحت عنوان «الموقع النحوي والبياني لقوله: ﴿لم يكن من الساجدين﴾»","url":""}]},{"id":"s7-56","number":56,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿ما منعك ألا تسجد﴾، وظاهر الكلام أن المتوقع: أن تسجد؟","answer":"من أوجه التفسير أن «لا» زائدة للتوكيد، والمعنى: ما منعك أن تسجد؛ فالزيادة تحقق معنى الفعل الذي وبخ على تركه، ولا تنفي طلب السجود. ومن الأوجه تضمين المنع معنى الحمل، أي: ما حملك على ألا تسجد؟ والمقصود إنكار امتناعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص782–784، تحت «سر تأكيد المعنى وتقريره بزيادة (لا) في ﴿ما منعك ألا تسجد﴾»","url":""}]},{"id":"s7-57","number":57,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"لماذا ذُكّر إبليس بلفظ ﴿أمرتك﴾ في سؤال امتناعه عن السجود؟","answer":"لأن موجب السجود هو امتثال أمر الله، لا أن يزن إبليس آدم بقياسه الفاسد؛ فالمخالفة عصيان للأمر قبل أن تكون موقفًا من آدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص786، تحت عنوان «نكتة التعبير بلفظ ﴿أمرتك﴾»","url":""}]},{"id":"s7-58","number":58,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"لماذا أجاب إبليس: ﴿أنا خير منه﴾ بدل أن يصرح بما منعه من السجود؟","answer":"ذكر العلة التي توهمها لا جواب السؤال المباشر؛ فكشف أن الكبر وادعاء الخيرية والقياس الفاسد هي التي منعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص789، تحت عنوان «مجيء الجواب على خلاف مقتضى الظاهر»","url":""}]},{"id":"s7-59","number":59,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"ما وجه فساد قياس إبليس النار بالطين في قوله: ﴿خلقتني من نار وخلقته من طين﴾؟","answer":"جعل إبليس الفضل تابعًا لمادة الخلق، وادعى أن النار أفضل من الطين. والمصدر يبين فساد هذه الدعوى، وأن تفضيل آدم كان بما خصه الله به من الخلق والتكريم والاستعداد، لا بمجرد أصله المادي؛ فذكر الأصلين لا يثبت الخيرية التي ادعاها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص790–791، تحت «الطباق بين النار والطين، وبيان أن قياس إبليس حجة عليه»","url":""}]},{"id":"s7-60","number":60,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"كيف تبين جملتا ﴿خلقتني من نار وخلقته من طين﴾ مراد إبليس بقوله: ﴿أنا خير منه﴾؟","answer":"تفصلان دعواه المجملة، وتكشفان أن مراده بالخيرية فضل مادة خلقه في زعمه. فهما بيان لحجته، أو جواب عن سؤال يثيره قوله: ما وجه كونك خيرًا منه؟","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص790، تحت «جملتا الخلق بين عطف البيان والاستئناف البياني»","url":""}]},{"id":"s7-61","number":61,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"كيف تخدم الجملة الاسمية ﴿أنا خير منه﴾ دعوى إبليس؟","answer":"صاغ دعواه في جملة اسمية ليعرض الخيرية كأنها وصف ثابت له، ويبني عليها امتناعه عن السجود. ثم فسر هذا الفضل المزعوم باختلاف مادتي الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص789–790، تحت «مناسبة التعبير بالجملة الاسمية في قوله: ﴿أنا خير منه﴾»","url":""}]},{"id":"s7-62","number":62,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"لماذا حُذف نداء إبليس واسمه في الأعراف، وذُكرا في مواضع أخرى؟","answer":"لقرب ذكر إبليس من الخطاب في الأعراف فاستغني عن النداء والاسم، بينما طال الفصل في بعض المواضع الأخرى فأعيد اسمه لإيضاح المخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص775–776، تحت عنوان «بلاغة المتشابه اللفظي مع آيات السجود الأخرى»","url":""}]},{"id":"s7-63","number":63,"surah":7,"verses":[13],"references":[{"surah":7,"verses":[13]}],"verseLabel":"الأعراف: 13","question":"لماذا كان جزاء استكبار إبليس هو الهبوط؟","answer":"لأن الهبوط يقابل طلبه العلو بغير حق؛ فمن تكبر عن أمر الله أُنزل من منزلته وأُبعد عن موضع الكرامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص794، تحت عنوان «نكتة التعبير بلفظ الهبوط»","url":""}]},{"id":"s7-64","number":64,"surah":7,"verses":[13],"references":[{"surah":7,"verses":[13]}],"verseLabel":"الأعراف: 13","question":"إلى ماذا يعود الضمير في ﴿منها﴾: إلى الجنة أم السماء أم المنزلة؟","answer":"يحتمل عوده إلى الجنة أو السماء أو المنزلة؛ ويجمعها معنى الإخراج من مقام الكرامة والعلو الذي كان فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص795، تحت «مناسبة عود الضمير على غير مذكور في قوله: ﴿منها﴾»","url":""}]},{"id":"s7-65","number":65,"surah":7,"verses":[13],"references":[{"surah":7,"verses":[13]}],"verseLabel":"الأعراف: 13","question":"ما دلالة النفي في قوله تعالى: ﴿فما يكون لك أن تتكبر فيها﴾؟","answer":"ينفي استحقاق إبليس للتكبر وإمكان قبوله منه في ذلك المقام، فهو أبلغ من نهي مجرد يقول: لا تتكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص796، تحت عنوان «دلالة النفي في قوله: ﴿فما يكون لك﴾»","url":""}]},{"id":"s7-66","number":66,"surah":7,"verses":[13],"references":[{"surah":7,"verses":[13]}],"verseLabel":"الأعراف: 13","question":"لماذا كرر الأمر بالخروج بعد الهبوط: ﴿فاخرج﴾؟","answer":"يحتمل أن يكون ﴿فاخرج﴾ تأكيدًا للأمر بالهبوط، لأن الهبوط من الجنة خروج منها. ويحتمل أن يؤسس معنى آخر، فيكون الهبوط زوالًا عن موضع الكرامة، والخروج طردًا مقرونًا بالذل أو إبعادًا عن المكان؛ فيشتد به بيان العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص800–801، تحت «دلالة قوله تعالى: ﴿فاخرج﴾ بين التأكيد والتأسيس»","url":""}]},{"id":"s7-67","number":67,"surah":7,"verses":[13],"references":[{"surah":7,"verses":[13]}],"verseLabel":"الأعراف: 13","question":"لماذا ناسب ذكر الصغار جزاء إبليس بعد تكبره؟","answer":"لأن الجزاء من جنس الذنب؛ فمن طلب العلو بغير حق عوقب بالذل والهوان، فانتقل من التكبر إلى أن يكون من الصاغرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص802، تحت عنوان «مناسبة ذكر الصغار في الآية الكريمة»","url":""}]},{"id":"s7-68","number":68,"surah":7,"verses":[14],"references":[{"surah":7,"verses":[14]}],"verseLabel":"الأعراف: 14","question":"ماذا يكشف طلب إبليس الإنظار بدل المغفرة عن موقفه بعد المعصية؟","answer":"يكشف إصراره على التمرد؛ فلم يتجه إلى التوبة وطلب المغفرة، بل طلب إطالة بقائه ليواصل إغواء بني آدم. وهكذا حوّل مهلة العمر إلى امتداد للعداوة بدل أن يجعلها سبيلًا للرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10، تحت عنوان «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s7-69","number":69,"surah":7,"verses":[14],"references":[{"surah":7,"verses":[14]}],"verseLabel":"الأعراف: 14","question":"لماذا اختير ﴿أنظرني﴾، لا: أمهلني؟","answer":"الإنظار تأخير إلى أجل معلوم، أما الإمهال فأعم وقد لا يذكر معه حد؛ فوافق لفظه طلب تحديد الغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص17، تحت «الفروق المعجمية: الإنظار والإمهال»","url":""}]},{"id":"s7-70","number":70,"surah":7,"verses":[14],"references":[{"surah":7,"verses":[14]}],"verseLabel":"الأعراف: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى يوم يبعثون﴾، دون أن يقال: إلى يوم القيامة؟","answer":"حدد يوم البعث لأنه يوم إحياء الخلق الذي يعقبه الخلود؛ فأراد امتداد بقائه إلى ذلك اليوم ليفلت من الموت. لذلك كانت تسمية البعث كاشفة عن غرضه من تحديد الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص12، تحت «مناسبة تحديد الإنظار في قوله تعالى: ﴿إلى يوم يبعثون﴾»","url":""}]},{"id":"s7-71","number":71,"surah":7,"verses":[14],"references":[{"surah":7,"verses":[14]}],"verseLabel":"الأعراف: 14","question":"لماذا جاء ﴿يبعثون﴾ بالبناء للمجهول؟","answer":"بُني للمجهول لتوجيه النظر إلى حدث بعث الخلق وعظمته، لا إلى إسناد الفعل إلى فاعله المعلوم، وفيه إيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص12، تحت «نكتة مجيء لفظ البعث على صيغة المبني للمفعول»","url":""}]},{"id":"s7-72","number":72,"surah":7,"verses":[14],"references":[{"surah":7,"verses":[14]}],"verseLabel":"الأعراف: 14","question":"ما سرّ مجيء طلب إبليس في الأعراف: ﴿أنظرني﴾، وفي الحجر وص: ﴿رب فأنظرني﴾؟","answer":"اقتصر مقام الأعراف على مجرد الإخبار بالاستنظار، فناسبه الإيجاز في ﴿أنظرني﴾. وفي الحجر وص جاء الطلب بعد ذكر الطرد والحرمان، فناسب مقام الضراعة أن ينادي بلفظ ﴿رب﴾ قبل طلب الإنظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص15–16، تحت عنوان «مقام الاستنظار يقتضي إظهار الضراعة بلفظ الربوبية»","url":""}]},{"id":"s7-73","number":73,"surah":7,"verses":[15],"references":[{"surah":7,"verses":[15]}],"verseLabel":"الأعراف: 15","question":"لماذا جاء جواب إبليس جملة اسمية: ﴿إنك من المنظرين﴾؟","answer":"تفيد الجملة الاسمية ثبوت الحكم واستقراره؛ فلا تعرضه كفعل إنظار عابر، بل تقرر دخوله في حكم مقدر إلى الأجل المعلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص13–14، تحت عنوان «بلاغة التعبير بالاسمية في قوله: ﴿إنك من المنظرين﴾»","url":""}]},{"id":"s7-1562","number":1562,"surah":7,"verses":[15],"references":[{"surah":7,"verses":[15]}],"verseLabel":"الأعراف: 15","question":"لماذا قيل لإبليس: ﴿من المنظرين﴾ بصيغة الجمع؟","answer":"ليدل على أنه داخل في طائفة سبق تقدير تأخير آجالها، لا أنه مُنح إنظارًا خاصًا استجابة كاملة لطلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص13–14، تحت عنوان «نكتة جمع ﴿المنظرين﴾»","url":""}]},{"id":"s7-74","number":74,"surah":7,"verses":[15],"references":[{"surah":7,"verses":[15]}],"verseLabel":"الأعراف: 15","question":"ما سرّ حذف غاية الإنظار من الجواب مع أن إبليس طلب تحديدها؟","answer":"حذف الغاية ليبين أنه لم يُجب إلى اليوم الذي طلبه؛ فكونه من المنظرين يتحقق بتأخيره إلى الوقت المعلوم، وهو قبل بعث الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص13، تحت «مناسبة الجواب في قوله تعالى: ﴿إنك من المنظرين﴾»","url":""}]},{"id":"s7-75","number":75,"surah":7,"verses":[15],"references":[{"surah":7,"verses":[15]}],"verseLabel":"الأعراف: 15","question":"ما سرّ مجيء الجواب في الأعراف: ﴿إنك من المنظرين﴾، وفي الحجر وص بالفاء: ﴿فإنك﴾؟","answer":"جاء الكلام في الأعراف استئنافًا غير مسبب عما قبله، فناسبه حذف الفاء. وفي الحجر وص جاء الاستنظار عقب الحكم بالطرد واللعنة، على معنى: إذا حكمت علي بذلك فأنظرني؛ فناسب هذا التسببَ اقترانُ الجواب بالفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص16–17، تحت «الفاء قرينة التسبب عما قبلها في جملة ﴿فإنك من المنظرين﴾»","url":""}]},{"id":"s7-76","number":76,"surah":7,"verses":[16],"references":[{"surah":7,"verses":[16]}],"verseLabel":"الأعراف: 16","question":"ما دلالة نسبة إبليس الغواية إلى الله في قوله: ﴿فبما أغويتني﴾؟","answer":"نسب الغواية إلى الله على سبيل الاعتراض والتمرد، فجعل ما انتهى إليه من الضلال أساسًا لوعيده بإغواء البشر. ويذكر المصدر من توجيه كلامه أنه عد الأمر بالسجود سببًا في ظهور إبائه وتكبره، فنسب الإغواء إلى ما اتخذه سببًا لغوايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص22، تحت «دلالة صيغة ﴿أغويتني﴾ في جملة ﴿فبما أغويتني لأقعدن لهم﴾»","url":""}]},{"id":"s7-77","number":77,"surah":7,"verses":[16],"references":[{"surah":7,"verses":[16]}],"verseLabel":"الأعراف: 16","question":"ما دلالة الباء و﴿ما﴾ في ﴿فبما أغويتني﴾؟","answer":"الباء للسببية أو للقسم، و﴿ما﴾ مصدرية: بسبب إغوائك إياي، أو أقسم بإغوائك؛ وعلى الوجهين بنى وعيده على غوايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص21–22، تحت «دلالة الباء في قوله تعالى: ﴿فبما أغويتني﴾؛ دلالة (ما) المصدرية في جملة ﴿فبما أغويتني﴾»","url":""}]},{"id":"s7-78","number":78,"surah":7,"verses":[16],"references":[{"surah":7,"verses":[16]}],"verseLabel":"الأعراف: 16","question":"لماذا أكد وعيده باللام والنون: ﴿لأقعدن لهم﴾؟","answer":"اللام واقعة في جواب القسم، ونون التوكيد الثقيلة تؤكد الفعل؛ فاجتماعهما يحقق وعيده بالقعود على الصراط، ويظهر شدة عزمه على إغواء الناس واستمراره فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص23، تحت «دلالة تتابع التأكيد في قوله: ﴿لأقعدن لهم﴾»","url":""}]},{"id":"s7-79","number":79,"surah":7,"verses":[16],"references":[{"surah":7,"verses":[16]}],"verseLabel":"الأعراف: 16","question":"لماذا صوّر الإضلال بالقعود على الطريق؟","answer":"استعار القعود للملازمة والترصد؛ كقاطع الطريق يقعد للمارين ليصدهم عن وجهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص22–23، تحت «لفظ القعود بين الكناية والاستعارة التمثيلية»","url":""}]},{"id":"s7-80","number":80,"surah":7,"verses":[16],"references":[{"surah":7,"verses":[16]}],"verseLabel":"الأعراف: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿صراطك المستقيم﴾، فأضاف الصراط إلى الله؟","answer":"إضافة الصراط إلى الله تخصصه بأنه الطريق الذي نصبه لعباده ليوصلهم إلى مرضاته. ففي الإضافة بيان أن بلوغ رضوانه يكون باتباع هذا الصراط، وهو الذي أراد إبليس صد الناس عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص25، تحت «دلالة الإضافة في قوله تعالى: ﴿صراطك﴾ من الآية الكريمة»","url":""}]},{"id":"s7-81","number":81,"surah":7,"verses":[16],"references":[{"surah":7,"verses":[16]}],"verseLabel":"الأعراف: 16","question":"لماذا عُدّي القعود للصراط بنفسه من غير ﴿على﴾ أو ﴿في﴾؟","answer":"من توجيهاته أن ﴿أقعدن﴾ ضمن معنى «ألزمن»، فتعدى إلى الصراط مباشرة، أو أن الجار حذف والتقدير: على صراطك. ويحتمل نصبه على الظرفية؛ وعلى هذه الأوجه يرسم التعبير ملازمة الطريق والترصد لسالكيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص24–25، تحت «نكتة تعدي ﴿لأقعدن﴾ إلى المفعول ﴿صراطك﴾»","url":""}]},{"id":"s7-82","number":82,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم لآتينهم﴾ بـ﴿ثم﴾ بعد ﴿لأقعدن﴾؟","answer":"﴿ثم﴾ للترتيب الرتبي: بعد أصل الملازمة والقعود ينتقل إلى مباشرة إتيانهم من وجوه متعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص25–26، تحت «دلالة حرف العطف (ثم) في قوله: ﴿ثم لآتينهم﴾»","url":""}]},{"id":"s7-83","number":83,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"لماذا ذكر الجهات الأربع: الأمام والخلف واليمين والشمال، ولم يذكر الفوق والتحت؟","answer":"تمثل الجهات الأربع الطرق التي يعتاد العدو أن يهجم منها، فصورت محاولات الإغواء المتنوعة بصورة هجوم محيط بالإنسان. أما الفوق والتحت فليستا من جهات هجوم العدو المعتادة في هذا التمثيل؛ فالمراد استيعاب مسالك الوسوسة غالبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص29، تحت «بلاغة الاستعارة التمثيلية في هذه الآية الكريمة»","url":""}]},{"id":"s7-1563","number":1563,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"كيف يخدم الطباق بين الأمام والخلف واليمين والشمال تصوير إحاطة الوسوسة؟","answer":"يجمع الطباق الجهات المتقابلة في صورة واحدة، فيوحي بتنوع مداخل إبليس ومحاولته الإحاطة بالإنسان من مسالك متعارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص29، تحت «بديع الطباق في الآية الكريمة»","url":""}]},{"id":"s7-84","number":84,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿من بين أيديهم ومن خلفهم﴾ بـ﴿من﴾، ثم ﴿عن أيمانهم وعن شمائلهم﴾ بـ﴿عن﴾؟","answer":"﴿من﴾ تلائم الابتداء والجهتين الممتدتين أمامًا وخلفًا، و﴿عن﴾ تلائم المجاوزة والميل من جانبي اليمين والشمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص26–27، تحت «نكتة المخالفة في حروف الجر ﴿من بين أيديهم ومن خلفهم﴾»","url":""}]},{"id":"s7-85","number":85,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"ما دلالة جمع ﴿أيمانهم﴾ و﴿شمائلهم﴾ في وصف إتيان إبليس؟","answer":"جاء الجمع ملائمًا لجماعة من يأتيهم إبليس؛ فيأتي كل واحد من جهة يمينه وشماله، ويوحي بتكرر التعرض وتنوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص27–28، تحت «مناسبة جمع اليمين والشمال في ﴿وعن أيمانهم وعن شمائلهم﴾»","url":""}]},{"id":"s7-1564","number":1564,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"لماذا تعددت سبل إغواء إبليس بينما وُصف صراط الله بالاستقامة والوحدة؟","answer":"لأن الباطل تتشعب مسالكه بحسب الشهوات والشبهات، أما طريق الحق فوجهته واحدة تصل العبد بمرضاة الله؛ فكثرة المداخل لا تجعلها طرقًا مساوية للصراط المستقيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص27–28، تحت «سبل إبليس كثيرة متنوعة، وصراط الله مستقيم واحد»","url":""}]},{"id":"s7-86","number":86,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"لماذا ختم إبليس وعيده بقوله: ﴿ولا تجد أكثرهم شاكرين﴾، لا: مؤمنين؟","answer":"نفي الشكر كناية عن الكفر؛ إذ اتباع صراط الله هو الإيمان وشكر نعمته، ومقصود إبليس صرفهم عنه. فعدل في وعيده إلى نفي الشكر، وفيه أيضًا إظهار قبح جحود النعمة التي أنعم الله بها عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص29–30، تحت «بلاغة الكناية في جملة ﴿ولا تجد أكثرهم شاكرين﴾»","url":""}]},{"id":"s7-87","number":87,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"لماذا أعيد الأمر بالخروج: ﴿اخرج منها﴾ بعد قوله في الآية 13: ﴿فاخرج﴾؟","answer":"أعيد بعد ظهور إصراره ووعيده لتجديد الطرد وتأكيد أنه لا مقام له فيها بعد هذه المجاوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص31–32، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-88","number":88,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"ما الفرق الدلالي بين ﴿مذءومًا﴾ و﴿مدحورًا﴾ في جزاء إبليس؟","answer":"المذءوم هو المعيب البالغ في الذم والمقت، والمدحور هو المطرود المبعد على سبيل الإهانة؛ فجمع اللفظان الذم والطرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص31، تحت «شرح المفردات: ﴿مذءومًا﴾ و﴿مدحورًا﴾»","url":""}]},{"id":"s7-1565","number":1565,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"لماذا قُيّد خروج إبليس بحالي ﴿مذءومًا مدحورًا﴾؟","answer":"ليبين أن خروجه لم يكن انتقالًا مجردًا، بل خروجًا مصحوبًا بالمقت والمهانة والطرد، فيكتمل تصوير الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص33، تحت «دلالة مجيء الخروج مقيدًا بالحال»","url":""}]},{"id":"s7-89","number":89,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"لم اختير وصف ﴿مذءومًا﴾ في الأمر بخروج إبليس؟","answer":"لأن الذأم أشد من الذم، فناسب الوصف شدة عزمه على الإغواء والتمرد؛ إذ بالغ في العداوة، فجيء بما يدل على بلوغه الغاية في المقت والعيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص33، تحت «علة إيثار لفظ ﴿مذءومًا﴾ في هذا الموضع»","url":""}]},{"id":"s7-90","number":90,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"ما الذي يكشفه الوعيد: ﴿لأملأن جهنم منكم﴾ عن عاقبة مشروع إبليس؟","answer":"يكشف أن مشروع الإغواء لا يغير سلطان الله ولا يفلت أتباع إبليس من الجزاء؛ فالاجتماع على العصيان ينتهي إلى الاجتماع في جهنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص35، تحت «نكتة التعبير بقوله تعالى: ﴿لأملأن جهنم منكم﴾»","url":""}]},{"id":"s7-1566","number":1566,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"ما دلالة ختم الوعيد بكلمة ﴿أجمعين﴾؟","answer":"تؤكد شمول الوعيد لإبليس ومن اتبعه، فلا يستثني اجتماعهم في العصيان أحدًا ممن ثبت عليه الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص36، تحت «دلالة قوله تعالى: ﴿أجمعين﴾»","url":""}]},{"id":"s7-91","number":91,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"إلى من يعود ضمير الجمع في ﴿منكم﴾؟","answer":"يعود إلى إبليس وأتباعه من الجن والإنس؛ ودل جمع الخطاب على إدخال من اتبعه معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص35–36، تحت «بلاغة التغليب في قوله: ﴿منكم﴾»","url":""}]},{"id":"s7-92","number":92,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿اسكن أنت وزوجك الجنة﴾، فأظهر ﴿أنت﴾ بعد ضمير الفعل؟","answer":"جاء ﴿أنت﴾ توكيدًا للضمير المستتر في ﴿اسكن﴾، وفيه تقرير الامتنان على آدم والتنويه بمقامه. وفي سياق طرد إبليس يعرض الضمير بإكرام آدم الذي أُمر إبليس بالسجود له، فتزداد المقابلة بين إسكان آدم وإخراج إبليس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص41، تحت «بلاغة التعريض بالضمير المنفصل»","url":""}]},{"id":"s7-93","number":93,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"لم خص آدم بالخطاب في ﴿اسكن أنت وزوجك الجنة﴾، وجعل زوجه معطوفة عليه؟","answer":"لأن آدم هو الأصيل في تلقي الوحي ومعاني الأمر، فجاء الخطاب موجهًا إليه، وعطفت زوجه عليه لتشاركه حكم السكن. فالصياغة تجمع بين تخصيصه بالخطاب وشمول النعمة لهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص40، تحت «نكتة تخصيص الخطاب بآدم، وعطف زوجه عليه»","url":""}]},{"id":"s7-94","number":94,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿فكلا من حيث شئتما﴾، ولم يحدد لهما موضعًا؟","answer":"أطلق لهما الأكل من أي موضع شاءا توسعةً وإباحةً عامة، فلم يحتج إلى تحديد إلا في الشجرة المستثناة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص43، تحت «مناسبة العموم في قوله تعالى: ﴿من حيث شئتما﴾»","url":""}]},{"id":"s7-95","number":95,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"لماذا جاء النهي: ﴿ولا تقربا هذه الشجرة﴾، لا: لا تأكلا منها؟","answer":"النهي عن القرب أبلغ وأحوط من النهي عن الأكل؛ لأنه يسد الطرق المؤدية إليه ويبعدهما عن موضع الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص46–47، تحت «نكتة التعبير بلفظ: ﴿تقربا﴾ في ﴿ولا تقربا هذه الشجرة﴾»","url":""}]},{"id":"s7-96","number":96,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"لماذا أشار إلى الشجرة بـ﴿هذه﴾؟","answer":"اسم الإشارة يعين الشجرة تعيينًا مشاهدًا حتى لا يلتبس المحظور، ويشعر بقربها المكاني منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص43، تحت «دلالة اسم الإشارة في قوله تعالى: ﴿هذه الشجرة﴾»","url":""}]},{"id":"s7-97","number":97,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"ما سر التعبير بـ﴿فتكونا من الظالمين﴾، دون: فتكونا ظالمين؟","answer":"في إدخالهما في زمرة الظالمين مبالغة في التحذير من مخالفة أمر الله؛ فالنسبة إلى أهل الوصف تقوي معنى الاتصاف به وشدة التنفير منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص352، تحت عنوان «التعبير بـ﴿من الظالمين﴾ دون ﴿فتكونا ظالمين﴾ للمبالغة في التحذير»","url":""}]},{"id":"s7-99","number":99,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"لماذا عُطف الأكل بالفاء ﴿فكلا﴾ في الأعراف، وبالواو ﴿وكلا﴾ في البقرة؟","answer":"الفاء في الأعراف تفيد ترتب الأكل مباشرة على السكن والإذن، والواو في البقرة لمطلق الجمع مع توسع السياق في ذكر النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص45–46، تحت «تنوع التعبير بين الواو والفاء تفاوت في ذكر مطلق الأكل ونوعه»","url":""}]},{"id":"s7-100","number":100,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"لماذا حُذفت ﴿رغدًا﴾ من آية الأعراف وذُكرت في البقرة؟","answer":"جاءت ﴿رغدًا﴾ في البقرة لزيادة بيان سعة النعمة؛ فالسياق يعدد ما امتن الله به على آدم. أما الأعراف فالسياق يعرض عداوة إبليس والتحذير من مخالفته، فاكتفى بإباحة الأكل حيث شاءا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص45–46، تحت عنوان «تنوع التعبير بين الواو والفاء، تفاوت في ذكر مطلق الأكل ونوعه»","url":""}]},{"id":"s7-101","number":101,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"لماذا تقدّم ﴿منها﴾ على ﴿حيث شئتما﴾ في البقرة، بينما جاء في الأعراف: ﴿من حيث شئتما﴾؟","answer":"في البقرة يعود الضمير في ﴿منها﴾ إلى الجنة باعتبار مطاعمها، فصرح بمصدر الأكل، ثم عمم مكانه بقوله: ﴿حيث شئتما﴾. وفي الأعراف دخلت ﴿من﴾ على ﴿حيث﴾ لتجعل ابتداء الأكل من أي موضع شاءا، مع إشعار بسعة المأكل والتوسعة عليهما.","sources":[{"label":"[موضع المقارنة في البقرة] موسوعة التفسير البلاغي، ج1، ص350، تحت «فن الاستخدام»","url":""},{"label":"موسوعة التفسير البلاغي، ج13، ص42–43، تحت «نكتة التعبير بـ﴿من﴾؛ مناسبة العموم في قوله تعالى: ﴿من حيث شئتما﴾»","url":""}]},{"id":"s7-102","number":102,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"كيف يصور قوله ﴿فوسوس لهما الشيطان﴾ طريقة خداعه لآدم وزوجه؟","answer":"يسمي إلقاءه إليهما وسوسة لأنها تسويل خفي بالغ في الإسرار، سواء كان بكلام أو بإلقاء في النفس. فخفي حديثه عن غيرهما، وأظهر لهما صورة الناصح ليخدعهما، مع أن غايته إغواؤهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص50–51، تحت «دلالة التعبير بقوله تعالى: ﴿فوسوس لهما الشيطان﴾»","url":""}]},{"id":"s7-103","number":103,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"لماذا عُلّلت الوسوسة بقوله: ﴿ليبدي لهما ما ووري عنهما من سوآتهما﴾؟","answer":"اللام للعاقبة والصيرورة على وجه؛ إذ لم يكن مقصوده المباشر كشف العورة، لكن وسوسته آلت إليه؛ ويجوز أن تكون للتعليل باعتبار قصده سلب النعمة وإيذاءهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص51–52، تحت «توجيه اللام بين العاقبة والتعليل في جملة ﴿ليبدي لهما﴾»","url":""}]},{"id":"s7-104","number":104,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"ما دلالة التعبير بالمواراة في ﴿ما ووري عنهما﴾؟","answer":"المواراة ستر الشيء عن النظر، والتعبير يبرز شدة ستر عورتيهما حتى كانتا محجوبتين عن نفسيهما. ويذكر المصدر وجه المبالغة في صيغة المفاعلة، ووجه الدلالة على أصل الستر؛ فالمعنى يصور تمام الستر قبل انكشافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص52–53، تحت «دلالة صيغة: ﴿ما ووري عنهما﴾ من الآية الكريمة»","url":""}]},{"id":"s7-105","number":105,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"لماذا جُمعت ﴿سوآتهما﴾؟","answer":"وضع الجمع موضع التثنية تخفيفًا، كما يرد في العربية عند إضافة أعضاء الاثنين إليهما. وفيه تعظيم شأن انكشاف العورة، حتى يصور كشف عورة كل واحد كأنه كشف لسوءات كثيرة؛ ويذكر المصدر أيضًا اعتبار العورة من الأمام والخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص53، تحت «سر التعبير بالجمع في قوله تعالى: ﴿من سوآتهما﴾»","url":""}]},{"id":"s7-106","number":106,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"ما دلالة قصر الشيطان علة النهي في قوله: ﴿ما نهاكما ربكما عن هذه الشجرة إلا أن تكونا ملكين﴾؟","answer":"القصر كذب به إبليس ليصور النهي كأنه لا علة له إلا منع رتبة الملك أو الخلود، فيصرفهما عن حكمة الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص55، تحت «مناسبة الحصر في جملة الاستثناء في قوله ﴿إلا أن تكونا ملكين﴾»","url":""}]},{"id":"s7-107","number":107,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"لماذا اختار فتنتين: الملك والخلود؟","answer":"أغراهما بما يظنان أنه يرفعهما فوق حالهما: رتبة الملائكة، أو البقاء والخلود في الجنة. فحصر لهما المطمع في أمرين يرغبان فيهما ليقوي إقبالهما على الأكل ويخفي حقيقة الخداع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص56، تحت «نكتة العطف بـ﴿أو﴾»","url":""}]},{"id":"s7-108","number":108,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"لم قال الشيطان ﴿ربكما﴾ في معرض إغوائه لآدم وزوجه؟","answer":"استعمل لفظ الربوبية ليوهمهما أن نصحه منسجم مع إنعام ربهما عليهما، ويهون عليهما مخالفة النهي. وأبعد نفسه عن الخطاب فقال ﴿ربكما﴾، مظهرًا لهما صورة الناصح مع ما في قوله من الكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص54، تحت «نكتة التعبير بلفظ ﴿ربكما﴾»","url":""}]},{"id":"s7-109","number":109,"surah":7,"verses":[21],"references":[{"surah":7,"verses":[21]}],"verseLabel":"الأعراف: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وقاسمهما﴾ بصيغة المفاعلة مع أن المقسم هو إبليس؟","answer":"المفاعلة هنا للمبالغة في القسم وتكريره، أو لأنهما قابلا قسمه بالقبول والتصديق فكأن المشاركة حصلت من الجانبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص58–59، تحت «دلالة صيغة المفاعلة في قوله تعالى: ﴿وقاسمهما﴾»","url":""}]},{"id":"s7-110","number":110,"surah":7,"verses":[21],"references":[{"surah":7,"verses":[21]}],"verseLabel":"الأعراف: 21","question":"لماذا أكد كذبه بـ﴿إني لكما لمن الناصحين﴾؟","answer":"واجه إبليس شكهما بالقسم و﴿إن﴾ واللام والجملة الاسمية، فتتابعت المؤكدات ليقرر نصحه المزعوم ويقرب باطله إلى نفسيهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص59–60، تحت «مناسبة تتابع المؤكدات في ﴿وقاسمهما إني لكما لمن الناصحين﴾»","url":""}]},{"id":"s7-111","number":111,"surah":7,"verses":[21],"references":[{"surah":7,"verses":[21]}],"verseLabel":"الأعراف: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿من الناصحين﴾، لا: ناصح؟","answer":"ادعى أنه واحد من جماعة عُرفت بالنصح، لا ناصح منفرد؛ ليقوي الثقة بقوله ويبالغ في التلبيس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص60، تحت «توجيه التعبير بقوله ﴿لمن الناصحين﴾، ودلالته على المراوغة»","url":""}]},{"id":"s7-112","number":112,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا عبّر عن إهباطهما إلى المعصية بقوله: ﴿فدلاهما بغرور﴾؟","answer":"استعيرت التدلية لإنزالهما من مقام الطاعة والنعمة بالتدرج في الخداع؛ كمن يدلي غيره في بئر بحبل يغره ثم يقطعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص64، تحت «بلاغة الاستعارة التمثيلية في الفعل ﴿فدلاهما﴾»","url":""}]},{"id":"s7-113","number":113,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا عُدّي التدلية بالباء في ﴿بغرور﴾؟","answer":"الباء للسببية أو الملابسة: أنزلهما بسبب غروره، أو مصاحبين لما كرره من الخداع والقسم الكاذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص64–65، تحت «الباء بين السببية والملابسة في لفظ ﴿بغرور﴾»","url":""}]},{"id":"s7-114","number":114,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا قيل: ﴿ذاقا الشجرة﴾، لا: أكلا منها؟","answer":"الذوق أول الأكل وأقله؛ فالتعبير يبين أن أثر المخالفة ظهر بمجرد تناول يسير، ويعظم شأن النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص66، تحت «علة التعبير بلفظ ﴿ذاقا﴾»","url":""}]},{"id":"s7-115","number":115,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿بدت لهما سوآتهما﴾ بعد أن كانت مواراة؟","answer":"قابل الظهور بالمواراة السابقة: سقط عنهما اللباس الذي كان يسترهما فظهرت عوراتهما لهما، فبادرا إلى الستر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص63، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-116","number":116,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا اختير ﴿وطفقا﴾ في تصوير مبادرتهما إلى الستر؟","answer":"تفيد ﴿طفقا﴾ الشروع والمبادرة؛ فما إن ظهرت السوأتان حتى أخذا في الستر من غير إمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص69، تحت «نكتة التعبير بالفعل ﴿وطفقا﴾»","url":""}]},{"id":"s7-1567","number":1567,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"ما أثر المضارع في قوله: ﴿يخصفان عليهما من ورق الجنة﴾؟","answer":"يستحضر المضارع هيئة الخصف المتجدد أمام السامع، فيصور حركتهما المتتابعة وهما يلصقان الورق طلبًا للستر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص67، تحت «نكتة التعبير بالفعل المضارع في ﴿يخصفان﴾»","url":""}]},{"id":"s7-117","number":117,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا قيل: ﴿يخصفان عليهما﴾ مع أن المقصود ستر السوأتين؟","answer":"يرجع الضمير إلى جسميهما على وجه المبالغة، كأن شدة الحياء حملتهما على طلب ستر الجسد كله، لا موضع العورة وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص69، تحت «مجيء الكلام على خلاف مقتضى الظاهر في ﴿يخصفان عليهما﴾»","url":""}]},{"id":"s7-118","number":118,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"ما دلالة اختيار النداء في قوله: ﴿وناداهما ربهما﴾؟","answer":"يشعر النداء ببعد حالهما عن مقام القرب بعد المخالفة، ويجعل العتاب مواجهة توقظهما إلى ما وقعا فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص68، تحت «إيثار التعبير بالنداء»","url":""}]},{"id":"s7-1568","number":1568,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا جاء العتاب بلفظ ﴿ربهما﴾؟","answer":"ليذكرهما بأن الله مالك أمرهما ومدبر أحوالهما ومربيهما؛ فيبقى معنى التربية والإنعام حاضرًا حتى في مقام العتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص70، تحت «نكتة التعبير بقوله ﴿ربهما﴾ دون سواه من الأسماء والصفات»","url":""}]},{"id":"s7-119","number":119,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"ما دلالة الاستفهام في قوله: ﴿ألم أنهكما عن تلكما الشجرة﴾؟","answer":"هو استفهام تقريري يثبت النهي الذي خالفاه، ويوقظهما إلى وضوح الأمر الذي سبق أن تلقياه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص68، تحت «مجاز الاستفهام في قوله: ﴿ألم أنهكما﴾»","url":""}]},{"id":"s7-1569","number":1569,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"ما دلالة الاستفهام في تذكيرهما بعداوة الشيطان؟","answer":"يقرر التحذير الذي سبق لهما ويكشف أن الوقوع لم يكن لغياب التنبيه، بل مع معرفة عداوة من أغواهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص71، تحت «دلالة الاستفهام المجازي في ﴿وأقل لكما إن الشيطان لكما عدو﴾»","url":""}]},{"id":"s7-1570","number":1570,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا جُمع في العتاب بين النهي عن الشجرة والتحذير من الشيطان؟","answer":"لأن الأول يقرر موضع المخالفة، والثاني يقرر سبب الوقوع فيها؛ فاجتمع بيان الحكم وبيان العدو الذي زين مخالفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص72، تحت «دلالة عطف ﴿وأقل لكما﴾ على جملة الاستفهام»","url":""}]},{"id":"s7-120","number":120,"surah":7,"verses":[23],"references":[{"surah":7,"verses":[23]}],"verseLabel":"الأعراف: 23","question":"لماذا افتتح آدم وزوجه اعترافهما بالنداء: ﴿ربنا﴾؟","answer":"افتتحا به إظهارًا للعبودية والافتقار، وتهيئةً للاعتراف وطلب المغفرة من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص76، تحت «نكتة النداء بـ﴿ربنا﴾»","url":""}]},{"id":"s7-1571","number":1571,"surah":7,"verses":[23],"references":[{"surah":7,"verses":[23]}],"verseLabel":"الأعراف: 23","question":"ما دلالة إضافة الرب إليهما في قولهما: ﴿ربنا﴾؟","answer":"تستحضر الإضافة رعاية الله وتربيته ورحمته، فيتوسلان بربوبيتهما مع إقرارهما بظلم النفس وحاجتهما إلى المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص76، تحت «مناسبة الإضافة في قوله تعالى: ﴿ربنا﴾»","url":""}]},{"id":"s7-121","number":121,"surah":7,"verses":[23],"references":[{"surah":7,"verses":[23]}],"verseLabel":"الأعراف: 23","question":"لماذا سمّى آدم وزوجه ذنبهما ظلمًا للنفس؟","answer":"لأن تبعة المعصية عائدة عليهما؛ فقد أوقعا نفسيهما في الحرمان والتعب بعد نعمة الجنة. وفي هذا التعبير اعتراف بأن ضرر الذنب يصيب صاحبه، لا أنه يضر الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص77، تحت «مناسبة تسمية الذنب ظلمًا للنفس»","url":""}]},{"id":"s7-1572","number":1572,"surah":7,"verses":[23],"references":[{"surah":7,"verses":[23]}],"verseLabel":"الأعراف: 23","question":"لماذا قالا: ﴿ظلمنا أنفسنا﴾ بالجمع مع أنهما اثنان؟","answer":"جيء بالجمع بدل التثنية إشعارًا بأن قلبيهما أصابهما أثر المعصية، ولأن جمع النفس شائع عند الإضافة إلى مثنى، وفيه استحضار لما دخلهما من ندم واضطراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص77، تحت «سر التعبير بالجمع في لفظ ﴿أنفسنا﴾ مع أنهما مثنى»","url":""}]},{"id":"s7-122","number":122,"surah":7,"verses":[23],"references":[{"surah":7,"verses":[23]}],"verseLabel":"الأعراف: 23","question":"ما سرّ تقديم المغفرة على الرحمة: ﴿وإن لم تغفر لنا وترحمنا﴾؟","answer":"قُدمت المغفرة لأنها إزالة أثر الذنب، ثم تأتي الرحمة بتحصيل الخير والفضل؛ فالتخلية قبل التحلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص79–80، تحت «مناسبة الترتيب بين المغفرة والرحمة في السياق»","url":""}]},{"id":"s7-123","number":123,"surah":7,"verses":[23],"references":[{"surah":7,"verses":[23]}],"verseLabel":"الأعراف: 23","question":"ما أثر توكيد قولهما: ﴿لنكونن من الخاسرين﴾؟","answer":"يقرر التوكيد يقينهما بأن الخسران لازم إن لم تتداركهما مغفرة الله ورحمته، ويكشف صدق خوفهما وشدة افتقارهما إلى النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص81، تحت «دلالة نتائج التأكيد في قوله تعالى: ﴿لنكونن﴾»","url":""}]},{"id":"s7-124","number":124,"surah":7,"verses":[24],"references":[{"surah":7,"verses":[24]}],"verseLabel":"الأعراف: 24","question":"لماذا جاء أمر الهبوط بصيغة الجمع: ﴿اهبطوا﴾ بعد خطاب آدم وزوجه؟","answer":"يشمل الجمع آدم وحواء وإبليس، ويدخل فيه من يتبعهم بحسب توجيه السياق؛ فانتقل الخطاب من الزوجين إلى أطراف العداوة التي ستعيش في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص87، تحت «معنى واو الجمع في قوله تعالى: ﴿اهبطوا﴾»","url":""}]},{"id":"s7-125","number":125,"surah":7,"verses":[24],"references":[{"surah":7,"verses":[24]}],"verseLabel":"الأعراف: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿بعضكم لبعض عدو﴾، فأفرد ﴿عدو﴾؟","answer":"أفرد لأنه مصدر أو اسم جنس يصدق على الواحد والجمع، أو لأن كل بعض عدو للبعض الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص90، تحت «سر التعبير بالمفرد ﴿عدو﴾ دون (أعداء)»","url":""}]},{"id":"s7-126","number":126,"surah":7,"verses":[24],"references":[{"surah":7,"verses":[24]}],"verseLabel":"الأعراف: 24","question":"ما سرّ تقديم الاستقرار على المتاع: ﴿مستقر ومتاع إلى حين﴾؟","answer":"قدم المستقر لأنه أعم؛ فهو يشمل مكث الإنسان حيًا في الأرض ومكثه بعد الموت، أما المتاع فانتفاع بملذات الحياة ينتهي بانتهائها. فالتقديم يجري من العام إلى الخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص92، تحت «سر تقديم (المستقر) على (المتاع)»","url":""}]},{"id":"s7-127","number":127,"surah":7,"verses":[24],"references":[{"surah":7,"verses":[24]}],"verseLabel":"الأعراف: 24","question":"ما دلالة حرف الغاية في قوله: ﴿ومتاع إلى حين﴾؟","answer":"تجعل ﴿إلى﴾ الاستقرار والمتاع منتهيين إلى أجل، فتقطع توهم الدوام وتذكر بأن الانتفاع في الدنيا محدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص92، تحت «نكتة التعبير بحرف الجر في: ﴿إلى حين﴾»","url":""}]},{"id":"s7-1573","number":1573,"surah":7,"verses":[24],"references":[{"surah":7,"verses":[24]}],"verseLabel":"الأعراف: 24","question":"لماذا قُيّد المتاع بلفظ ﴿حين﴾ من غير تحديد الأجل؟","answer":"لأن ﴿حين﴾ يصدق على زمن يطول أو يقصر، فيشمل اختلاف آجال الأفراد وانتهاء الدنيا بقيام الساعة، مع بقاء الأجل مستورًا عن الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص93، تحت «مناسبة التعبير بلفظ ﴿حين﴾»","url":""}]},{"id":"s7-128","number":128,"surah":7,"verses":[24],"references":[{"surah":7,"verses":[24]}],"verseLabel":"الأعراف: 24","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿اهبطوا بعضكم لبعض عدو﴾ بصيغة الجمع، وفي طه: ﴿اهبطا منها جميعًا بعضكم لبعض عدو﴾ بصيغة التثنية؟","answer":"في الأعراف يتوجه الجمع إلى آدم وزوجه وذريتهما، ويدخل إبليس في خطاب الهبوط بحسب توجيه السياق. وفي طه حملت التثنية على فريقين متواجهين: آدم وذريته، وإبليس وأعوانه؛ فناسبت التثنية جمع كل طرف مع من يتبعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص88، تحت «سر التعبير بالجمع هنا، وبالمثنى في سورة طه»","url":""}]},{"id":"s7-129","number":129,"surah":7,"verses":[25],"references":[{"surah":7,"verses":[25]}],"verseLabel":"الأعراف: 25","question":"لماذا قُدّم ﴿فيها﴾ في قوله: ﴿فيها تحيون﴾؟","answer":"للاهتمام بالأرض التي جُعلت موضع حياة بني آدم واستقرارهم، ولإبراز اختصاص حياتهم الدنيوية بها قبل الانتقال إلى الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص97، تحت «بلاغة تقديم الجار والمجرور في جملة ﴿فيها تحيون﴾»","url":""}]},{"id":"s7-1574","number":1574,"surah":7,"verses":[25],"references":[{"surah":7,"verses":[25]}],"verseLabel":"الأعراف: 25","question":"لماذا قُدّم ﴿فيها﴾ في قوله: ﴿وفيها تموتون﴾؟","answer":"للاهتمام بالأرض بوصفها موضع الموت كما كانت موضع الحياة، وليكتمل نسق ارتباط الإنسان بها قبل إخراجه منها للبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص99، تحت «بلاغة تقديم الجار والمجرور في قوله تعالى: ﴿وفيها تموتون﴾»","url":""}]},{"id":"s7-130","number":130,"surah":7,"verses":[25],"references":[{"surah":7,"verses":[25]}],"verseLabel":"الأعراف: 25","question":"لم عبر بالحياة في ﴿فيها تحيون﴾ بعد ذكر المعايش والاستقرار في الأرض؟","answer":"لأن الحياة أعم من المعيشة؛ فهي الأصل الذي يكون معه الانتفاع بالمعايش. وبعد بيان مكان الاستقرار جاء هذا التعبير ليبين شمول الأرض للحياة نفسها، ثم لما يليها من الموت والبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص98–99، تحت «سر التعبير بالحياة في قوله تعالى: ﴿فيها تحيون﴾»","url":""}]},{"id":"s7-131","number":131,"surah":7,"verses":[25],"references":[{"surah":7,"verses":[25]}],"verseLabel":"الأعراف: 25","question":"لماذا قيل: ﴿ومنها تخرجون﴾، لا: وفيها تبعثون؟","answer":"لأن الإخراج يصور البعث خروجًا محسوسًا من الأرض بعد الدفن، فيجعل مشهد انبعاث الأجساد من القبور حاضرًا في العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص100، تحت «سر التعبير بالإخراج في قوله تعالى: ﴿ومنها تخرجون﴾»","url":""}]},{"id":"s7-1575","number":1575,"surah":7,"verses":[25],"references":[{"surah":7,"verses":[25]}],"verseLabel":"الأعراف: 25","question":"كيف تلخص الأفعال ﴿تحيون﴾ و﴿تموتون﴾ و﴿تخرجون﴾ رحلة الإنسان؟","answer":"تجمع الأفعال أطوار الإنسان في مقابلة موجزة: حياة في الأرض، ثم موت فيها، ثم خروج منها للبعث؛ فتربط البداية والنهاية والمصير بمشهد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص100، تحت «بديع المقابلة بين الأفعال ﴿تحيون﴾ و﴿تموتون﴾ و﴿تخرجون﴾»","url":""}]},{"id":"s7-132","number":132,"surah":7,"verses":[25],"references":[{"surah":7,"verses":[25]}],"verseLabel":"الأعراف: 25","question":"لماذا بُني ﴿تخرجون﴾ للمجهول؟","answer":"بُني للمجهول للاهتمام بحدث الخروج وهوله، وللعلم بأن مخرِجهم هو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص100–101، تحت «القراءات القرآنية وأثرها في ضبط لفظ ﴿تخرجون﴾»","url":""}]},{"id":"s7-133","number":133,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"لماذا افتتح النداء بـ﴿يا بني آدم﴾ بعد قصة أبويهم؟","answer":"جاء النداء عقب قصة أبويهم لينقل العبرة إلى ذريتهما ويحذرهم من فتنة الشيطان، ويذكرهم بنعمة اللباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص104–105، تحت «بلاغة النداء في قوله تعالى: ﴿يا بني آدم﴾»","url":""}]},{"id":"s7-134","number":134,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"لماذا عبّر عن خلق اللباس بقوله: ﴿أنزلنا عليكم لباسًا﴾؟","answer":"لأن أسبابه من رزق الله المنزل من السماء كالمطر الذي ينبت مواد اللباس، ولأن إظهاره للناس بقدرة الله يشبه إنزال النعمة عليهم. وفي التعبير تعظيم للمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص107، تحت «التعبير عن اللباس بالإنزال، مع أنه من الأرض في الظاهر لنا»","url":""}]},{"id":"s7-135","number":135,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"لماذا عُطف ﴿ريشًا﴾ على اللباس الذي يواري السوأة؟","answer":"للتفريق بين الضرورة والزينة: لباس يستر العورة، وريش يتجمل به الإنسان ويتسع به عيشه. فالعطف يجمع النعمتين مع اختلاف وظيفتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص111، تحت «دلالة العطف في قوله تعالى: ﴿وريشًا﴾»","url":""}]},{"id":"s7-136","number":136,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"لماذا سُميت الزينة ﴿ريشًا﴾؟","answer":"الريش في الأصل كسوة الطائر وزينته، فاستعير لما يتجمل به الإنسان من لباس ومال وهيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص110–111، تحت «بلاغة الاستعارة في قوله تعالى: ﴿وريشًا﴾»","url":""}]},{"id":"s7-137","number":137,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"كيف تكون التقوى لباسًا؟","answer":"شبه تمكن التقوى من صاحبها وملازمتها له بملابسة الثوب للإنسان وإحاطته به؛ فاللباس يستر البدن، والتقوى تستر صاحبها من فضائح الذنوب وعواقبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص112، تحت «بلاغة الاستعارة في قوله تعالى: ﴿ولباس التقوى﴾»","url":""}]},{"id":"s7-1576","number":1576,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"كيف يحمل قوله: ﴿ولباس التقوى ذلك خير﴾ حثًا من غير صيغة أمر؟","answer":"إخباره بأن لباس التقوى خير يتضمن الدعوة إلى تحصيله؛ فبيان خيريته يحرك الرغبة فيه ويحث على التقوى بأسلوب الخبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص113، تحت «إشعار الجملة الخبرية بالطلب»","url":""}]},{"id":"s7-138","number":138,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"ما أثر الإتيان باسم الإشارة في قوله: ﴿ولباس التقوى ذلك خير﴾؟","answer":"يُبرز اسم الإشارة لباس التقوى وينوه به، كأنه شيء حاضر متميز يُلفت إليه النظر ليُعرف قدره وخيريته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص114، تحت «دلالة الإتيان باسم الإشارة في قوله تعالى: ﴿ذلك خير﴾»","url":""}]},{"id":"s7-1577","number":1577,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"لماذا أشير إلى لباس التقوى باسم البعيد ﴿ذلك﴾؟","answer":"ليس المراد بعدًا مكانيًا، بل تعظيم رتبته وعلو منزلته؛ فصيغة البعد ترفع شأن التقوى فوق الزينة الظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص112، تحت «دلالة التعبير بصيغة البعد لاسم الإشارة ﴿ذلك﴾»","url":""}]},{"id":"s7-139","number":139,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"لماذا خُتمت آية اللباس بقوله: ﴿لعلهم يذكرون﴾؟","answer":"ليتذكر بنو آدم نعمة الستر وقصة أبويهم، فيقابلوا النعمة بالشكر ويختاروا لباس التقوى ويحذروا فتنة الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص118، تحت «سر اختيار التعبير بالتذكر ﴿لعلهم يذكرون﴾»","url":""}]},{"id":"s7-140","number":140,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"لماذا قيل لبني آدم: ﴿لا يفتننكم الشيطان﴾؟","answer":"ظاهر اللفظ نهي للشيطان عن إيقاع الفتنة، والمقصود نهي بني آدم عن تمكينه منها باتباعه. فتوجيه النهي إلى سبب الفتنة يبالغ في التحذير منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص122، تحت «براعة التعبير بقوله تعالى: ﴿لا يفتننكم﴾ دون غيره»","url":""}]},{"id":"s7-141","number":141,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿كما أخرج أبويكم من الجنة﴾، مع أن المخرج حقيقة هو الله؟","answer":"نُسب الإخراج إليه سببيًا؛ لأنه أغراهما بالأكل فكان فعله سبب الخروج، أما المخرج حقيقة فهو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص126، تحت «بلاغة المجاز العقلي في قوله: ﴿أخرج أبويكم من الجنة﴾»","url":""}]},{"id":"s7-142","number":142,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"لماذا وصف آدم وحواء بـ﴿أبويكم﴾؟","answer":"سُميا أبويهم لأن البشر جميعًا من ذريتهما، وفي التعبير استثارة لعاطفة البنوة وأخذ العبرة من تجربتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص126، تحت «سر العدول عن لفظي (آدم) و(حواء) إلى لفظ ﴿أبويكم﴾»","url":""}]},{"id":"s7-143","number":143,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما أثر المضارع في قوله: ﴿ينزع عنهما لباسهما﴾؟","answer":"يستحضر المضارع صورة النزع كأنها تقع أمام السامع، ويجدد التحذير من فعل الشيطان وطرائق فتنته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص126، تحت «نكتة التعبير بصيغة المضارع ﴿ينزع﴾»","url":""}]},{"id":"s7-1578","number":1578,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"لماذا اختير لفظ ﴿ينزع﴾ في وصف سلب اللباس؟","answer":"لأن النزع يصور سلب ستر كان ثابتًا وملازمًا، وفيه معنى الشدة وكشف ما كان مصونًا، فيقوي صورة الفتنة وعاقبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص127–128، تحت «سر التعبير: ﴿ينزع عنهما لباسهما﴾»","url":""}]},{"id":"s7-1579","number":1579,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما دلالة اللام في قوله: ﴿ليريهما سوآتهما﴾؟","answer":"تحتمل لام العاقبة؛ لأن كشف السوءات كان نتيجة الإغواء، وتحتمل التعليل بإسناد غاية الفعل إلى المتسبب فيه. وعلى الوجهين تشتد صورة التحذير من الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص128، تحت «دلالة اللام في قوله تعالى: ﴿ليريهما﴾»","url":""}]},{"id":"s7-144","number":144,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"لماذا أُكد الخبر: ﴿إنه يراكم هو وقبيله﴾؟","answer":"لتقوية التحذير من عدو يراقب بني آدم وهم لا يرونه، حتى يكون حذرهم دائمًا ولا يغفلوا عن مداخل فتنته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص129، تحت «دلالة تأكيد رؤية الشيطان وقبيله لبني آدم»","url":""}]},{"id":"s7-1580","number":1580,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما دلالة ذكر ﴿هو﴾ في قوله: ﴿يراكم هو وقبيله﴾؟","answer":"يؤكد الضمير المستتر في ﴿يراكم﴾، ويعيد التنبيه إلى أن الشيطان الذي فتن الأبوين هو نفسه المتربص بذريتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص130، تحت «دلالة ذكر الضمير ﴿هو﴾ في قوله تعالى: ﴿هو وقبيله﴾»","url":""}]},{"id":"s7-145","number":145,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿من حيث لا ترونهم﴾، لا: وأنتم لا ترونهم؟","answer":"﴿من حيث﴾ تدل على جهة ووجه خفي لا تقع منه رؤيتهم أصلًا، فهي أبلغ من مجرد الحال ﴿وأنتم لا ترونهم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص130–131، تحت «سر مجيء الظرف، والتعبير بعدم الرؤية في ﴿لا ترونهم﴾»","url":""}]},{"id":"s7-146","number":146,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"لماذا أعقب التحذير من الشيطان بقوله: ﴿إنا جعلنا الشياطين أولياء للذين لا يؤمنون﴾؟","answer":"ليبين أن ولاية الشياطين ليست أمرًا منفصلًا عن اختيار الإنسان؛ فهي عقوبة توافق إعراض من لا يؤمن، وتحذير من أن يقود ترك الإيمان إلى قبول ولايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص132–133، تحت «بلاغة موقع قوله تعالى: ﴿إنا جعلنا الشياطين أولياء﴾»","url":""}]},{"id":"s7-1581","number":1581,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما دلالة وصف أولياء الشياطين بأنهم ﴿الذين لا يؤمنون﴾؟","answer":"تعرّفهم الصلة بالسبب الذي هيأهم لهذه الولاية؛ فعدم الإيمان هو الأصل الذي يفتح باب اتباع الشيطان وقبول سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص133، تحت «مناسبة مجيء الاسم الموصول وصلته»","url":""}]},{"id":"s7-1582","number":1582,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما أثر تذييل الآية ببيان أولياء الشياطين؟","answer":"يعمم المعنى ويقرره: الشياطين أولياء لمن لا يؤمنون. فيغدو ختام الآية قاعدة تحذيرية كلية بعد تصوير خطرهم الخفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص134، تحت «حسن التذييل في آخر الآية، وأثره في المعنى»","url":""}]},{"id":"s7-147","number":147,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"لماذا جاء الشرط بالماضي في قوله: ﴿وإذا فعلوا فاحشة﴾؟","answer":"جيء بالماضي لتصوير الفاحشة أمرًا متحقق الوقوع منهم ومتكررًا حتى صار عادة معروفة، لا مجرد احتمال بعيد؛ ولذلك بُني الرد على واقع فعلوه واحتجوا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص136، تحت «سر التعبير بالفعل الماضي في الشرط ﴿فعلوا﴾»","url":""}]},{"id":"s7-1583","number":1583,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"لماذا قيل: ﴿فعلوا فاحشة﴾، لا: عملوا فاحشة؟","answer":"الفعل أعم من العمل، وقد يقع من غير نظر في القصد والعاقبة؛ فاختياره يصور اندفاعهم إلى القبيح من غير تدبر، بخلاف العمل الذي يكثر اقترانه بالقصد والمعالجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص137، تحت «سر التعبير بـ﴿فعلوا﴾ دون عملوا»","url":""}]},{"id":"s7-1584","number":1584,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"كيف سوّغ المشركون فعل الفاحشة لأنفسهم؟","answer":"جمعوا حجتين باطلتين: تقليد الآباء، ثم الافتراء بأن الله أمرهم بها. وعطف الثانية يكشف انتقالهم من اتباع الموروث إلى نسبة التشريع نفسه إلى الله، وهو أشد في البطلان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص141، تحت «مناسبة العطف في قوله تعالى: ﴿والله أمرنا بها﴾»","url":""}]},{"id":"s7-148","number":148,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"ما دلالة تقديم ﴿عليها﴾ في قولهم: ﴿وجدنا عليها آباءنا﴾؟","answer":"قُدّم ﴿عليها﴾ للاهتمام بالحال التي وجدوا آباءهم ملازمين لها، وتصوير شدة تعلقهم بالفاحشة وتقليدهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص140، تحت «نكتة تقديم قوله تعالى: ﴿عليها﴾ على ﴿آباءنا﴾»","url":""}]},{"id":"s7-149","number":149,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"كيف أبطل القرآن احتجاجهم بأن الله أمرهم بالفاحشة؟","answer":"رد الدعوى من أصلها بنفي أن يأمر الله بالفحشاء، ثم واجههم بالاستفهام المنكر عن القول عليه بلا علم؛ فجمع بين إبطال المدعى وكشف أن حجتهم افتراء لا برهان له.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص144، تحت «بلاغة الاحتجاج في سياق الآية الكريمة»","url":""}]},{"id":"s7-1585","number":1585,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"كيف انتظمت جملتا ﴿إن الله لا يأمر بالفحشاء﴾ و﴿أتقولون على الله ما لا تعلمون﴾ في جواب واحد؟","answer":"دخلتا معًا في مقول ﴿قل﴾: الأولى تقرر الحق الذي ينسف دعواهم، والثانية تنكر عليهم جرأتهم. فتم الرد بإثبات المبدأ ثم إلزامهم بنتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص146، تحت «سر مجيء جملة الاستفهام مع سابقتها مقول قول واحد»","url":""}]},{"id":"s7-150","number":150,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"لماذا اختيرت ﴿الفحشاء﴾ في الرد، لا ﴿فاحشة﴾ كما في أول الآية؟","answer":"عُرفت ﴿الفحشاء﴾ للجنس، فنفى أن يأمر الله بأي شيء من جنس القبائح؛ وهو أعم وأقوى من إعادة فاحشة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص144، تحت «سر التعبير بالإظهار في مقام الإضمار، فقال: ﴿بالفحشاء﴾»","url":""}]},{"id":"s7-151","number":151,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"ما دلالة الاستفهام في قوله: ﴿أتقولون على الله ما لا تعلمون﴾؟","answer":"خرج الاستفهام إلى التوبيخ والإنكار؛ إذ لا حجة لهم على نسبة هذا التشريع إلى الله، فجعل مجرد نطقهم به موضع استنكار شديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص145، تحت «بلاغة الاستفهام المجازي في قوله تعالى: ﴿أتقولون﴾»","url":""}]},{"id":"s7-1586","number":1586,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"ماذا أفاد التعبير بـ﴿ما لا تعلمون﴾ في وصف قولهم على الله؟","answer":"عمم الموصول كل قول لا يستند إلى علم، وجعل جهلهم بالحكم نفسه حجة عليهم؛ فمن لا يعلم لا يملك أن ينسب إلى الله أمرًا أو تحريمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص146، تحت «دلالة ﴿ما﴾ في قوله تعالى: ﴿ما لا تعلمون﴾»","url":""}]},{"id":"s7-152","number":152,"surah":7,"verses":[29],"references":[{"surah":7,"verses":[29]}],"verseLabel":"الأعراف: 29","question":"لماذا قابل الفحشاء بقوله: ﴿قل أمر ربي بالقسط﴾؟","answer":"القسط ضد الفحشاء والظلم، فجاء الأمر به ردًا جامعًا يثبت أن تشريع الله قائم على العدل والاستقامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص151، تحت «نكتة التعبير بلفظ (القسط)»","url":""}]},{"id":"s7-153","number":153,"surah":7,"verses":[29],"references":[{"surah":7,"verses":[29]}],"verseLabel":"الأعراف: 29","question":"ما الذي تصوره استعارة الإقامة في قوله: ﴿وأقيموا وجوهكم﴾؟","answer":"استعيرت الإقامة للتوجه المستقيم إلى عبادة الله مع الثبات والمداومة؛ فالمطلوب ليس حركة الوجه وحدها، بل استقامة العبد في قصده وعمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص153، تحت «بلاغة الاستعارة في قوله تعالى: ﴿وأقيموا﴾»","url":""}]},{"id":"s7-1587","number":1587,"surah":7,"verses":[29],"references":[{"surah":7,"verses":[29]}],"verseLabel":"الأعراف: 29","question":"هل المراد بالوجوه في ﴿وأقيموا وجوهكم﴾ ظاهر الوجه فقط؟","answer":"يحتمل أن يراد بالوجه الذات كلها، بذكر أشرف الجزء وإرادة الكل، وأن يراد به القصد والوجهة. وفي الحالين ينتقل التعبير من الجارحة إلى إخلاص الإنسان كله لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص154، تحت «لفظ ﴿وجوهكم﴾ بين المجاز المرسل والاستعارة»","url":""}]},{"id":"s7-154","number":154,"surah":7,"verses":[29,31],"references":[{"surah":7,"verses":[29,31]}],"verseLabel":"الأعراف: 29؛ الأعراف: 31","question":"ما سر التعبير بقوله: ﴿عند كل مسجد﴾؟","answer":"يحتمل المسجد موضع الصلاة أو وقتها أو السجود نفسه، فيعم الأمر كل حال عبادة. ولفظ ﴿عند﴾ يربط إقامة الوجه بمقام التوجه إلى الله، لا ببناء مخصوص وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص154–155، تحت «دلالة قوله تعالى: ﴿عند كل مسجد﴾»","url":""}]},{"id":"s7-155","number":155,"surah":7,"verses":[29],"references":[{"surah":7,"verses":[29]}],"verseLabel":"الأعراف: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿وادعوه مخلصين له الدين﴾، فقدم ﴿له﴾؟","answer":"قُدّم ﴿له﴾ للاختصاص: يكون الدين والدعاء خالصين لله وحده، لا نصيب فيهما لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص156، تحت «دلالة تقديم ﴿له﴾ في السياق»","url":""}]},{"id":"s7-156","number":156,"surah":7,"verses":[29],"references":[{"surah":7,"verses":[29]}],"verseLabel":"الأعراف: 29","question":"لماذا شُبه البعث بالبدء في قوله: ﴿كما بدأكم تعودون﴾؟","answer":"يجعل التشبيه الخلق الأول دليلًا مشاهدًا على الإعادة؛ فمن أنشأهم أول مرة قادر على بعثهم. وبذلك يقرب الغيب إلى العقل بما يقر به المخاطب من أصل وجوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص157–158، تحت «بلاغة التشبيه في ﴿كما بدأكم﴾»","url":""}]},{"id":"s7-157","number":157,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"لماذا أسند الهدى إلى الله في ﴿فريقًا هدى﴾ ولم تسند إليه الضلالة؟","answer":"أسند الهدى إلى الله لأنه فضل ومنة، وحُذف إسناد الضلالة إليه أدبًا، مع بيان سببها في اختيارهم ولاية الشياطين؛ فلا يوهم التعبير أنهم أضلوا بلا مسؤولية منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص162، تحت «نكتة إسناد (الهدى) إلى الله دون (الضلالة)»","url":""}]},{"id":"s7-158","number":158,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"ما سرّ تقديم المفعول ﴿فريقًا﴾ في الجملتين؟","answer":"على إعراب ﴿فريقًا﴾ مفعولًا مقدمًا، يبرز التقديم اختصاص فريق بالهداية، ويشعر بأن الفريق المقابل لم يرد هدايته، ثم تصرح الجملة التالية بمآله. وبذلك يظهر التقسيم والتقابل قبل تفصيل حكم كل فريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص161–162، تحت «الوقف القرآني وتعدد المعنى»","url":""}]},{"id":"s7-159","number":159,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿حق عليهم الضلالة﴾، لا: أضلهم؟","answer":"﴿حق﴾ تفيد ثبوت الضلالة واستحقاقها ولزومها لهم بعد أسبابها، لا نسبة الإضلال إليهم بلا بيان لمسؤوليتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص162–163، تحت «سر اختلاف التعبير بين ﴿حق عليهم الضلالة﴾ مقابل الهداية»","url":""}]},{"id":"s7-160","number":160,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"لماذا أكدت علة ضلالهم بـ﴿إنهم اتخذوا الشياطين أولياء﴾؟","answer":"جاء التوكيد ليقرر السبب الحقيقي لضلالهم ويربط الجزاء باختيارهم؛ فلم تقع الضلالة اعتباطًا، بل ثبتت عليهم لاتخاذهم الشياطين أولياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص165، تحت «دلالة التعبير بـ(إن) في سياق الآية الكريمة»","url":""}]},{"id":"s7-1588","number":1588,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"ماذا يكشف لفظ ﴿اتخذوا﴾ في وصف ولايتهم للشياطين؟","answer":"يدل الاتخاذ على قصد وتمكن ومداومة؛ فهم لم تعرض لهم وسوسة عابرة، بل جعلوا الشياطين أولياء يتبعونهم، ولذلك استحقوا الضلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص165، تحت «دلالة التعبير بلفظ ﴿اتخذوا﴾ دون غيره»","url":""}]},{"id":"s7-1589","number":1589,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"ما الذي تضيفه عبارة ﴿من دون الله﴾ إلى وصف ولايتهم؟","answer":"تكشف أنهم لم يكتفوا باتباع الشياطين، بل آثروهم على ولاية الله وأعرضوا عن هدايته؛ فاجتمع في فعلهم اتخاذ الباطل وترك الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص165، تحت «دلالة الصفة في قوله تعالى: ﴿من دون الله﴾»","url":""}]},{"id":"s7-161","number":161,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"لماذا خُتمت بـ﴿ويحسبون أنهم مهتدون﴾؟","answer":"يجمع الختام بين وقوعهم في الضلال واعتقادهم أنهم على الهدى؛ فهم يفعلون القبائح ويحسبونها طاعة وقربى. وبالجملة الاسمية في ﴿أنهم مهتدون﴾ يظهر رسوخ هذا الوهم في أنفسهم، فتشتد صورة ضلالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص167–168، تحت «سر ختام الآية بقوله تعالى: ﴿ويحسبون أنهم مهتدون﴾»","url":""}]},{"id":"s7-162","number":162,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"لماذا جدد النداء بقوله: ﴿يا بني آدم﴾؟","answer":"جدد النداء لاستقلال الوصية الجديدة وعظمها، وليستحضر المخاطبون انتسابهم إلى آدم بعد التحذير من فتنة الشيطان؛ فيتهيؤوا لسماع ما يحفظ كرامتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص171–172، تحت «نكتة إعادة النداء»","url":""}]},{"id":"s7-163","number":163,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"لماذا قيل: ﴿خذوا زينتكم﴾، لا: البسوا ثيابكم؟","answer":"ناسب ﴿خذوا﴾ حال من كانوا يلقون ثيابهم ويتعرون للطواف؛ فأمروا باستصحابها وارتدائها. واللفظ أوسع من مجرد اللبس، إذ يشمل إعداد الزينة للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص172–173، تحت «بلاغة التعبير بالأخذ دون فعل اللبس»","url":""}]},{"id":"s7-1590","number":1590,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"لماذا سميت الثياب هنا زينة، ولم تسم لباسًا؟","answer":"الزينة أبعث على الرغبة في الستر وتحسين الهيئة؛ فخوطبوا بما يحبب إليهم التجمل عند العبادة، بدل الاقتصار على معنى ستر العورة الذي يؤديه لفظ اللباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص174–175، تحت «سر التعبير بلفظ الزينة دون اللباس»","url":""}]},{"id":"s7-164","number":164,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"لماذا أضاف الزينة إليهم: ﴿زينتكم﴾؟","answer":"تنسب الزينة إلى المخاطبين بوصفها ملكًا لهم وفي متناولهم، فتحثهم على استعمالها ولا تترك لهم عذرًا في التخلي عنها. وفي الإضافة تحفيز وترغيب في حسن الهيئة عند الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص174–175، تحت «دلالة إضافة لفظ الزينة لكاف الخطاب»","url":""}]},{"id":"s7-166","number":166,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"كيف جمع نظم الآية بين أخذ الزينة والأكل والشرب في عبارة موجزة؟","answer":"ذكر أخذ الزينة أولًا فدل على اللباس، وذكر الأكل والشرب بعده فدل على سائر الانتفاع المباح؛ فجمع حاجات الظاهر والبدن، وحذف من كل جانب ما يدل عليه الآخر في نظم موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص176، تحت «بديع فن الاحتباك»","url":""}]},{"id":"s7-167","number":167,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"ما سر عطف ﴿ولا تسرفوا﴾ على إباحة الأكل والشرب؟","answer":"جاء النهي عقب الأمر حتى تبقى الإباحة في حد الاعتدال؛ فالانتفاع بالنعمة مشروع، أما مجاوزة الحاجة والتبذير فتحول الانتفاع إلى ضرر ومعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص177–178، تحت «دلالة عطف النهي على الأمر»","url":""}]},{"id":"s7-168","number":168,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"لماذا زجر عن الإسراف بنفي المحبة في ﴿إنه لا يحب المسرفين﴾؟","answer":"نفي المحبة يحذر من الإسراف مع إبقاء باب الرجاء، ويستميل المخاطب إلى طلب محبة الله بالاعتدال. فهو أنسب بمقام الإرشاد من الاقتصار على إثبات الكراهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص178–179، تحت «نكتة إيثار نفي الحب على إثبات الكراهية»","url":""}]},{"id":"s7-169","number":169,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"ما دلالة الاستفهام في قوله: ﴿قل من حرم زينة الله﴾؟","answer":"هو استفهام إنكاري يطلب منهم سند التحريم فلا يجدونه؛ فيبطل حق البشر في منع ما أباحه الله، ويكشف أن تشريعهم قائم على الهوى لا البرهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص184–185، تحت «غرض الاستفهام»","url":""}]},{"id":"s7-170","number":170,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"لماذا أضيفت الزينة إلى الله: ﴿زينة الله﴾؟","answer":"إضافتها إليه لأنها خلقه وعطيته وتشريعه لعباده، فلا يملك غيره تحريمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص185–186، تحت «دلالات إضافة ﴿زينة﴾ إلى لفظ الجلالة»","url":""}]},{"id":"s7-171","number":171,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"ما سر التعبير بقوله: ﴿التي أخرج لعباده﴾؟","answer":"يصور الإخراج إبراز الزينة من أسبابها وإظهارها للعباد بعد خفائها في موادها؛ فيشعر بالعناية والتيسير، ويذكرهم بأن وصولها إليهم من تدبير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص186، تحت «فائدة استعمال الفعل ﴿أخرج﴾»","url":""}]},{"id":"s7-172","number":172,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"لماذا جمع بين الزينة و﴿الطيبات من الرزق﴾؟","answer":"الزينة تصلح الظاهر وتجمله، والطيبات تقوم البدن وتلذه؛ فجمع نوعي النعمة ودفع تحريم المشركين لهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص187–188، تحت «نكتة عطف الطيبات على الزينة»","url":""}]},{"id":"s7-173","number":173,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"كيف تكون الزينة والطيبات ﴿للذين آمنوا﴾ مع انتفاع الكافرين بها في الدنيا؟","answer":"اللام للاختصاص الأصلي والإباحة؛ فالمؤمنون هم المقصودون بهذه النعم لأنهم يشكرون المنعم ويستعملونها في طاعته، وإن شاركهم غيرهم فيها زمن الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص190–191، تحت «معنى اللام ودلالتها»","url":""}]},{"id":"s7-1591","number":1591,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"لماذا ذكر المؤمنون وحدهم في الدنيا مع أن غيرهم يشاركهم في الزينة والطيبات؟","answer":"اكتفى بذكر المؤمنين تنبيهًا إلى أنهم أهل الانتفاع المقصود بهذه النعم، وحذف ذكر غيرهم مع فهم مشاركتهم العارضة في الدنيا؛ ثم يخلص النعيم للمؤمنين في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص191، تحت «سر حذف المعطوف»","url":""}]},{"id":"s7-174","number":174,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"ما الذي يفيده وصف النعم بأنها ﴿خالصة يوم القيامة﴾؟","answer":"تفيد أنها خاصة بالمؤمنين يوم القيامة لا يشاركهم فيها الكافرون، وأنها نقية من منغصات الدنيا وكدرها؛ فيجتمع خلوص الملك وخلوص النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص182، تحت «شرح المفردات: ﴿خالصة﴾»","url":""}]},{"id":"s7-175","number":175,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"ما وجه التشبيه في قوله: ﴿كذلك نفصل الآيات﴾؟","answer":"شبه هذا البيان المفصل للزينة والطيبات بما يجري عليه بيان سائر الأحكام؛ فكما اتضح الحكم هنا تتضح الآيات بالحجة والتفصيل، ليزول الاشتباه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص192، تحت «بلاغة التشبيه المرسل المجمل»","url":""}]},{"id":"s7-1592","number":1592,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"ماذا تفيد اللام في قوله: ﴿لقوم يعلمون﴾؟","answer":"تفيد أن أهل العلم هم المنتفعون بهذا التفصيل والمقصودون به؛ لأنهم يتلقون الآيات بفهم وقبول، لا أن البيان محجوب عمن سواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص192، تحت «فائدة اللام ودلالتها»","url":""}]},{"id":"s7-1593","number":1593,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"لماذا خُص أهل العلم في قوله: ﴿لقوم يعلمون﴾؟","answer":"لأن العلم أثبت وأرسخ من الفهم العابر، وهو الذي يحمل صاحبه على تمييز الحلال من الحرام والعمل بالدليل؛ فناسب ختام آيات الأحكام.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص193، تحت «سر التعبير بالعلم دون الفهم»","url":""}]},{"id":"s7-176","number":176,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"ما سر القصر في قوله: ﴿إنما حرم ربي﴾ بعد سؤال ﴿من حرم﴾؟","answer":"هو قصر إضافي يرد على المشركين: المحرمات الحقيقية هي ما ذكره الله، لا الزينة والطيبات التي منعوها. وجاءت ﴿إنما﴾ لتقرير ما يعرفونه في أصل الفطرة وتوبيخهم على مخالفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص200–201، تحت «غرض القصر في سياق الرد على المشركين»","url":""}]},{"id":"s7-177","number":177,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"لماذا بدأت المحرمات بـ﴿الفواحش ما ظهر منها وما بطن﴾؟","answer":"بدأ بها لعظم خطرها وظهور فسادها في الفرد والمجتمع، ثم تدرج إلى بقية الأصول المحرمة. وجمع الظاهر والباطن ليشمل الفعل المعلن والخفي ولا يترك للهوى منفذًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص203–204، تحت «نكتة ترتيب المحرمات في الآية»","url":""}]},{"id":"s7-178","number":178,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"ما الفرق بين الإثم والبغي في سياق المحرمات؟","answer":"الإثم اسم لما يجلب الذم والعقوبة من المعاصي، أما البغي فهو تجاوز الحق إلى ظلم الغير والاستطالة عليه. فذكرهما يجمع فساد المرء في نفسه واعتداءه على سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص209–210، تحت «الإثم والعدوان والبغي»","url":""}]},{"id":"s7-179","number":179,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"لماذا قُيّد البغي بـ﴿بغير الحق﴾ مع أن البغي لا يكون بحق؟","answer":"يبطل القيد دعوى من يتصور أن تعدي بعض الناس على بعض هو الحق، فيصرح بأن البغي المذكور ظلم. ويحتمل الاحتراز من مقابلة المعتدي بالحق واستيفاء القصاص المشروع، مما يشبه البغي في صورته ولا يكون بغيًا مذمومًا في حقيقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص205–206، تحت «فائدة ذكر قيد ﴿بغير الحق﴾»","url":""}]},{"id":"s7-180","number":180,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"كيف يقوي قوله: ﴿ما لم ينزل به سلطانًا﴾ إبطال الشرك؟","answer":"ينفي عن الشرك أي حجة منزلة، لا ليفهم إمكان شريك يقوم عليه برهان، بل للتهكم بدعواهم؛ إذ يستحيل أن ينزل الله دليلًا يثبت له شريكًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص206–207، تحت «بلاغة ذكر القيد»","url":""}]},{"id":"s7-1594","number":1594,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"لماذا يسمى البرهان سلطانًا؟","answer":"لأن الحجة الواضحة تقهر الباطل وتستولي على العقل بقوتها، كما ينفذ السلطان أمره. فنفي السلطان عن الشرك يصوره دعوى عاجزة لا سند لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص210، تحت «السلطان والحجة»","url":""}]},{"id":"s7-181","number":181,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"لماذا جعل القول على الله بلا علم خاتمة المحرمات؟","answer":"جُعل خاتمة لأنه أصل عظيم تنشأ عنه البدع والتحليل والتحريم والشرك؛ ومن افترى على الله جمع أنواع الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص203–205، تحت «نكتة ترتيب المحرمات في الآية»","url":""}]},{"id":"s7-182","number":182,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"لماذا أضيف الأجل إلى الأمة في ﴿فإذا جاء أجلهم﴾ لا إلى أفرادها؟","answer":"لأن السياق في أجل الجماعة: مدة بقائها أو وقت حلول عقوبتها بعد التكذيب، فللأمم سنن وآجال عامة كما للأفراد آجال خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص217، تحت «غرض إضافة الأجل إلى ضمير الأمة»","url":""}]},{"id":"s7-1595","number":1595,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"لماذا عبر بـ﴿أمة﴾ في قوله: ﴿ولكل أمة أجل﴾؟","answer":"الأمة جماعة يجمعها شأن أو دين أو زمن، فيلائم اللفظ الحديث عن مصير جماعي وسنة تجري على المكذبين بوصفهم مجتمعًا، لا أفرادًا متفرقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص214، تحت «سر التعبير بأمة»","url":""}]},{"id":"s7-183","number":183,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"ما دلالة العموم في قوله: ﴿ولكل أمة أجل﴾؟","answer":"لفظ ﴿كل﴾ يقرر أن السنة لا تحابي أمة؛ فلكل جماعة أجل مقدر، ولا يخرج المكذبون من هذا القانون العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص213–214، تحت «دلالة العموم الصريح»","url":""}]},{"id":"s7-1596","number":1596,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"ما الذي أفاده حذف صفة الأمة في قوله: ﴿ولكل أمة أجل﴾؟","answer":"حذفت الصفة اعتمادًا على السياق، والتقدير: لكل أمة مكذبة معاندة أجل. فالإيجاز يبقي اللفظ عامًا، ويجعل الوعيد متجهًا إلى من تحققت فيهم صفة التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص214–215، تحت «نكتة الإيجاز بحذف الصفة»","url":""}]},{"id":"s7-184","number":184,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا جاء أجلهم﴾، فجعل الأجل آتيًا؟","answer":"شُبه الأجل بغائب يأتي عند حلول وقته، فيصور حتميته وأنه يوافيهم لا محالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص216، تحت «بلاغة الاستعارة في إسناد المجيء إلى الأجل»","url":""}]},{"id":"s7-185","number":185,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]},{"surah":10,"verses":[49]}],"verseLabel":"الأعراف: 34؛ يونس: 49","question":"ما أثر الجمع بين نفي الاستئخار ونفي الاستقدام؟","answer":"جمع النفي بين طرفي الزمن ليقرر ثبات الأجل من الجهتين: فلا يستطيعون دفعه بالتأخير ولا تغييره بالتقديم. ويشتد بذلك الوعيد بأن الموعد خارج عن تصرفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص218–219، تحت «بديع فن الطباق»","url":""}]},{"id":"s7-186","number":186,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"ما سرّ تقديم الاستئخار على الاستقدام؟","answer":"قدم نفي الاستئخار لأن الغرض هنا بيان أنهم لن يجدوا خلاصًا من حلول العذاب ولا مهربًا منه بالتأخير. ثم نفى الاستقدام، فسوى بين الطرفين في الاستحالة وقرر ثبات الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص219، تحت «فائدة عطف الجمل»","url":""}]},{"id":"s7-187","number":187,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"لماذا نُكرت ﴿ساعة﴾؟","answer":"نُكرت للتقليل: لا يتأخرون أقل جزء من الزمن، فضلًا عن مدة طويلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص218–219، تحت «سر التعبير بساعة عن أقل الوقت»","url":""}]},{"id":"s7-188","number":188,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"ما سر انتقال الفاء في الأعراف والنحل إلى صدر الشرط، وبقائها في جواب الشرط في يونس؟","answer":"في الأعراف والنحل ترتب ذكر مجيء الأجل على الكلام السابق، فدخلت الفاء على ﴿إذا﴾ للتفريع والتعقيب. أما في يونس فجاء تقرير الأجل بعد نفي ملك الرسول الضر والنفع، فدخلت الفاء على جواب الشرط لتربط عدم الاستئخار بحلول الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص219–220، وج19، ص483، تحت «توجيه المتشابه اللفظي بين آية يونس والأعراف والنحل»","url":""}]},{"id":"s7-189","number":189,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"لم جدد نداء ﴿يا بني آدم﴾ عند الحديث عن مجيء الرسل؟","answer":"لتجديد التنبيه والعناية بما سيلقى عليهم من عهد الرسل وسبيل النجاة، بعد الوصايا السابقة. فإعادة النداء تستدعي الإصغاء إلى هذا الأمر وتبرز أهميته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص224، تحت «نكتة تكرار النداء»","url":""}]},{"id":"s7-190","number":190,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"لماذا قيل: ﴿إما يأتينكم﴾ بالمضارع مع تحقق مجيء الرسل؟","answer":"يستحضر المضارع مجيء الرسل متجددًا في أزمنة الأمم، ويصور البلاغ كأنه يقع أمام المخاطبين؛ فلا يراد الشك، بل تجديد العهد كلما جاء رسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص224، تحت «دلالة العدول عن الماضي إلى المضارع»","url":""}]},{"id":"s7-191","number":191,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"لماذا أكد فعل المجيء بنون التوكيد؟","answer":"النون تؤكد حتمية وصول الرسل والبلاغ إلى المخاطبين، وتلائم مقام العهد والتحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص224، تحت «بلاغة تأكيد الشرط»","url":""}]},{"id":"s7-192","number":192,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿رسل منكم﴾؟","answer":"﴿منكم﴾ تؤنسهم بالرسل وتجعل الحجة أبلغ؛ فهم بشر يعرفون لسان قومهم وأحوالهم ويمكن الاقتداء بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص225–226، تحت «دلالة الجار والمجرور في الامتنان»","url":""}]},{"id":"s7-193","number":193,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"لماذا عبر عن تبليغ الوحي بقوله: ﴿يقصون عليكم آياتي﴾؟","answer":"القص أعم من مجرد التلاوة؛ فهو اتباع للخبر وبيان لمعناه، ويشمل ما يبلغ من صحيفة أو من غيرها. لذلك يلائم مهمة الرسل في عرض الآيات وشرحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص226–227، تحت «سر اختيار مفردة ﴿يقصون﴾ دون مرادفاتها»","url":""}]},{"id":"s7-1597","number":1597,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"ماذا يفيد المضارع في قوله: ﴿يقصون عليكم آياتي﴾؟","answer":"يصور استمرار الرسل في التبليغ وتجدد بيانهم للناس، ويستحضر أداء الرسالة كأنه مشهد قائم؛ فتظهر ملازمتهم لوظيفتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص226، تحت «نكتة التعبير عن الصفة بالفعل المضارع»","url":""}]},{"id":"s7-194","number":194,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"لماذا قيل: ﴿فمن اتقى وأصلح﴾، ولم يقل: فمن صدق واتبع؟","answer":"عدل إلى التقوى والإصلاح ليبين ثمرة اتباع الرسل: اجتناب المعصية وإصلاح العمل. فالنجاة لا تتحقق بمجرد دعوى التصديق، بل بانقياد يغير حال الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص229، تحت «سر العدول عما يقتضيه الظاهر في جواب الشرط»","url":""}]},{"id":"s7-195","number":195,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"ما الفرق بين الخوف والحزن في قوله: ﴿فلا خوف عليهم ولا هم يحزنون﴾؟","answer":"الخوف همّ يلحق الإنسان لشيء متوقع في المستقبل، والحزن غم يقع لما مضى وفات؛ فنفيهما يجمع لهم الأمن من آتي الزمن وصفاء النفس مما مضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص236، تحت «الخوف والحزن»","url":""}]},{"id":"s7-196","number":196,"surah":7,"verses":[36],"references":[{"surah":7,"verses":[36]}],"verseLabel":"الأعراف: 36","question":"لماذا قابل المتقين بـ﴿الذين كذبوا بآياتنا واستكبروا عنها﴾؟","answer":"لأنهما يقابلان ﴿اتقى وأصلح﴾: التكذيب فساد الاعتقاد، والاستكبار امتناع عن الانقياد والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص232–233، تحت «سر الاختلاف في التعبير بين المتقابلات»","url":""}]},{"id":"s7-197","number":197,"surah":7,"verses":[36],"references":[{"surah":7,"verses":[36]}],"verseLabel":"الأعراف: 36","question":"كيف يبين قوله ﴿واستكبروا عنها﴾ سبب التكذيب بالآيات؟","answer":"ذكر الاستكبار بعد التكذيب يكشف أن امتناعهم عن قبول الآيات صادر عن الترفع والعناد، لا عن نقص بيانها. ففي العطف تفسير لعلة التكذيب، مع زيادة بيان قبح موقفهم وشناعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص233–234، تحت «فائدة عطف الاستكبار على التكذيب»","url":""}]},{"id":"s7-198","number":198,"surah":7,"verses":[36],"references":[{"surah":7,"verses":[36]}],"verseLabel":"الأعراف: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿أولئك أصحاب النار﴾، فجعلهم أصحابًا لها؟","answer":"الصاحب ملازم لصاحبه؛ فالتعبير يدل على ملازمتهم النار وعدم انفكاكهم عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص234–235، تحت «دلالة اختيار لفظ الصحبة»","url":""}]},{"id":"s7-199","number":199,"surah":7,"verses":[36],"references":[{"surah":7,"verses":[36]}],"verseLabel":"الأعراف: 36","question":"ماذا أفاد قوله: ﴿هم فيها خالدون﴾ بعد وصفهم بأصحاب النار؟","answer":"الجملة الاسمية تؤكد دوام ملازمتهم النار وثبات الخلود، وإعادة الضمير تزيد التقرير، وتقديم ﴿فيها﴾ يقصر خلودهم على هذا المصير المهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص235–236، تحت «دلالة التوكيد بالجملة الاسمية»","url":""}]},{"id":"s7-200","number":200,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما غرض الاستفهام في قوله: ﴿فمن أظلم ممن افترى على الله كذبًا أو كذب بآياته﴾؟","answer":"الاستفهام للإنكار والنفي: لا أحد أشد ظلمًا ممن اختلق على الله قولًا أو رد آياته؛ وفيه تقريع وتحذير من بلوغ غاية الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص240، تحت «غرض الاستفهام وفائدته»","url":""}]},{"id":"s7-1598","number":1598,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ماذا أفاد الجمع بين الافتراء على الله والتكذيب بآياته؟","answer":"جمع الطرفين: إنشاء الباطل من عند النفس، ورد الحق حين يأتي من الله. فصور طريقَي محاربة الوحي، وبين أن كليهما ظلم عظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص242، تحت «براعة التعبير في الجمع بين لفظ الافتراء والتكذيب»","url":""}]},{"id":"s7-201","number":201,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"لماذا عطف الافتراء والتكذيب بـ﴿أو﴾؟","answer":"يوجه المصدر ﴿أو﴾ هنا بمعنى الإضراب والترقي: بل كذب بآياته؛ فينتقل من افتراء الكذب على الله إلى تكذيب آياته، مبينًا شناعة كل من الوصفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص243، تحت «معنى حرف ﴿أو﴾»","url":""}]},{"id":"s7-202","number":202,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما سر التعبير بقوله: ﴿ينالهم نصيبهم﴾؟","answer":"صور النصيب كشيء يصل إليهم ويصيبهم حتمًا؛ فتجعل الاستعارة ما كتب لهم من رزق وأجل أو عذاب أمرًا لا يفوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص244، تحت «بلاغة الاستعارة المكنية»","url":""}]},{"id":"s7-1599","number":1599,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما المقصود بالكتاب في قوله: ﴿نصيبهم من الكتاب﴾؟","answer":"هو ما كتب وقدر لهم في اللوح من رزق وأجل وعمل، وقيل نصيبهم من العذاب. والتعريف يستحضر الكتاب المعلوم الذي أحصى الله فيه المقادير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص245، تحت «دلالة استعمال مفردة الكتاب ومعنى التعريف»","url":""}]},{"id":"s7-203","number":203,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا جاءتهم رسلنا يتوفونهم﴾، فجمع الرسل؟","answer":"المراد رسل الموت من الملائكة: ملك الموت وأعوانه؛ فالجمع باعتبار تعدد الملائكة الموكلين بالتوفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص247، تحت «نكتة التعبير بالرسل دون الملائكة»","url":""}]},{"id":"s7-204","number":204,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما دلالة سؤال الملائكة: ﴿أين ما كنتم تدعون من دون الله﴾؟","answer":"سؤال توبيخ وتقرير يظهر عجز المعبودات التي دعوها؛ لا طلبًا لعلم مكانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص248–249، تحت «غرض الاستفهام التهكمي»","url":""}]},{"id":"s7-205","number":205,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما دلالة جوابهم: ﴿ضلوا عنا﴾، وتصوير غياب آلهتهم بالضلال؟","answer":"أي غابوا وفقدوا فلم ينفعوا؛ فصور بطلان أثرهم كضياع من كانوا يرجون حضورهم ونصرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص250–251، تحت «سر استعمال لفظ الضلال»","url":""}]},{"id":"s7-206","number":206,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما دلالة شهادتهم ﴿على أنفسهم أنهم كانوا كافرين﴾؟","answer":"شهدوا حين قامت الحجة وعاينوا الحق، فصار اعترافهم بالكفر إقرارًا على أنفسهم لا ينفعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص251–252، تحت «غرض ذكر القيد»","url":""}]},{"id":"s7-207","number":207,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"ما سرّ التعبير بقوله تعالى: ﴿ادخلوا في أمم قد خلت من قبلكم﴾، ولم يقل: مع أمم؟","answer":"يذكر المصدر وجهين: أن تكون ﴿في﴾ بمعنى المصاحبة، أو أن تكون للظرفية، وهو الأوفق عنده؛ أي ادخلوا في جملة أمم سبقتكم. فالظرفية تصور اندراجهم في تلك الجماعات، ويتبع ذلك دخولهم النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص259، تحت «براعة استعمال حرف الجر ﴿في﴾»","url":""}]},{"id":"s7-208","number":208,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"لماذا جمع الجن والإنس في دخول النار؟","answer":"جمع الفريقين لأن التكليف والعصيان وقعا منهما، ولأن شياطين الجن وأتباعهم من الإنس اشتركوا في الإضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص261–262، تحت «دلالة ﴿من﴾ في قوله تعالى: ﴿من الجن والإنس﴾»","url":""}]},{"id":"s7-209","number":209,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿كلما دخلت أمة لعنت أختها﴾، وسمى الأمة الأخرى أختًا؟","answer":"سميت أختها لاشتراكهما في الملة والكفر والمصير، مع أن هذا الاشتراك لم يمنع التلاعن.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص263، تحت «نكتة الاستعارة التصريحية في قوله تعالى: ﴿أختها﴾»","url":""}]},{"id":"s7-210","number":210,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا اداركوا فيها جميعًا﴾، واختار صيغة الادّارك؟","answer":"الادّراك تتابع اللحاق حتى يجتمع آخرهم بأولهم في النار؛ وصيغته تصور تدارك بعضهم بعضًا واجتماعهم جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص256–257، 264، تحت «المعنى الإجمالي؛ لطيفة في توجيه الإدغام في قوله: ﴿اداركوا﴾»","url":""}]},{"id":"s7-211","number":211,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"لماذا سمت الأمة المتبوعة ﴿أولاهم﴾ والتابعة ﴿أخراهم﴾؟","answer":"الأولى المتقدمة زمانًا والمتبوعة في الضلال، والأخرى المتأخرة التابعة التي جاءت بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص256–257، تحت «شرح المفردات»","url":""}]},{"id":"s7-212","number":212,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"لماذا طلب الأتباع لقادتهم ﴿عذابًا ضعفًا﴾؟","answer":"طلبوا مضاعفة عذابهم انتقامًا ممن أغووهم، وفي العبارة كناية محتملة عن تمني أن يكون عذاب الأتباع أخف بالمقارنة مع عذاب القادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص265–266، تحت «براعة الكناية في قوله تعالى: ﴿فآتهم عذابًا ضعفًا من النار﴾»","url":""}]},{"id":"s7-1600","number":1600,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"لماذا نسب الأتباع الضلال إلى قادتهم فقالوا: ﴿هؤلاء أضلونا﴾؟","answer":"نسبوا الضلال إليهم لأنهم سببوه بالدعوة والتزيين، مع أن الأتباع اختاروا الاستجابة؛ فذكر السبب مكان الفعل الذي نشأ عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص265، تحت «نكتة المجاز المرسل في ﴿أضلونا﴾»","url":""}]},{"id":"s7-213","number":213,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"ماذا حذف من قوله: ﴿لكل ضعف﴾؟","answer":"حذف المضاف إليه اعتمادًا على السياق؛ أي لكل فريق أو لكل أمة ضعف من العذاب. فالإيجاز يعم الفريقين ويقطع توهم اختصاص القادة بالمضاعفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص267، تحت «بلاغة الإيجاز بالحذف»","url":""}]},{"id":"s7-1601","number":1601,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"ماذا أفاد الاستدراك في قوله: ﴿ولكن لا تعلمون﴾؟","answer":"يرفع توهم الأتباع أن عذابهم أخف من عذاب القادة؛ فلكل نصيبه المضاعف، لكنهم لا يحيطون بمقادير الجزاء التي قدرها الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص267، تحت «دلالة استعمال ﴿ولكن﴾»","url":""}]},{"id":"s7-1602","number":1602,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"لماذا حذف متعلق العلم في قوله: ﴿ولكن لا تعلمون﴾؟","answer":"حذفه يعمم جهلهم: لا يعلمون مقدار عذاب كل فريق ولا حكمته ولا ما أعد للآخرين؛ فيشتد تقريعهم على الحكم بغير علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص268، تحت «نكتة حذف معمول ﴿تعلمون﴾»","url":""}]},{"id":"s7-214","number":214,"surah":7,"verses":[39],"references":[{"surah":7,"verses":[39]}],"verseLabel":"الأعراف: 39","question":"ما دلالة قول الأولى للأخرى: ﴿فما كان لكم علينا من فضل﴾؟","answer":"نفوا مزية الأتباع عليهم في استحقاق التخفيف؛ فقد اشترك الجميع في الكفر ولم تكن للتابعين حجة ترفع عنهم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص270، تحت «شرح المفردات: ﴿فضل﴾»","url":""}]},{"id":"s7-215","number":215,"surah":7,"verses":[39],"references":[{"surah":7,"verses":[39]}],"verseLabel":"الأعراف: 39","question":"ما أثر ﴿من﴾ في قولهم: ﴿فما كان لكم علينا من فضل﴾؟","answer":"تؤكد ﴿من﴾ النفي وتفيد استغراق أي فضل؛ فالمتبوعون ينفون أن تكون للأتباع مزية عليهم توجب أن يكون عذابهم أخف. وليس المراد تسمية زيادة العذاب فضلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص273، تحت «فائدة ﴿من﴾ في قوله تعالى: ﴿من فضل﴾»","url":""}]},{"id":"s7-216","number":216,"surah":7,"verses":[39],"references":[{"surah":7,"verses":[39]}],"verseLabel":"الأعراف: 39","question":"لماذا خُتم الحوار بـ﴿فذوقوا العذاب بما كنتم تكسبون﴾؟","answer":"الخطاب يقطع جدالهم ورد التبعة بعضهم على بعض؛ فكل فريق يذوق جزاء ما كان يكتسبه باختياره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص275–276، تحت «دلالة اجتماع فعل الكون والمضارع: ﴿كنتم تكسبون﴾»","url":""}]},{"id":"s7-217","number":217,"surah":7,"verses":[39],"references":[{"surah":7,"verses":[39]},{"surah":8,"verses":[35]}],"verseLabel":"الأعراف: 39؛ الأنفال: 35","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿بما كنتم تكسبون﴾، وفي الأنفال: ﴿بما كنتم تكفرون﴾؟","answer":"في الأعراف: 39 جاء ﴿تكسبون﴾ لأن السياق يجمع الكفر والضلال والإضلال، فناسب التعبير بالكسب لتعدد الأعمال الموجبة للعذاب. أما في الأنفال: 35 فجاء ﴿تكفرون﴾ لأن الكلام في عذاب المشركين وعبادتهم الباطلة عند البيت؛ فصرح بالكفر الذي استحقوا به ذلك العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص277، وج16، ص110–111، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-218","number":218,"surah":7,"verses":[40],"references":[{"surah":7,"verses":[40]}],"verseLabel":"الأعراف: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تفتح لهم أبواب السماء﴾، وما الذي كان ينتظر أن يصعد؟","answer":"لا تفتح لصعود أرواحهم أو أعمالهم ودعائهم، ولا لنزول الرحمة عليهم؛ فالعبارة تصور حرمانهم من القبول والكرامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص285–286، تحت «براعة النظم في الجمع بين الحقيقة والمجاز»","url":""}]},{"id":"s7-219","number":219,"surah":7,"verses":[40],"references":[{"surah":7,"verses":[40]}],"verseLabel":"الأعراف: 40","question":"ما وجه تضعيف الفعل في ﴿لا تُفَتَّح لهم أبواب السماء﴾؟","answer":"من وجوه التضعيف الإشارة إلى كثرة الأبواب، أو تأكيد نفي الفتح وتحقيقه. ويذكر المصدر وجهًا آخر يجعل المنفي ذلك الفتح القوي الذي يكون للمؤمنين وأعمالهم؛ فتبرز شدة الحرمان من القبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص285، تحت «نكتة تضعيف الفعل ﴿تفتح﴾»","url":""}]},{"id":"s7-220","number":220,"surah":7,"verses":[40],"references":[{"surah":7,"verses":[40]}],"verseLabel":"الأعراف: 40","question":"لماذا شُبّه استحالة دخولهم الجنة بولوج الجمل في سم الخياط؟","answer":"عُلّق دخولهم الجنة على أمر مستحيل في العادة: أن يدخل الجمل الضخم في ثقب الإبرة الدقيق. فالتعليق يصور انتفاء دخول المكذبين المستكبرين المذكورين، ويؤكد خلود حرمانهم منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص286–287، تحت «بلاغة تعليق النجاة بالمستحيل»","url":""}]},{"id":"s7-221","number":221,"surah":7,"verses":[40],"references":[{"surah":7,"verses":[40]}],"verseLabel":"الأعراف: 40","question":"لماذا اختير ﴿الجمل﴾ و﴿سم الخياط﴾؟","answer":"الجمل مشهور بعظم الجرم، وسم الخياط غاية في الضيق؛ فاجتماعهما يصنع أوضح صورة للتعذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص287، تحت «نكتة تخصيص الجمل دون غيره»","url":""}]},{"id":"s7-222","number":222,"surah":7,"verses":[40],"references":[{"surah":7,"verses":[40]}],"verseLabel":"الأعراف: 40","question":"لماذا خُتمت بـ﴿وكذلك نجزي المجرمين﴾، لا: المكذبين؟","answer":"يصفهم ختام الآية بكمال الإجرام، ويجعل ما ذكر من الحرمان جزاءً يجري على أمثالهم من المجرمين المكذبين. ففي التذييل تعميم للحكم في هذا الصنف، وتقرير لاستحقاقهم الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص288–289، تحت «بلاغة التذييل في الآية»","url":""}]},{"id":"s7-223","number":223,"surah":7,"verses":[41],"references":[{"surah":7,"verses":[41]}],"verseLabel":"الأعراف: 41","question":"ما سرّ وصف جهنم بأنها ﴿مهاد﴾ مع أن المهاد موضع الراحة؟","answer":"وصف جهنم بالمهاد تهكم ومقابلة؛ فما يفترشونه ليس موضع راحة بل نار تحيط بهم من أسفل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص292، تحت «سر التعبير بقوله: ﴿مهاد﴾ دون عذاب»","url":""}]},{"id":"s7-224","number":224,"surah":7,"verses":[41],"references":[{"surah":7,"verses":[41]}],"verseLabel":"الأعراف: 41","question":"كيف أغنى ذكر ﴿من جهنم﴾ مع المهاد عن إعادته مع الغواشي؟","answer":"هذا من الاحتباك: ذكر ﴿من جهنم﴾ مع المهاد يدل على أن الغواشي من جهنم أيضًا، وذكر ﴿من فوقهم﴾ مع الغواشي يدل على أن المهاد من تحتهم. فدل المذكور في كل جانب على المحذوف في الآخر، وأوجز تصوير إحاطة النار بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص293، تحت «فن الاحتباك في الآية»","url":""}]},{"id":"s7-225","number":225,"surah":7,"verses":[41],"references":[{"surah":7,"verses":[41]}],"verseLabel":"الأعراف: 41","question":"لم صرّح بـ﴿من فوقهم﴾ مع الغواشي، ولم يقل: من تحتهم مهاد؟","answer":"يفهم من المهاد أنه يكون تحت صاحبه، فلا يحتاج إلى التصريح بالتحتية. أما ما يغشى الإنسان فقد يأتيه من جهات مختلفة؛ فذكر ﴿من فوقهم﴾ لتعيين جهة الغواشي وإتمام صورة إحاطة النار من فوقهم وتحتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص292–293، تحت «براعة المقابلة بين ﴿مهاد﴾ و﴿فوقهم﴾»","url":""}]},{"id":"s7-226","number":226,"surah":7,"verses":[41],"references":[{"surah":7,"verses":[41]}],"verseLabel":"الأعراف: 41","question":"لماذا خُتمت بـ﴿وكذلك نجزي الظالمين﴾ بعد ﴿المجرمين﴾ في الآية السابقة؟","answer":"يجمع الختامان لهم وصفي الإجرام والظلم، ويناسب كل وصف سياقه: فقد قطعوا صلتهم بالآيات بالتكذيب والاستكبار، فذكر الإجرام مع حرمان الجنة؛ وظلموا أنفسهم بإيرادها الهلاك، فذكر الظلم مع إحاطة النار. وفي اختلاف الفاصلتين تنويع مع تحقيق الوصفين لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص295–296، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-227","number":227,"surah":7,"verses":[42],"references":[{"surah":7,"verses":[42]}],"verseLabel":"الأعراف: 42","question":"لماذا اعترض بين الإيمان والجنة بقوله: ﴿لا نكلف نفسًا إلا وسعها﴾؟","answer":"الجملة اعتراض يرفع توهم أن العمل الصالح المطلوب فوق الطاقة؛ فدخول الجنة مرتب على إيمان وعمل في حدود الوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص302، تحت «براعة الإطناب بالاعتراض»","url":""}]},{"id":"s7-228","number":228,"surah":7,"verses":[42],"references":[{"surah":7,"verses":[42]}],"verseLabel":"الأعراف: 42","question":"ما الذي يحدده لفظ ﴿وسعها﴾ في قوله: ﴿لا نكلف نفسًا إلا وسعها﴾؟","answer":"الوسع هو الطاقة؛ فالتكليف مقيد بما تطيقه النفس، ولا يطلب منها ما يجاوز قدرتها. وفي ذلك ترغيب في الطاعة، إذ ينال المؤمن النعيم العظيم بما يستطيعه من العمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص297، تحت «شرح المفردات: ﴿وسعها﴾»","url":""}]},{"id":"s7-229","number":229,"surah":7,"verses":[42],"references":[{"surah":7,"verses":[42]}],"verseLabel":"الأعراف: 42","question":"ماذا أفاد القصر في قوله: ﴿أولئك أصحاب الجنة﴾؟","answer":"يقصر استحقاق الجنة على المؤمنين العاملين بالصالحات المذكورين، ويقرر أنهم أهلها الملازمون لها؛ فلا يشاركهم فيها من أعرض عن الإيمان والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص303–304، تحت «غرض القصر في الآية»","url":""}]},{"id":"s7-230","number":230,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿ونزعنا ما في صدورهم من غل﴾، فجعل الغل شيئًا يُنزع؟","answer":"استعير النزع لإزالة الغل إزالة تامة قوية؛ كأنه جسم متغلغل في الصدور يُقتلع منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص308–309، تحت «نكتة الاستعارة التصريحية»","url":""}]},{"id":"s7-231","number":231,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"ما وجه التعبير بالصدور في ﴿ونزعنا ما في صدورهم من غل﴾؟","answer":"يذكر المصدر وجه التعبير بالصدر عن القلب، وهو محل الغل، فيوحي التطهير بأنه بلغ القلب وما يجاوره. ويذكر وجهًا آخر يحمل الصدر على حقيقته، إذ يظهر فيه الانشراح والانقباض؛ فنزع الغل يورث صفاء النفس وانشراح الصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص310، تحت «نكتة التعبير بالصدور بدل القلوب»","url":""}]},{"id":"s7-232","number":232,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"ما أثر وصف الأنهار بالجريان في مشهد الجنة؟","answer":"يرسم الجريان حركة الماء وانسيابه المتصل، ويزيد المشهد حياة وجمالًا، كما يوحي بتجدد النعمة ووفرتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص310، تحت «دلالة التعبير بوصف الأنهار بالجريان»","url":""}]},{"id":"s7-1603","number":1603,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"كيف أسند الجريان إلى الأنهار مع أن الجاري ماؤها؟","answer":"أسند الفعل إلى المحل الذي يجري فيه الماء، وفي ذلك مبالغة توحي بوفرة الماء حتى كأن الأنهار نفسها تجري، مع إيجاز الصورة وقوتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص311، تحت «بلاغة المجاز العقلي في الآية»","url":""}]},{"id":"s7-233","number":233,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"لماذا وصف الله بقولهم: ﴿الذي هدانا لهذا﴾؟","answer":"جعلت الصلة الهداية سبب الحمد الظاهر، فاستحضر أهل الجنة نعمة ربهم التي أوصلتهم إلى النعيم، وربطوا الجزاء بالمنة والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص313، تحت «سر الوصف بالاسم الموصول»","url":""}]},{"id":"s7-1604","number":1604,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"إلام يشير اسم الإشارة في قول أهل الجنة: ﴿هدانا لهذا﴾؟","answer":"يشير إلى ما هم فيه من الجنة والنعيم، أو إلى الطريق الذي أوصلهم إليه؛ فاستعملت الإشارة إلى الحاصل للدلالة على سببه وتمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص314، تحت «بلاغة المجاز المرسل»","url":""}]},{"id":"s7-234","number":234,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"ما دلالة ﴿لولا أن هدانا الله﴾، وكيف أغنى ما قبلها عن ذكر جوابها؟","answer":"تعلق ﴿لولا﴾ حصول الاهتداء بهداية الله، فيعترف أهل الجنة بأن الفضل له. وحذف جوابها لدلالة ﴿وما كنا لنهتدي﴾ عليه؛ أي لولا هداية الله ما اهتدينا، فأوجز الكلام مع وضوح تعلق النعمة بفضل المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص314–315، تحت «دلالة حذف الجواب»","url":""}]},{"id":"s7-235","number":235,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"لماذا أكد أهل الجنة قولهم: ﴿لقد جاءت رسل ربنا بالحق﴾؟","answer":"أكدوه فرحًا بتحقق الوعد بعد مشاهدته، وإظهارًا لصدق الرسل وإقرارًا بأن ما أخبروا به صار واقعًا مشهودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص315، تحت «نكتة التأكيد بلام القسم و﴿قد﴾»","url":""}]},{"id":"s7-1605","number":1605,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"ماذا أفادت إضافة الرب إلى أهل الجنة في قولهم: ﴿رسل ربنا﴾؟","answer":"تستحضر إحسان الله إليهم وتربيته وهدايته، وتجعل مجيء الرسل من آثار عنايته بهم؛ فناسبت مقام الشكر بعد تمام النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص315–316، تحت «دلالة الإضافة في ﴿ربنا﴾»","url":""}]},{"id":"s7-236","number":236,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"لماذا نودوا: ﴿أن تلكم الجنة أورثتموها﴾، فجعلت الجنة ميراثًا؟","answer":"شبه حصول الجنة لهم بالميراث الذي يصير إلى صاحبه من غير بيع ولا شراء ولا غصب. وفي الصورة بيان عظم المنحة؛ فالعمل سبب لها بفضل الله، وليس عوضًا يستقل بمقابلة هذا النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص318–319، تحت «دلالة التعبير بالإرث»","url":""}]},{"id":"s7-237","number":237,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"ما سرّ الجمع بين ﴿أورثتموها﴾ و﴿بما كنتم تعملون﴾؟","answer":"العمل سبب للدخول بتفضل الله، أما نفس الجنة وثوابها فميراث وفضل؛ فلا تعارض بين السببية والمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص319، تحت «معنى الباء في ﴿بما﴾»","url":""}]},{"id":"s7-238","number":238,"surah":7,"verses":[44],"references":[{"surah":7,"verses":[44]}],"verseLabel":"الأعراف: 44","question":"لماذا نادى أصحاب الجنة أصحاب النار؟","answer":"نادوهم لإقامة الحجة وإظهار صدق وعد الله للفريقين، وزيادة الحسرة على المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص329، تحت «دلالة التعبير بالمناداة ﴿ونادى﴾ دون القول»","url":""}]},{"id":"s7-239","number":239,"surah":7,"verses":[44],"references":[{"surah":7,"verses":[44]}],"verseLabel":"الأعراف: 44","question":"ما دلالة التعبير بـ﴿ربنا﴾ و﴿ربكم﴾ في خطاب أصحاب الجنة لأصحاب النار؟","answer":"يشير ﴿ربنا﴾ إلى إحسان الله لأهل الإيمان في الدنيا بنعمه وهدايته، وإتمام هذا الإحسان لهم في الآخرة. ويذكر ﴿ربكم﴾ أهل النار بمن أنعم عليهم وهداهم إلى سبيل الرشاد في الدنيا، فقابلوا إحسانه بالجحود والكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص331، تحت «دلالة التعبير بالربوبية دون الألوهية»","url":""}]},{"id":"s7-240","number":240,"surah":7,"verses":[44],"references":[{"surah":7,"verses":[44]}],"verseLabel":"الأعراف: 44","question":"لماذا سأل أهل الجنة: ﴿فهل وجدتم ما وعد ربكم حقًا﴾ وهم يعلمون؟","answer":"السؤال للتقرير والتبكيت، ليقر أهل النار بألسنتهم بصدق الوعيد كما أقر أهل الجنة بصدق الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص331–332، تحت «دلالة الاستفهام في قوله: ﴿فهل وجدتم﴾»","url":""}]},{"id":"s7-241","number":241,"surah":7,"verses":[44],"references":[{"surah":7,"verses":[44]}],"verseLabel":"الأعراف: 44","question":"ما دلالة جواب أهل النار: ﴿قالوا نعم﴾؟","answer":"يثبت جوابهم صدق ما سئلوا عنه، فيقرون بأنهم وجدوا الوعيد حقًا. ويصور هذا الإقرار خزيهم وحسرتهم؛ فقد صار ما كانوا ينكرونه واقعًا لا يستطيعون دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص334، تحت «دلالة الجواب ﴿قالوا نعم﴾ في سياق الآية»","url":""}]},{"id":"s7-242","number":242,"surah":7,"verses":[44],"references":[{"surah":7,"verses":[44]}],"verseLabel":"الأعراف: 44","question":"ما سرّ التعبير بقوله تعالى: ﴿فأذن مؤذن بينهم﴾، ولم يُسمّ المؤذن؟","answer":"الفعل ﴿أذّن﴾ مبني للمعلوم وفاعله ﴿مؤذن﴾. ونُكر المؤذن لأن تعيين شخصه غير مقصود؛ فالعناية بالإعلام والحكم المعلن. وذكر الفاعل مع الفعل يبين أن المنادي جهة أخرى بين الفريقين، ويذكر المصدر أنه من الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص335، تحت «نكتة تنكير ﴿مؤذن﴾»","url":""}]},{"id":"s7-243","number":243,"surah":7,"verses":[44],"references":[{"surah":7,"verses":[44]}],"verseLabel":"الأعراف: 44","question":"لماذا كانت اللعنة ﴿على الظالمين﴾ لا على الكافرين؟","answer":"يعلل هذا الوصف استحقاقهم اللعنة؛ فظلمهم هو الذي أوردهم الهلاك. وهو وصف جامع يصل هذا الإعلان بما بعده من صدهم عن سبيل الله وابتغائها عوجًا وكفرهم بالآخرة؛ فلا يراد هنا فصل الظلم عن كفرهم، بل بيان موجب الجزاء وجمع أوصافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص337–338، تحت «دلالة (ال) في لفظ ﴿الظالمين﴾»","url":""}]},{"id":"s7-244","number":244,"surah":7,"verses":[45],"references":[{"surah":7,"verses":[45]},{"surah":11,"verses":[19]}],"verseLabel":"الأعراف: 45؛ هود: 19","question":"لماذا وصف الظالمين بأنهم ﴿يصدون عن سبيل الله ويبغونها عوجًا﴾؟","answer":"في الأعراف: 45: هذه أوصاف تكشف تعدي ظلمهم إلى غيرهم: يمنعون الناس من طريق الله، ويحاولون إظهاره معوجًا لصدهم عنه.\n\nفي هود: 19: لم يكتفوا بضلال أنفسهم، بل منعوا غيرهم وصوروا الطريق المستقيم معوجًا؛ فجمعوا الصد والتحريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص343–344، تحت «سر التعبير بالصد ﴿يصدون﴾ دون المنع»","url":""}]},{"id":"s7-245","number":245,"surah":7,"verses":[45],"references":[{"surah":7,"verses":[45]}],"verseLabel":"الأعراف: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿يبغونها عوجًا﴾، فجعل العوج مطلوبًا؟","answer":"صورهم كأنهم يطلبون العوج ويبتغونه للسبيل المستقيم؛ أي يلتمسون الشبه ويصفونه بالانحراف أو يريدون الناس عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص346–347، تحت «بلاغة المجاز في قوله تعالى: ﴿ويبغونها عوجًا﴾»","url":""}]},{"id":"s7-246","number":246,"surah":7,"verses":[45],"references":[{"surah":7,"verses":[45]}],"verseLabel":"الأعراف: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم بالآخرة كافرون﴾ بتقديم ﴿بالآخرة﴾؟","answer":"قُدّم للاهتمام بموضع كفرهم وتشنيعه؛ فالآخرة التي دل عليها الوحي هي خاصة ما يجحدونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص349–350، تحت «دلالة تقديم الجار والمجرور»","url":""}]},{"id":"s7-247","number":247,"surah":7,"verses":[45],"references":[{"surah":7,"verses":[45]}],"verseLabel":"الأعراف: 45","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وهم بالآخرة كافرون﴾، وزاد في هود ضميرًا آخر فقال: ﴿وهم بالآخرة هم كافرون﴾؟","answer":"في هود تكرر ﴿هم﴾ لتقوية الحكم بكفرهم بالآخرة، وناسب ذلك مقام تسجيل إنكار البعث وما ينتظرهم من العقاب، وما سبق من الإطناب في ذكرهم. أما الأعراف فالمقام حكاية حال قوم دخلوا النار وظهر عقابهم، فناسبه الإيجاز دون هذا التكرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص348–349، تحت «سر ذكر الضمير المنفصل ﴿وهم﴾ مرة لا مرتين»","url":""}]},{"id":"s7-248","number":248,"surah":7,"verses":[46],"references":[{"surah":7,"verses":[46]}],"verseLabel":"الأعراف: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿وبينهما حجاب وعلى الأعراف رجال﴾؟","answer":"الحجاب يفصل بين الجنة والنار، وفوق أعاليه رجال يشرفون على الفريقين؛ فرتب المكان قبل ذكر أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص357–358، تحت «تقديم متعلق الخبر ﴿وبينهما﴾ على المسند إليه ﴿حجاب﴾»","url":""}]},{"id":"s7-249","number":249,"surah":7,"verses":[46],"references":[{"surah":7,"verses":[46]}],"verseLabel":"الأعراف: 46","question":"لماذا سُمي السور أو المكان ﴿الأعراف﴾؟","answer":"الأعراف جمع عُرف، وهو المكان المرتفع الظاهر من السور؛ سمي بذلك لعلوه وتمكن من عليه من معرفة الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص357–358، تحت «سر التعبير بالأعراف دون السور»","url":""}]},{"id":"s7-250","number":250,"surah":7,"verses":[46],"references":[{"surah":7,"verses":[46]}],"verseLabel":"الأعراف: 46","question":"ما دلالة التنوين في ﴿يعرفون كلًا بسيماهم﴾؟","answer":"التنوين عوض عن المضاف إليه الذي دل عليه السياق؛ أي يعرفون كل فريق من أصحاب الجنة وأصحاب النار، أو كل أصحاب الجنة وأصحاب النار، بعلاماتهم. فاستغني عن إعادة ذكر الفريقين لوضوح المراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص360، تحت «دلالة التنوين في لفظ ﴿كلًا﴾»","url":""}]},{"id":"s7-251","number":251,"surah":7,"verses":[46],"references":[{"surah":7,"verses":[46]}],"verseLabel":"الأعراف: 46","question":"لماذا نادوا أصحاب الجنة بالسلام مع أنهم ﴿لم يدخلوها وهم يطمعون﴾؟","answer":"يحيون أهل الجنة بعدما عرفوهم بعلاماتهم، وفي ندائهم تضرع ورجاء واسترحام. ثم يبين قوله ﴿لم يدخلوها وهم يطمعون﴾ أن أصحاب الأعراف لم يدخلوا الجنة بعد، مع شدة رجائهم في فضل الله ودخولها؛ فلا ينافي سلامهم بقاءهم منتظرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص361–362، تحت «سر التعبير بـ﴿سلام﴾ دون غيرها في سياق الآية»","url":""}]},{"id":"s7-252","number":252,"surah":7,"verses":[46],"references":[{"surah":7,"verses":[46]}],"verseLabel":"الأعراف: 46","question":"ما دلالة المضارع في ﴿وهم يطمعون﴾؟","answer":"يصور المضارع تجدد طمع أصحاب الأعراف وشدة رجائهم في دخول الجنة. وتبين الجملة الحالية المعترضة حالهم وهم لم يدخلوها بعد، وقوة رغبتهم فيما عند الله من الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص363–364، تحت «نكتة التعبير بالفعل المضارع ﴿يطمعون﴾»","url":""}]},{"id":"s7-253","number":253,"surah":7,"verses":[47],"references":[{"surah":7,"verses":[47]}],"verseLabel":"الأعراف: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا صرفت أبصارهم تلقاء أصحاب النار﴾ بالبناء للمجهول؟","answer":"لا حاجة إلى تعيين الصارف؛ فالعناية بتصوير نظرهم إلى أصحاب النار وما يبعثه من الخوف. ويقابل هذا الصرف توجههم إلى الجنة برغبة؛ فهم لا يتعمدون التطلع إلى النار، بل تقع أبصارهم على ما حولهم وهم كارهون لرؤيتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص367–368، تحت «سر بناء الفعل للمفعول في ﴿صرفت﴾»","url":""}]},{"id":"s7-254","number":254,"surah":7,"verses":[47],"references":[{"surah":7,"verses":[47]}],"verseLabel":"الأعراف: 47","question":"لماذا اختير ﴿تلقاء﴾؟","answer":"﴿تلقاء﴾ تحدد الجهة المقابلة التي تقع فيها النار أمام أبصارهم، وتصور مواجهتهم المباشرة للمشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص370، تحت «سر التعبير بقوله: ﴿تلقاء﴾ دون جهة»","url":""}]},{"id":"s7-255","number":255,"surah":7,"verses":[47],"references":[{"surah":7,"verses":[47]}],"verseLabel":"الأعراف: 47","question":"ما دلالة قولهم: ﴿ربنا لا تجعلنا مع القوم الظالمين﴾ بدلًا من: من أهل النار؟","answer":"ينفون عن أنفسهم مجرد المعية مع الظالمين، وهي أعم من أن يكونوا منهم؛ فيكون طلب النجاة من مصيرهم أولى. وذكر الظلم يبين سبب العذاب، فكأنهم يسألون الوقاية من العذاب ومن سببه الذي أورد أصحابه النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص372–373، تحت «سر التعبير بالمعية في قوله تعالى: ﴿مع القوم الظالمين﴾»","url":""}]},{"id":"s7-256","number":256,"surah":7,"verses":[48],"references":[{"surah":7,"verses":[48]}],"verseLabel":"الأعراف: 48","question":"لماذا نادى أصحاب الأعراف رجالًا ﴿يعرفونهم بسيماهم﴾؟","answer":"نادوهم للتوبيخ والتقرير بعدما عرفوهم بعلامات الكبر والكفر، وإظهار انقلاب منزلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص375–376، تحت «سر التعبير بالمناداة ﴿ونادى﴾ وأثره في المعنى»","url":""}]},{"id":"s7-257","number":257,"surah":7,"verses":[48],"references":[{"surah":7,"verses":[48]}],"verseLabel":"الأعراف: 48","question":"ما سرّ التعبير بقوله تعالى: ﴿ما أغنى عنكم جمعكم وما كنتم تستكبرون﴾؟","answer":"يحتمل الأسلوب النفي أو الاستفهام الإنكاري، ويؤدي في الحالين معنى التوبيخ والشماتة: لم ينفعهم جمع المال والرجال واستكبارهم، ولم يدفع عنهم العذاب. ففيه إبطال لما كانوا يعتزون به من قوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص379–380، تحت «سر التعبير بقوله: ﴿ما أغنى﴾ دون غيرها في الآية»","url":""}]},{"id":"s7-258","number":258,"surah":7,"verses":[48],"references":[{"surah":7,"verses":[48]}],"verseLabel":"الأعراف: 48","question":"لماذا عبّر عن أتباعهم أو أموالهم بـ﴿جمعكم﴾؟","answer":"﴿جمعكم﴾ اسم جامع لما كانوا يجمعونه من مال ورجال وأتباع، وما اعتزوا به من قوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص380–381، تحت «سر التعبير بلفظ ﴿جمعكم﴾ في أثناء السياق»","url":""}]},{"id":"s7-259","number":259,"surah":7,"verses":[49],"references":[{"surah":7,"verses":[49]}],"verseLabel":"الأعراف: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿أهؤلاء الذين أقسمتم لا ينالهم الله برحمة﴾؟","answer":"الاستفهام للتقرير والتوبيخ: هؤلاء الضعفاء الذين حلفتم ألا تصيبهم الرحمة قد أكرمهم الله، فظهر بطلان حكمكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص386–387، تحت «دلالة الاستفهام ﴿أهؤلاء﴾»","url":""}]},{"id":"s7-260","number":260,"surah":7,"verses":[49],"references":[{"surah":7,"verses":[49]}],"verseLabel":"الأعراف: 49","question":"لماذا عُدّيت الرحمة بفعل ﴿ينالهم﴾؟","answer":"النيل يصور الرحمة كعطاء يصل إليهم ويصيبهم فعلًا، فيقابل إنكار المستكبرين لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص388–389، تحت «بلاغة الاستعارة التصريحية التبعية»","url":""}]},{"id":"s7-261","number":261,"surah":7,"verses":[49],"references":[{"surah":7,"verses":[49]}],"verseLabel":"الأعراف: 49","question":"ما أثر مجيء ﴿ادخلوا الجنة﴾ مباشرة دون التصريح بفعل القول؟","answer":"يقرب حذف القول مشهد الإذن بالدخول، كأن السامع يتلقى البشارة مباشرة؛ إذ المقصود الإكرام والإنعام. ويذكر المصدر أن الخطاب يحتمل أصحاب الأعراف أو المؤمنين المستضعفين الذين كان المستكبرون يحتقرونهم، وفي الحالين يظهر بطلان حكم المستكبرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص391–392، تحت «دلالة عدم ذكر القول قبل قوله: ﴿ادخلوا الجنة﴾»","url":""}]},{"id":"s7-262","number":262,"surah":7,"verses":[49],"references":[{"surah":7,"verses":[49]}],"verseLabel":"الأعراف: 49","question":"لماذا جمع نفي الخوف والحزن بعد الأمر بالدخول؟","answer":"نفي الخوف يؤمنهم من المستقبل، ونفي الحزن يزيل ألم الماضي؛ فتم لهم الأمن عند الدخول.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص394–395، تحت «سر اختصاص نفي الخوف والحزن دون سواهما»","url":""}]},{"id":"s7-263","number":263,"surah":7,"verses":[50],"references":[{"surah":7,"verses":[50]}],"verseLabel":"الأعراف: 50","question":"ما سرّ طلب أصحاب النار بلفظ ﴿أفيضوا علينا من الماء﴾ بدلًا من: أعطونا ماء؟","answer":"الإفاضة إعطاء بكثرة وانصباب، فاختاروها لشدة عطشهم وحاجتهم إلى وفرة الماء لا مجرد قدر يسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص399–400، تحت «سر التعبير بلفظ الإفاضة دون السقيا»","url":""}]},{"id":"s7-264","number":264,"surah":7,"verses":[50],"references":[{"surah":7,"verses":[50]}],"verseLabel":"الأعراف: 50","question":"ما سرّ قولهم: ﴿أو مما رزقكم الله﴾ وإبهام سائر الرزق؟","answer":"أبهموا طمعًا في أي شيء من نعيم الجنة، فلا يهمهم نوع الرزق بعد الماء من شدة الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص403–404، تحت «دلالة حذف متعلق ﴿مما رزقكم الله﴾»","url":""}]},{"id":"s7-265","number":265,"surah":7,"verses":[50],"references":[{"surah":7,"verses":[50]}],"verseLabel":"الأعراف: 50","question":"لماذا جاء الرد: ﴿إن الله حرمهما على الكافرين﴾، فثنى الضمير؟","answer":"الضمير للماء وما رزق الله أهل الجنة؛ فثنى ليشمل المطلوبين معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص402–403، تحت «دلالة الجمع بين الماء والطعام»","url":""}]},{"id":"s7-266","number":266,"surah":7,"verses":[50],"references":[{"surah":7,"verses":[50]}],"verseLabel":"الأعراف: 50","question":"لماذا عُبّر عن المنع الأخروي بالتحريم؟","answer":"التحريم هنا المنع القطعي، لا حكم التكليف؛ أي قضى الله بحرمان الكافرين منهما في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص405، تحت «سر التعبير بالفعل حرم دون المنع في السياق»","url":""}]},{"id":"s7-267","number":267,"surah":7,"verses":[51],"references":[{"surah":7,"verses":[51]}],"verseLabel":"الأعراف: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿اتخذوا دينهم لهوًا ولعبًا﴾، وفي الأنعام: ﴿لعبًا ولهوًا﴾؟","answer":"من التوجيهات التي يذكرها المصدر مراعاة ترتيب أطوار العمر: فاللعب يغلب في الصبا، واللهو في الشباب. وفي الأعراف يحكى حالهم يوم القيامة بعد انقضاء الدنيا، فجاء اللهو ثم اللعب على ترتيب ما مضى، من الأقرب إلى الأبعد؛ أما في الأنعام فجاء اللعب ثم اللهو وفق ترتيب هذين الطورين في الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص418، تحت «المتشابه اللفظي بين آية الأعراف51 وآية العنكبوت64»","url":""}]},{"id":"s7-268","number":268,"surah":7,"verses":[51],"references":[{"surah":7,"verses":[51]}],"verseLabel":"الأعراف: 51","question":"ما سرّ تقديم اللهو هنا وأُخر في الأنعام؟","answer":"يوجه المصدر الفرق باختلاف جهة النظر إلى الدنيا: في الأعراف ينظر إليها من مشهد القيامة وقد مضت، فقدم اللهو الذي يغلب في الشباب على اللعب الذي يغلب في الصبا. وفي الأنعام روعي ترتيب الأطوار في الحياة، فقدم اللعب ثم اللهو. وهو وجه من وجوه التوجيه، لا حصر لمعنى الآيتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص418، تحت «المتشابه اللفظي بين آية الأعراف51 وآية العنكبوت64»","url":""}]},{"id":"s7-269","number":269,"surah":7,"verses":[51],"references":[{"surah":7,"verses":[51]}],"verseLabel":"الأعراف: 51","question":"ما المراد بقوله تعالى: ﴿فاليوم ننساهم كما نسوا لقاء يومهم هذا﴾، وهل النسيان هنا ذهول؟","answer":"النسيان من الله تركهم في العذاب وحرمانهم من الرحمة، لا ذهول العلم؛ جزاء إهمالهم الاستعداد للقاء يومهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص414–415، تحت «دلالة النسيان بين الحقيقة والمجاز»","url":""}]},{"id":"s7-270","number":270,"surah":7,"verses":[51],"references":[{"surah":7,"verses":[51]}],"verseLabel":"الأعراف: 51","question":"ما أثر إضافة اليوم إليهم والإشارة إليه في ﴿لقاء يومهم هذا﴾؟","answer":"إضافة اليوم إليهم تزيد تشنيع ترك الاستعداد لأمر يخصهم ويعود أثره عليهم. والإشارة بـ﴿هذا﴾ تقرعهم باليوم الحاضر الذي كانوا ينكرونه، وقد صار واقعًا مشاهدًا لا يستطيعون دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص416، تحت «بلاغة الإضافة في المركب الإضافي ﴿يومهم﴾»","url":""}]},{"id":"s7-271","number":271,"surah":7,"verses":[51],"references":[{"surah":7,"verses":[51]}],"verseLabel":"الأعراف: 51","question":"لماذا عطف ﴿وما كانوا بآياتنا يجحدون﴾ على نسيان اللقاء؟","answer":"جمعوا بين ترك الاستعداد للآخرة والجحود بالآيات؛ فالأول إعراض عملي والثاني إنكار اعتقادي، وكلاهما سبب الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص417، تحت «دلالة ترتيب أوصاف الكافرين في هذه الآية وما قبلها»","url":""}]},{"id":"s7-272","number":272,"surah":7,"verses":[52],"references":[{"surah":7,"verses":[52]}],"verseLabel":"الأعراف: 52","question":"ما وجه التعبير بـ﴿كتاب﴾ وتنكيره في ﴿ولقد جئناهم بكتاب﴾؟","answer":"يفيد لفظ الكتاب معنى يشمل جنس الكتب المنزلة، ويدخل فيه القرآن الذي واجههم بالحجة. وتنكيره للتعظيم: كتاب عظيم الشأن في هدايته وبيانه، ويحتمل التنويع؛ أي كتاب من جنس ما أنزل على الأمم من قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص425–426، تحت «غرض تنكير لفظ كتاب في قوله: ﴿بكتاب﴾»","url":""}]},{"id":"s7-273","number":273,"surah":7,"verses":[52],"references":[{"surah":7,"verses":[52]}],"verseLabel":"الأعراف: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿فصلناه على علم﴾، وما دلالة ﴿على﴾؟","answer":"﴿على﴾ تفيد التمكن والاستناد: فُصل الكتاب تفصيلًا قائمًا على علم محيط بالمصالح والحقائق، لا عن جهل أو مصادفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص427–428، تحت «سر استعمال حرف الاستعلاء في قوله: ﴿فصلناه على علم﴾»","url":""}]},{"id":"s7-274","number":274,"surah":7,"verses":[52],"references":[{"surah":7,"verses":[52]}],"verseLabel":"الأعراف: 52","question":"لماذا وصف الكتاب بأنه ﴿هدى ورحمة لقوم يؤمنون﴾؟","answer":"هو هدى بما يرشد إليه ورحمة بما يثمره اتباعه؛ وخص المؤمنين لأنهم المنتفعون بهذين الأثرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص428–429، تحت «دلالة عطف الرحمة على الهدى»","url":""}]},{"id":"s7-275","number":275,"surah":7,"verses":[53],"references":[{"surah":7,"verses":[53]}],"verseLabel":"الأعراف: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿هل ينظرون إلا تأويله﴾، واستعمل النظر بمعنى الانتظار؟","answer":"النظر هنا بمعنى الانتظار، وقد صور إعراضهم كحال من ينتظر وقوع الوعيد، تهكمًا بهم؛ فهم لا ينتظرونه حقيقة لأنهم يجحدونه. فكأنهم لم يبق لهم بعد إعراضهم عن الحجج إلا أن يعاينوا ما أنذروا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص435–436، تحت «بلاغة الاستعارة التهكمية في التعبير بالنظر في قوله: ﴿ينظرون﴾»","url":""}]},{"id":"s7-276","number":276,"surah":7,"verses":[53],"references":[{"surah":7,"verses":[53]}],"verseLabel":"الأعراف: 53","question":"ما معنى مجيء ﴿تأويل﴾ الكتاب؟","answer":"تأويله تحقق مآله ووقوع ما وعد به من البعث والحساب والثواب والعقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص432، تحت «شرح المفردات: ﴿تأويله﴾»","url":""}]},{"id":"s7-277","number":277,"surah":7,"verses":[53],"references":[{"surah":7,"verses":[53]}],"verseLabel":"الأعراف: 53","question":"لماذا وُصفوا بأنهم ﴿نسوه من قبل﴾؟","answer":"أي تركوا العمل به والإيمان بمآله مع قيامه بينهم، فعوملوا معاملة من نسي شيئًا ولم يعتن به.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص437–438، تحت «سر التعبير بالنسيان عن الترك»","url":""}]},{"id":"s7-278","number":278,"surah":7,"verses":[53],"references":[{"surah":7,"verses":[53]}],"verseLabel":"الأعراف: 53","question":"ما مناسبة قولهم: ﴿قد جاءت رسل ربنا بالحق﴾ بعد مجيء التأويل؟","answer":"قالوه عند مشاهدة تحقق أخبار الرسل، إقرارًا متأخرًا بصدقهم لا ينفع بعد فوات زمن الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص438–439، تحت «توجيه تخصيص قول الناسين دون غيره من أقوالهم بالذكر»","url":""}]},{"id":"s7-279","number":279,"surah":7,"verses":[53],"references":[{"surah":7,"verses":[53]}],"verseLabel":"الأعراف: 53","question":"لماذا طلبوا أولًا الشفعاء ثم طلبوا الرد إلى الدنيا؟","answer":"قدموا طلب الشفاعة لأنها تبدو لهم أقرب إلى إمكان الخلاص، أما الرد إلى الدنيا فأبعد وأشد تعذرًا. ويكشف الجمع بين الطلبين اضطرابهم وتعلقهم بأي سبيل للنجاة؛ فلا يلزم من ترتيب الكلام أن الطلب الثاني وقع بعد فراغهم من الأول واليأس منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص442–443، تحت «نكات تقديم طلب الشفاعة على الرد إلى الدنيا»","url":""}]},{"id":"s7-280","number":280,"surah":7,"verses":[53],"references":[{"surah":7,"verses":[53]}],"verseLabel":"الأعراف: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿قد خسروا أنفسهم وضل عنهم ما كانوا يفترون﴾؟","answer":"أضاعوا أنفسهم بإدخالها النار، وغابت عنهم الآلهة والأقوال التي اختلقوها فلم يبق لافترائهم أثر ينفعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص445–446، تحت «بلاغة التعبير في قوله تعالى: ﴿خسروا أنفسهم﴾»","url":""}]},{"id":"s7-281","number":281,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"كيف يستدل بخلق السماوات والأرض في ﴿إن ربكم الله الذي خلق السماوات والأرض﴾ على استحقاقه العبادة؟","answer":"ذكر الخلق وصفًا يقرر أن الله هو الرب المنعم المدبر، فيلزم المخاطبين بإفراده بالعبادة. فالخلق حقيقة يقرون بها، فجعلت دليلًا على ما أعرضوا عنه من توحيد الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص457، تحت «مناسبة ذكر الخلق للربوبية والأمر للألوهية»","url":""}]},{"id":"s7-282","number":282,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]},{"surah":14,"verses":[19]},{"surah":15,"verses":[85]}],"verseLabel":"الأعراف: 54؛ إبراهيم: 19؛ الحجر: 85","question":"ما دلالة ذكر السماوات والأرض في الاستدلال بالخلق في الأعراف54 وإبراهيم19 والحجر85؟","answer":"في الأعراف54: يستدل بخلق السماوات والأرض على أن الخالق هو الرب المستحق للعبادة، فتقام الحجة على من يقرون بالخلق ويعرضون عن إفراده بالألوهية.\n\nفي إبراهيم19: يوجه النظر إلى هذين الخلقين العظيمين للاستدلال بسعة القدرة على خلق الناس وإهلاكهم والإتيان بغيرهم، وأن الخلق قائم بالحق والحكمة.\n\nفي الحجر85: يأتي ذكر السماوات والأرض وما بينهما في مقام يعم الخلق؛ فجمع السماوات يستوعبها جميعًا، والأرض هي المعهودة للمخاطبين، وكل ذلك مخلوق بالحق لا عبثًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص455–456، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-283","number":283,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم استوى على العرش﴾، وما دلالة ﴿ثم﴾؟","answer":"الاستواء على العرش ثابت لله على الوجه اللائق به بلا تمثيل؛ و﴿ثم﴾ للترتيب في الخبر أو الرتبة وإظهار عظمة التدبير بعد الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص457–458، تحت «دلالة حرف ﴿ثم﴾ في قوله: ﴿ثم استوى﴾»","url":""}]},{"id":"s7-284","number":284,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"لماذا صُور الليل بأنه ﴿يغشي﴾ النهار؟","answer":"شُبه الليل بغطاء يلبس النهار ويستره بظلمته، فصوّر التعاقب إحاطةً وتغطية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص458–459، تحت «جزالة التعبير البلاغي في قوله: ﴿يغشي الليل النهار﴾»","url":""}]},{"id":"s7-285","number":285,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"كيف يصور ﴿يطلبه حثيثًا﴾ تعاقب الليل والنهار؟","answer":"يصور تعاقبهما بمطاردة طالب لمطلوب لا يفتر عنها، فيطلب الليل النهار الذي سبقه، أو يتعاقبان في طلب أحدهما الآخر. و﴿حثيثًا﴾ تزيد معنى الطلب الحثيث المتصل، فتدل الصورة على سرعة اللحاق واستمرار التعاقب دون انقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص459–460، تحت «أثر الاستعارة التمثيلية في تصوير المعنى»","url":""}]},{"id":"s7-286","number":286,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"لماذا عطف الشمس والقمر والنجوم منصوبة أو مرفوعة بحسب القراءة؟","answer":"في قراءة النصب تعطف الشمس والقمر والنجوم على السماوات، فتدخل في مفعول ﴿خلق﴾، وتكون ﴿مسخرات﴾ حالًا. وفي قراءة الرفع تكون الأسماء مبتدأ و﴿مسخرات﴾ خبرًا؛ فيستأنف بها تقرير خضوع هذه الأجرام لأمر الله. وكلا الوجهين ينتظم في الاستدلال على تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص460، تحت «دلالة الواو في قوله: ﴿والشمس﴾»","url":""}]},{"id":"s7-287","number":287,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]},{"surah":16,"verses":[12]}],"verseLabel":"الأعراف: 54؛ النحل: 12","question":"ما دلالة ﴿مسخرات بأمره﴾ في الأعراف54 والنحل12؟","answer":"في الأعراف54: يصور التسخير انقياد الشمس والقمر والنجوم لنظام مقدر لا تخرج عنه، و﴿بأمره﴾ ترد ذلك إلى قدرة الله وإرادته وتدبيره.\n\nفي النحل12: يبين التسخير انتظام هذه الأجرام في منافع العباد، و﴿بأمره﴾ تعني بأمره الكوني وقدرته، فلا تستقل هذه المخلوقات بتصرفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص461–462، تحت «دلالة الباء في قوله: ﴿بأمره﴾»","url":""}]},{"id":"s7-288","number":288,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"لماذا فُصل بين ﴿الخلق﴾ و﴿الأمر﴾: ﴿ألا له الخلق والأمر﴾؟","answer":"الخلق له وحده إيجادًا، والأمر له وحده حكمًا وتدبيرًا وتشريعًا؛ فجمع ملك الأعيان وملك التصرف فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص463–464، تحت «موقع قوله: ﴿ألا له الخلق والأمر﴾ من الكلام السابق»","url":""}]},{"id":"s7-289","number":289,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"لماذا خُتمت بـ﴿تبارك الله رب العالمين﴾؟","answer":"جاء التذييل بعد دلائل الخلق والتسخير إعلانًا لكثرة خير الله وعظمته واستحقاقه الربوبية للعالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص464–465، تحت «ربط جملة التذييل ﴿تبارك الله رب العالمين﴾»","url":""}]},{"id":"s7-290","number":290,"surah":7,"verses":[55],"references":[{"surah":7,"verses":[55]}],"verseLabel":"الأعراف: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿ادعوا ربكم﴾، واختار اسم الرب؟","answer":"اختير الرب لاستدعاء معنى التربية والإنعام والقرب من عباده، وهو أنسب بحال السائل المفتقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص471–472، تحت «سر التعبير بلفظ الربوبية في قوله: ﴿ادعوا ربكم﴾»","url":""}]},{"id":"s7-291","number":291,"surah":7,"verses":[55],"references":[{"surah":7,"verses":[55]}],"verseLabel":"الأعراف: 55","question":"لماذا جمع بين ﴿تضرعًا وخفية﴾؟","answer":"التضرع ذل القلب وخضوعه، والخفية إسرار الصوت وإبعاده عن الرياء؛ فجمع حال الباطن وأدب الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص472–473، تحت «دلالة الجمع بين التضرع والخفية»","url":""}]},{"id":"s7-292","number":292,"surah":7,"verses":[55],"references":[{"surah":7,"verses":[55]}],"verseLabel":"الأعراف: 55","question":"ما وجه التعبير بالتضرع مع الخفية، دون أن يقال: جهرًا وخفية؟","answer":"التضرع يصف ذل الداعي وخضوعه، والخفية تصف إسراره؛ فلا يتعارضان، بل يمكن أن يجتمعا. وإذا حمل التضرع على الدعاء الظاهر كان في اختياره بدل الجهر تنبيه إلى أدب العبودية؛ فالمقصود إظهار الحاجة والافتقار، لا مجرد رفع الصوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص472–473، تحت «فائدة وضع التضرع موضع الجهر»","url":""}]},{"id":"s7-293","number":293,"surah":7,"verses":[55],"references":[{"surah":7,"verses":[55]}],"verseLabel":"الأعراف: 55","question":"لماذا خُتمت بـ﴿إنه لا يحب المعتدين﴾، وما الاعتداء في الدعاء؟","answer":"يعلل الختام الأمر بأدب الدعاء، ويحذر من تجاوز حد العبودية والخضوع. ولم يقيد الاعتداء بنوع واحد؛ فيشمل الإخلال بأدب الدعاء وترك الطاعة واتباع غيرها، مع دخول مخالفة التضرع والخفية في النهي بحسب هذا السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص474–475، تحت «بلاغة الفاصلة القرآنية»","url":""}]},{"id":"s7-294","number":294,"surah":7,"verses":[55,205],"references":[{"surah":7,"verses":[55,205]}],"verseLabel":"الأعراف: 55، 205","question":"ما الفرق بين قوله في الدعاء: ﴿تضرعًا وخُفية﴾، وقوله في الذكر آخر الأعراف: ﴿تضرعًا وخِيفة﴾؟","answer":"﴿خُفية﴾ في آية الدعاء من الإخفاء؛ فهي تصف إسرار الداعي مع خضوعه. أما ﴿خِيفة﴾ في آية الذكر فمن الخوف، فتصف ما يصاحب الذكر من خشية وهيبة. وقد ذكر خفاء الذكر هناك بقوله ﴿في نفسك﴾ و﴿دون الجهر من القول﴾؛ فجمع السياقان أدب القلب وأدب الصوت بألفاظ تلائم كل موضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص468–469، تحت «شرح المفردات: ﴿خفية﴾»","url":""}]},{"id":"s7-295","number":295,"surah":7,"verses":[56],"references":[{"surah":7,"verses":[56]}],"verseLabel":"الأعراف: 56","question":"لم جاء النهي عن الإفساد في الأرض، دون الاكتفاء بالأمر بإصلاحها؟","answer":"في النهي عناية بترك الضرر؛ فدفع الفساد مقدم على تحصيل ما ينفع. والأرض مهيأة للصلاح، فينبه النهي إلى أن المطلوب صيانة ما أصلح وعدم تخريبه، كما أن ترك المنهي عنه أيسر من فعل المأمور به.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص479–480، تحت «علة إيثار النهي عن الإفساد دون الأمر بالإصلاح»","url":""}]},{"id":"s7-296","number":296,"surah":7,"verses":[56],"references":[{"surah":7,"verses":[56]}],"verseLabel":"الأعراف: 56","question":"لماذا قُيد النهي بقوله: ﴿بعد إصلاحها﴾؟","answer":"القيد يشدد القبح؛ فالإفساد بعد قيام الصلاح ونظامه نقض للنعمة وتخريب لما استقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص480، تحت «غرض التعبير بالظرف في قوله: ﴿بعد إصلاحها﴾»","url":""}]},{"id":"s7-297","number":297,"surah":7,"verses":[56],"references":[{"surah":7,"verses":[56]}],"verseLabel":"الأعراف: 56","question":"لماذا جمع في الدعاء بين ﴿خوفًا وطمعًا﴾؟","answer":"يبين الوصفان باعثي الدعاء: خوف التقصير والعقاب، والطمع في المغفرة والرحمة والفضل. فيظل الداعي بين الخوف والرجاء، فلا يأمن العقاب ولا ييأس من الرحمة، ويجتهد في الطاعة طلبًا للإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص481–482، تحت «معنى الواو في قوله: ﴿خوفًا وطمعًا﴾»","url":""}]},{"id":"s7-298","number":298,"surah":7,"verses":[56],"references":[{"surah":7,"verses":[56]}],"verseLabel":"الأعراف: 56","question":"ما دلالة الواو بين ﴿خوفًا وطمعًا﴾، وهل يلزم اجتماعهما في كل دعاء؟","answer":"يذكر المصدر وجه التقسيم: فقد يكون باعث الدعاء الخوف وطلب المغفرة، وقد يكون الطمع وطلب التوفيق والرحمة. ويجوز أن يجتمعا في الدعاء الواحد، لكن الجمع بينهما في الآية لا يوجب حضورهما معًا في كل دعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص482، تحت «معنى الواو في قوله: ﴿خوفًا وطمعًا﴾»","url":""}]},{"id":"s7-299","number":299,"surah":7,"verses":[56],"references":[{"surah":7,"verses":[56]}],"verseLabel":"الأعراف: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿إن رحمت الله قريب﴾، فوصف الرحمة المؤنثة بـ﴿قريب﴾؟","answer":"من الأوجه التي يذكرها المصدر مراعاة المعنى: أن الله قريب برحمته من المحسنين؛ فيعطى المضاف حكم المضاف إليه في التذكير. وفي العبارة تصوير لقرب حصول الرحمة ورجائه، وليس المقصود قرب مكان. وهذا توجيه من وجوه التعبير، لا قاعدة عامة تسوي بين المذكر والمؤنث في كل لفظ على وزن فعيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص482–483، تحت «نكتة تذكير لفظ ﴿قريب﴾»","url":""}]},{"id":"s7-300","number":300,"surah":7,"verses":[56],"references":[{"surah":7,"verses":[56]}],"verseLabel":"الأعراف: 56","question":"لماذا خُص المحسنون بقرب الرحمة؟","answer":"خُصوا لأن الإحسان امتثال الأمر وترك الإفساد والدعاء خوفًا وطمعًا؛ فمن حقق سببه كان أحق بقرب الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص484، تحت «توجيه المخصوص بالذكر في لفظ ﴿المحسنين﴾»","url":""}]},{"id":"s7-301","number":301,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿يرسل الرياح بشرًا بين يدي رحمته﴾؟","answer":"جعل إرسال الرياح المتنوعة المتتابعة بشارةً تتقدم نزول المطر؛ فـ﴿بين يدي رحمته﴾ تمثيل لسبقها الرحمة، والرحمة هنا المطر وما ينشأ عنه من حياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص491–492، تحت «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s7-302","number":302,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"لماذا جُمعت ﴿الرياح﴾ هنا، وتأتي ﴿الريح﴾ مفردة في مواضع العذاب؟","answer":"يذكر المصدر أن الجمع يناسب اختلاف الرياح وتعاونها في منافع المطر، وأن الإفراد يكثر في مواضع العذاب لما يصور من قوة ريح ذات جهة واحدة. وهذا توجيه أغلبي لا قاعدة مطردة؛ فقد وردت الريح مفردة في الرحمة، مثل ﴿وجرين بهم بريح طيبة﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص504–505، تحت «الرياح والريح»","url":""}]},{"id":"s7-303","number":303,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"لماذا سُمي المطر ﴿رحمته﴾؟","answer":"سُمّي المطر رحمةً لأنه سبب الرحمة؛ فبه تحيا الأرض ويخرج الرزق، فأطلق اسم الأثر على سببه بيانًا لعظم النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص492–493، تحت «سر تسمية المطر رحمة»","url":""}]},{"id":"s7-304","number":304,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"ما وجه التعبير بـ﴿أقلت سحابًا ثقالًا﴾، بدل حملت؟","answer":"الإقلال حمل يشعر بخفة المحمول بالنسبة إلى حامله وقدرته عليه. فالسحاب ثقيل بما فيه من الماء، ومع ذلك تحمله الرياح المسخرة بسهولة؛ فجمع التعبير بين ثقل السحاب وخفته بالنسبة إلى ما سخّر لحمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص505–506، تحت «أقلت وحملت»","url":""}]},{"id":"s7-305","number":305,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"لماذا جُمع ﴿ثقالًا﴾ مع إفراد ﴿سحابًا﴾؟","answer":"﴿سحاب﴾ اسم جنس جمعي يدل على قطع السحاب، فروعِي معناه الجمعي في وصفه بـ﴿ثقالًا﴾؛ وثقلها بما تحمله من الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص493–494، تحت «بلاغة استعمال جمع التكسير في قوله: ﴿ثقالًا﴾»","url":""}]},{"id":"s7-306","number":306,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"لماذا انتقل من الغيبة إلى التكلم: ﴿سقناه لبلد ميت فأنزلنا﴾؟","answer":"الانتقال من الغيبة إلى التكلم بضمير العظمة يزيد العناية بالفعل ويؤكد أنه جار بقدرة الله وتقديره. فيتوجه الانتباه إلى سوق السحاب إلى المكان المحدد له، ثم إنزال الماء وإخراج الثمرات.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص495، تحت «نكتة الالتفات في قوله تعالى: ﴿سقناه﴾»","url":""}]},{"id":"s7-307","number":307,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"ما الصورة في وصف البلد بـ﴿ميت﴾؟","answer":"شبه البلد المجدب الخالي من النبات بالميت الذي لا تظهر فيه الحياة ولا ينتفع به. ففي وصفه بالموت تصوير لشدة جدبه، ويهيئ ذلك للمقابلة بين إحياء الأرض بالنبات وإخراج الموتى.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص496، تحت «بلاغة المجاز في الاستعمال والإسناد في وصف البلد بميت»","url":""}]},{"id":"s7-308","number":308,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"لماذا شُبه إخراج الموتى بإخراج الثمرات: ﴿كذلك نخرج الموتى﴾؟","answer":"إحياء الأرض بالماء مثال محسوس لإحياء الأجساد؛ فالذي أخرج النبات من الأرض الميتة قادر على إخراج الموتى.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص498–499، تحت «بلاغة التشبيه في قوله: ﴿كذلك نخرج الموتى﴾»","url":""}]},{"id":"s7-309","number":309,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"ما سرّ التعبير في قوله تعالى في الأعراف والروم: ﴿يرسل الرياح﴾ بالمضارع، وفي الفرقان وفاطر: ﴿أرسل الرياح﴾ بالماضي؟","answer":"في الأعراف جاء ﴿يرسل﴾ بالمضارع ملائمًا لما قبله من ﴿يغشي﴾ والأمر بالدعاء والنهي عن الإفساد، وما فيها من توجه إلى المستقبل. وفي الروم48 ناسب المضارع ما سبق في الروم46: ﴿أن يرسل الرياح﴾. أما الفرقان فجاء ﴿أرسل﴾ مع سياق الأفعال الماضية في ذكر النعم، وفاطر جاء فيها الماضي بعد تذكير الناس بالنعم الماضية وما صدر به من وصف الخالق؛ فناسب كل تعبير نسق سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص500–501، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-310","number":310,"surah":7,"verses":[58],"references":[{"surah":7,"verses":[58]}],"verseLabel":"الأعراف: 58","question":"ما دلالة إضافة الرب إلى ضمير النبات في ﴿يخرج نباته بإذن ربه﴾؟","answer":"تشعر الربوبية بإنعام الله على النبات وتربيته وإمداده بما ينمو به. وتبين الإضافة عناية الخالق به، وأن خروجه الحسن إنما يكون بإذن ربه وتيسيره، فيلتفت السامع إلى نعمة الإنبات ومصدرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص517–518، تحت «سر إضافة ضمير النبات إلى لفظ الربوبية في قوله: ﴿بإذن ربه﴾»","url":""}]},{"id":"s7-311","number":311,"surah":7,"verses":[58],"references":[{"surah":7,"verses":[58]}],"verseLabel":"الأعراف: 58","question":"ما وجه إسناد الخروج إلى النبات ثم تقييده بـ﴿بإذن ربه﴾؟","answer":"صور النبات كأنه يخرج بنفسه، ثم رد هذا الخروج إلى مشيئة الله بقوله ﴿بإذن ربه﴾؛ فلا يستقل النبات بإيجاد نفسه أو نموه. وفي الصورة إظهار لانقياده لربه وافتقاره إلى إذنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص515–516، تحت «المجاز العقلي في قوله: ﴿يخرج نباته﴾»","url":""}]},{"id":"s7-312","number":312,"surah":7,"verses":[58],"references":[{"surah":7,"verses":[58]}],"verseLabel":"الأعراف: 58","question":"ما سرّ التعبير في قوله تعالى في البلد الخبيث: ﴿لا يخرج إلا نكدًا﴾، وحذف نباته؟","answer":"حُذف ﴿نباته﴾ لدلالة ما قبله عليه، ولتتجه العناية إلى هيئة الخروج: فلا يصدر من الأرض الخبيثة إلا خارج نكد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص519–520، تحت «غرض الحصر في قوله: ﴿لا يخرج إلا نكدًا﴾»","url":""}]},{"id":"s7-313","number":313,"surah":7,"verses":[58],"references":[{"surah":7,"verses":[58]}],"verseLabel":"الأعراف: 58","question":"لماذا اختير ﴿نكدًا﴾، لا: قليلًا؟","answer":"النكد ليس مجرد القلة، بل ما يخرج بعسر ويكون قليل الخير والمنفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص525–526، تحت «النكد والسيئ»","url":""}]},{"id":"s7-314","number":314,"surah":7,"verses":[58],"references":[{"surah":7,"verses":[58]}],"verseLabel":"الأعراف: 58","question":"لماذا صار اختلاف الأرض مثلًا لاختلاف القلوب؟","answer":"الأرض الطيبة تقبل الماء فتخرج النافع، والخبيثة لا تخرج إلا نكدًا؛ وكذلك القلوب: منها ما يقبل الوحي فيثمر، ومنها ما لا ينتفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص511–512، تحت «غرض التمثيل بالبلد الطيب والخبيث»","url":""}]},{"id":"s7-315","number":315,"surah":7,"verses":[58],"references":[{"surah":7,"verses":[58]}],"verseLabel":"الأعراف: 58","question":"لماذا خُتمت بـ﴿كذلك نصرف الآيات لقوم يشكرون﴾؟","answer":"خُتمت بالشكر لأن تصريف الدلائل وإنزال المطر وإخراج النبات نعم، ولا ينتفع بآياتها حقًا إلا من عرف المنعم وشكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص523–524، تحت «توجيه المخصوص بالذكر في قوله: ﴿لقوم يشكرون﴾»","url":""}]},{"id":"s7-316","number":316,"surah":7,"verses":[59],"references":[{"surah":7,"verses":[59]}],"verseLabel":"الأعراف: 59","question":"لماذا افتتحت قصص الرسل بنوح؟","answer":"بدأت القصص بنوح، أول رسول إلى أهل الأرض المشركين، ثم تتتابع أخبار الرسل للاعتبار بمصائر المكذبين والمؤمنين وتسلية الرسول ﷺ وتثبيته أمام تكذيب قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص530، تحت «فوائد القصص القرآني وأغراضه»","url":""}]},{"id":"s7-317","number":317,"surah":7,"verses":[59],"references":[{"surah":7,"verses":[59]}],"verseLabel":"الأعراف: 59","question":"ما سرّ نداء نوح قومه بقوله: ﴿يا قوم اعبدوا الله﴾؟","answer":"في ﴿يا قوم﴾ استمالة بنداء القرابة والقرب، وإظهار لشفقة الرسول على قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص533، تحت «فائدة إضافة ﴿يا قوم﴾ إلى ضمير المتكلم المحذوف»","url":""}]},{"id":"s7-318","number":318,"surah":7,"verses":[59],"references":[{"surah":7,"verses":[59]}],"verseLabel":"الأعراف: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿ما لكم من إله غيره﴾، دون أن يقال: لا إله إلا هو؟","answer":"ينفي الأسلوب أن يكون لهم أي إله مستحق للعبادة غير الله، و﴿من﴾ تؤكد استغراق النفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص534–535، تحت «الفرق بين قوله: ﴿وما من إله إلا الله﴾ وقوله: ﴿ما لكم من إله غيره﴾»","url":""}]},{"id":"s7-319","number":319,"surah":7,"verses":[59],"references":[{"surah":7,"verses":[59]}],"verseLabel":"الأعراف: 59","question":"ما سر التعبير بـ﴿إني أخاف عليكم﴾ دون: إني أحذركم؟","answer":"يظهر التعبير خوفه عليهم وحنوه وحرصه على نجاتهم، فيستميلهم بخطاب لين. فهو أنسب لإبراز شفقة الرسول من تحذير يشعر المخاطب بعلو المتكلم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص536، تحت «سر التعبير بقوله: ﴿أخاف﴾ دون: أحذركم»","url":""}]},{"id":"s7-320","number":320,"surah":7,"verses":[59],"references":[{"surah":7,"verses":[59]},{"surah":39,"verses":[13]}],"verseLabel":"الأعراف: 59؛ الزمر: 13","question":"ما سر وصف اليوم بالعظمة في ﴿عَذَابَ يَوْمٍ عَظِيمٍ﴾ بدل وصف العذاب نفسه؟","answer":"في الأعراف59: وصف اليوم بالعظمة لعظم ما يقع فيه من العذاب والأهوال؛ فعظمة الظرف تدل على عظمة ما يحتويه.\n\nوفي الزمر13: المراد يوم القيامة، وتعظيم اليوم لما فيه من الدواهي والأهوال يستلزم تعظيم العذاب الواقع فيه، وتزيد إضافة العذاب إلى ذلك اليوم من تهويله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص537، تحت «دلالة وصف اليوم بالعظيم»","url":""}]},{"id":"s7-321","number":321,"surah":7,"verses":[59],"references":[{"surah":7,"verses":[59]}],"verseLabel":"الأعراف: 59","question":"لماذا بدأت قصة نوح في الأعراف بـ﴿لقد أرسلنا نوحًا﴾ بلا واو، وفي هود والمؤمنون بـ﴿ولقد أرسلنا نوحًا﴾؟","answer":"في الأعراف استؤنفت القصة للانتقال من إقامة الحجة وذكر النعم والوعيد إلى الاعتبار بأخبار الأمم، فجاءت ﴿لقد أرسلنا﴾ مفصولة. وفي هود جاءت الواو لربط القصة بما سبق من تقرير الرسالة والإنذار. وفي المؤمنون هي واو استئنافية تبدأ أخبار الأمم بعد دلائل التوحيد وذكر الفلك. فالمسألة ارتباط كل قصة بسياقها، ولا يكفي تعليل الفرق بكونها أول قصة في السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص530–531، تحت «علة فصل جملة: ﴿لقد أرسلنا﴾ عما قبلها»","url":""}]},{"id":"s7-322","number":322,"surah":7,"verses":[60],"references":[{"surah":7,"verses":[60]}],"verseLabel":"الأعراف: 60","question":"لم أسند الرد على نوح إلى ﴿الملأ من قومه﴾ خاصة؟","answer":"لأن الملأ هم أشراف القوم وأصحاب الرأي والنفوذ فيهم، وهم أحرص على بقاء رئاستهم وأقدر على حمل العامة على مخالفة الرسول. فحكاية قولهم تبرز دور قادة القوم في مقاومة الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص541–542، تحت «علة إسناد القول إلى الملأ دون القوم»","url":""}]},{"id":"s7-323","number":323,"surah":7,"verses":[60],"references":[{"surah":7,"verses":[60]}],"verseLabel":"الأعراف: 60","question":"ما دلالة تعبير الملأ بـ﴿لنراك﴾ في اتهام نوح بالضلال؟","answer":"الرؤية هنا قلبية بمعنى العلم، فكأنهم يدعون أنهم يعلمون ضلاله علمًا لا شك فيه. وأكدوا اتهامهم بإن واللام لإظهار الجزم بدعواهم الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص543، تحت «سر التعبير بالرؤية في قوله: ﴿لنراك﴾»","url":""}]},{"id":"s7-324","number":324,"surah":7,"verses":[60],"references":[{"surah":7,"verses":[60]}],"verseLabel":"الأعراف: 60","question":"ما سرّ تعبيرهم بقولهم: ﴿في ضلال﴾، فجعلوه محيطًا به؟","answer":"صوّروا الضلال ظرفًا يحيط به ويتمكن منه، مبالغةً في اتهامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص543–544، تحت «بلاغة المجاز المرسل في قوله: ﴿في ضلال مبين﴾»","url":""}]},{"id":"s7-325","number":325,"surah":7,"verses":[61],"references":[{"surah":7,"verses":[61]}],"verseLabel":"الأعراف: 61","question":"لماذا أجاب نوح: ﴿ليس بي ضلالة﴾، ولم يقل: لست ضالًا؟","answer":"نفي أن تكون به ﴿ضلالة﴾ ينفي أن تلابسه أدنى خصلة من الضلال، وهو أبلغ من «لست ضالًا».","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص548–549، تحت «سر العدول عن نفي الضلال المبين إلى نفي الضلالة»","url":""}]},{"id":"s7-326","number":326,"surah":7,"verses":[61],"references":[{"surah":7,"verses":[61]}],"verseLabel":"الأعراف: 61","question":"لماذا أفرد ﴿ضلالة﴾ مع قولهم ﴿في ضلال﴾؟","answer":"أفرد ﴿ضلالة﴾ لينفي عنه فردًا واحدًا من جنس الضلال، فضلًا عن الغرق فيه كما زعموا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص548–549، تحت «سر العدول عن نفي الضلال المبين إلى نفي الضلالة»","url":""}]},{"id":"s7-327","number":327,"surah":7,"verses":[61],"references":[{"surah":7,"verses":[61]}],"verseLabel":"الأعراف: 61","question":"لماذا استدرك: ﴿ولكني رسول من رب العالمين﴾؟","answer":"الاستدراك يزيل تهمتهم ثم يثبت الحقيقة المقابلة: ليس به ضلالة، وإنما هو رسول من رب العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص550–551، تحت «بلاغة وصل جملة: ﴿ولكني رسول﴾ بما قبلها»","url":""}]},{"id":"s7-328","number":328,"surah":7,"verses":[62],"references":[{"surah":7,"verses":[62]}],"verseLabel":"الأعراف: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿أبلغكم رسالات ربي﴾ بالجمع؟","answer":"جُمعت ﴿رسالات﴾ لتعدد ما يبلغه من أوامر ونواه ومواعظ وأخبار، أو لأن أجزاء الرسالة المتتابعة بمنزلة رسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص556–557، تحت «نكتة الجمع في قوله: ﴿رسالات﴾»","url":""}]},{"id":"s7-329","number":329,"surah":7,"verses":[62],"references":[{"surah":7,"verses":[62]}],"verseLabel":"الأعراف: 62","question":"لماذا اختير المضارع ﴿أبلغكم وأنصح لكم﴾؟","answer":"المضارع يدل على تجدد التبليغ والنصح واستمرارهما، لا على فعل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص556، تحت «دلالة التعبير بالمضارع في قوله: ﴿أبلغكم﴾»","url":""}]},{"id":"s7-330","number":330,"surah":7,"verses":[62],"references":[{"surah":7,"verses":[62]}],"verseLabel":"الأعراف: 62","question":"لماذا عُدي النصح باللام: ﴿أنصح لكم﴾؟","answer":"عُدّي النصح باللام لأنه إرادة الخير للمنصوح وتوجيهه إلى ما ينفعه؛ فاللام تبرز منفعة نصحه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص559، تحت «سر التعبير بقوله: ﴿وأنصح لكم﴾ دون وأنصحكم»","url":""}]},{"id":"s7-331","number":331,"surah":7,"verses":[62],"references":[{"surah":7,"verses":[62]}],"verseLabel":"الأعراف: 62","question":"ما سرّ قول نوح لقومه في الأعراف: ﴿وأعلم من الله ما لا تعلمون﴾؟","answer":"أُسند العلم إلى نوح للدلالة على تمكنه منه، ثم قُيد بأنه من الله ليبيّن أن إنذاره قائم على الوحي وأحكام الله وعلمه بعاقبة التكذيب، لا على دعوى بشرية مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص560، تحت «نكتة إسناد العلم إلى نوح، ثم بيان أنه ﴿من الله﴾»","url":""}]},{"id":"s7-332","number":332,"surah":7,"verses":[63],"references":[{"surah":7,"verses":[63]}],"verseLabel":"الأعراف: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿أوعجبتم أن جاءكم ذكر من ربكم﴾ في صورة إنكار؟","answer":"الاستفهام إنكاري: لا موجب لتعجبهم من الوحي، فإرسال بشر منهم تقتضيه الحكمة ولا يصح ذريعة للتكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص567–568، تحت «غرض الاستفهام في قوله: ﴿أوعجبتم﴾»","url":""}]},{"id":"s7-333","number":333,"surah":7,"verses":[63],"references":[{"surah":7,"verses":[63]}],"verseLabel":"الأعراف: 63","question":"لماذا سُمي الوحي ﴿ذكرًا﴾؟","answer":"سمي الوحي ذكرًا لأنه موعظة تذكرهم بربهم وخالقهم وبما غفلوا عنه من أمره، فتوقظهم من الغفلة وتدعوهم إلى طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص565–566، تحت «شرح المفردات: ﴿ذكر﴾»","url":""}]},{"id":"s7-334","number":334,"surah":7,"verses":[63],"references":[{"surah":7,"verses":[63]}],"verseLabel":"الأعراف: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿على رجل منكم﴾، لا: إلى رجل؟","answer":"من توجيهاته أن ﴿جاءكم﴾ ضمن معنى نزل، فناسبه حرف الاستعلاء: جاءكم ذكر نازل على رجل منكم. وفي التعبير تصوير لمجيء الوحي من عند الله إلى الرسول ليبلغه قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص570–571، تحت «غرض استعمال حرف الاستعلاء ﴿على﴾»","url":""}]},{"id":"s7-335","number":335,"surah":7,"verses":[63],"references":[{"surah":7,"verses":[63]}],"verseLabel":"الأعراف: 63","question":"لماذا ذكر بشريته وقربه: ﴿رجل منكم﴾؟","answer":"﴿رجل منكم﴾ يرفع الاستغراب؛ فهو بشر يعرفون نسبه ولسانه وصدقه، فيسهل تلقي البيان عنه وتقوم الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص571، تحت «غرض التعبير بالرجولة في قوله: ﴿على رجل منكم﴾»","url":""}]},{"id":"s7-336","number":336,"surah":7,"verses":[63],"references":[{"surah":7,"verses":[63]}],"verseLabel":"الأعراف: 63","question":"لماذا ترتبت الغايات: ﴿لينذركم ولتتقوا ولعلكم ترحمون﴾؟","answer":"الترتيب سببي: جاء الذكر للإنذار، والإنذار يحمل على التقوى، والتقوى سبب يرجى به نيل الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص572–573، تحت «بلاغة ذكر التقوى إثر الإنذار في قوله: ﴿لينذركم ولتتقوا﴾»","url":""}]},{"id":"s7-337","number":337,"surah":7,"verses":[64],"references":[{"surah":7,"verses":[64]}],"verseLabel":"الأعراف: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿فكذبوه فأنجيناه﴾ بفاءين متتابعتين؟","answer":"الأولى تصل تكذيبهم بدعوته وتصور مبادرتهم إلى الرد. والثانية ترتب النجاة على ما انتهى إليه التكذيب، مع إيجاز أحداث طويلة بينهما؛ فالتعقيب فيها بحسب سياق القصة، ولا يعني أن الطوفان والنجاة وقعا فور أول دعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص579–580، تحت «بلاغة الإيجاز في قوله: ﴿فكذبوه فأنجيناه﴾»","url":""}]},{"id":"s7-338","number":338,"surah":7,"verses":[64],"references":[{"surah":7,"verses":[64]}],"verseLabel":"الأعراف: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين معه في الفلك﴾، دون أن يقال: ومن آمن معه؟","answer":"جمعت العبارة صحبتهم لنوح ووجودهم في وسيلة النجاة؛ فالعبرة بمن صدق واتبع وركب الفلك معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص581–582، تحت «بلاغة الإيجاز في قوله: ﴿والذين معه﴾»","url":""}]},{"id":"s7-339","number":339,"surah":7,"verses":[64],"references":[{"surah":7,"verses":[64]}],"verseLabel":"الأعراف: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿وأغرقنا الذين كذبوا بآياتنا﴾، فأظهر الصلة بدل الضمير؟","answer":"أظهر ﴿الذين كذبوا بآياتنا﴾ بدل الضمير لتسجيل سبب الإغراق عليهم: تكذيبهم بآيات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص584–585، تحت «نكتة التعبير بالاسم الموصول ﴿الذين﴾ دون الصريح المكذبين»","url":""}]},{"id":"s7-340","number":340,"surah":7,"verses":[64],"references":[{"surah":7,"verses":[64]}],"verseLabel":"الأعراف: 64","question":"لماذا خُتمت بـ﴿إنهم كانوا قومًا عمين﴾؟","answer":"الخاتمة تعلل التكذيب والإغراق بعمى البصيرة المتأصل؛ و﴿كانوا﴾ تدل على رسوخ الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص586–587، تحت «موجب فصل جملة: ﴿إنهم كانوا قومًا عمين﴾ عما قبلها»","url":""}]},{"id":"s7-341","number":341,"surah":7,"verses":[64],"references":[{"surah":7,"verses":[64]}],"verseLabel":"الأعراف: 64","question":"ما دلالة وصف قوم نوح بـ﴿عمين﴾؟","answer":"﴿عمين﴾ جمع عَمٍ، وهي صفة مشبهة تصف عمى القلب والبصيرة. فالمراد رسوخ الضلالة فيهم وعدم اهتدائهم إلى الحق، رغم طول دعوة نوح لهم، لا فقد حاسة البصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص587، تحت «سر تفرد هذه الآية بوصف قوم نوح بقوله: ﴿عمين﴾»","url":""}]},{"id":"s7-342","number":342,"surah":7,"verses":[64],"references":[{"surah":7,"verses":[64]}],"verseLabel":"الأعراف: 64","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿فأنجيناه والذين معه﴾، وفي يونس: ﴿فنجيناه ومن معه﴾؛ فاختار «أنجينا/الذين» هنا و«نجّينا/من» هناك؟","answer":"في يونس جاءت ﴿فنجيناه﴾ بالتضعيف لتلائم مقام إظهار تمام النجاة بعد تحدي نوح قومه وإعلامهم بعجزهم عن الإضرار به، ثم ذكر جعله ومن معه خلائف. وفي الأعراف جاء الإنباء بالنجاة بـ﴿فأنجيناه﴾. وأما الموصول، فـ﴿الذين معه﴾ ينوه بجماعة المؤمنين المعروفين بصحبته، و﴿من معه﴾ في يونس يشمل من أنجاهم الله معه من العقلاء وغيرهم. ولا يلزم من ذلك أن يكون اختيار الموصول ناشئًا عن تخفيف فعل النجاة أو تشديده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص581–582، تحت «توجيه المتشابه اللفظي بين ﴿فأنجيناه﴾ و﴿فنجيناه﴾»","url":""}]},{"id":"s7-343","number":343,"surah":7,"verses":[65],"references":[{"surah":7,"verses":[65]}],"verseLabel":"الأعراف: 65","question":"ما سرّ التعبير في قوله تعالى: ﴿وإلى عاد أخاهم هودًا﴾، فجعل هودًا أخًا لهم؟","answer":"الأخوة أخوة نسب وقوم، وفيها استمالة وإظهار للنصح والمودة؛ وليست أخوة دين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص590–591، تحت «شرح المفردات: ﴿أخاهم﴾»","url":""}]},{"id":"s7-344","number":344,"surah":7,"verses":[65],"references":[{"surah":7,"verses":[65]}],"verseLabel":"الأعراف: 65","question":"لماذا حُذف فعل الإرسال قبل ﴿إلى عاد﴾؟","answer":"حُذف ﴿أرسلنا﴾ اعتمادًا على قصة نوح، والتقدير: وأرسلنا إلى عاد أخاهم هودًا؛ فالإيجاز يربط القصص.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص591–592، تحت «دلالة العطف على الحذف»","url":""}]},{"id":"s7-345","number":345,"surah":7,"verses":[65],"references":[{"surah":7,"verses":[65]}],"verseLabel":"الأعراف: 65","question":"لماذا خُتمت دعوته بـ﴿أفلا تتقون﴾، بينما قال نوح: ﴿إني أخاف عليكم﴾؟","answer":"انتقل خطاب هود إلى التحضيض على التقوى بعد بيان عاقبة قوم نوح، فصار في مصيرهم زاجر يغني عن بسط الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص593–594، تحت «غرض الاستفهام في قوله: ﴿أفلا تتقون﴾»","url":""}]},{"id":"s7-346","number":346,"surah":7,"verses":[66],"references":[{"surah":7,"verses":[66]}],"verseLabel":"الأعراف: 66","question":"لماذا وصف المتكلمون بأنهم ﴿الملأ الذين كفروا من قومه﴾؟","answer":"من توجيهاته تمييز الملأ الكافرين من غيرهم ممن آمن وكتم إيمانه، ويذكر المصدر أيضًا حمل الوصف على الذم. وفي إبراز الكفر تسجيل لمنطلق موقفهم من الرسول، فلا يكون القيد لمجرد وجود غيرهم في مجموع القوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص596–597، تحت «فائدة ذكر قوله: ﴿الذين كفروا﴾»","url":""}]},{"id":"s7-347","number":347,"surah":7,"verses":[66],"references":[{"surah":7,"verses":[66]}],"verseLabel":"الأعراف: 66","question":"ما سرّ تعبير قوم هود عنه بأنه ﴿في سفاهة﴾، وتعبير قوم نوح عنه بأنه ﴿في ضلال﴾؟","answer":"يربط المصدر كل اتهام بسياقه: لما خوف نوح قومه بالطوفان وشرع في السفينة عدوا عمله في أرض لا ماء فيها ضلالًا عن الصواب. وأما هود فدعاهم إلى ترك آلهتهم، فعدوا العدول عن عبادة الآباء سفاهة وخفة عقل. وكلا الاتهامين باطل صادر عن فساد تصورهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص598–599، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-348","number":348,"surah":7,"verses":[66],"references":[{"surah":7,"verses":[66]}],"verseLabel":"الأعراف: 66","question":"لماذا أكدوا مرتين: ﴿إنا لنراك... وإنا لنظنك﴾؟","answer":"كرروا ﴿إنا﴾ واللام لتوكيد كل تهمة على حدة: السفاهة والكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص597، تحت «فائدة المؤكدات في الآية الكريمة»","url":""}]},{"id":"s7-349","number":349,"surah":7,"verses":[66],"references":[{"surah":7,"verses":[66]}],"verseLabel":"الأعراف: 66","question":"ما سرّ تعبيرهم في الكذب بـ﴿لنظنك من الكاذبين﴾، مع جزمهم بالسفاهة؟","answer":"على التوجيه الذي يذكره المصدر، ادعوا اليقين بسفاهته بسبب ما رأوه من مخالفته عبادتهم، فعبروا بالرؤية القلبية بمعنى العلم. أما اتهامه بالكذب فتوقفوا عن الجزم به وعبروا بالظن؛ إذ كان عندهم علم بالرسل وعاقبة مخالفتهم، ولم يبعد عهدهم بقصة نوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص597–598، تحت «سر إيثار التعبير بالرؤية في السفاهة والظن في الكذب»","url":""}]},{"id":"s7-350","number":350,"surah":7,"verses":[66],"references":[{"surah":7,"verses":[66]}],"verseLabel":"الأعراف: 66","question":"لماذا جاء جواب الملأ في الأعراف: ﴿قال الملأ﴾ بلا فاء، وفي هود والمؤمنون: ﴿فقال الملأ﴾؟","answer":"في الأعراف جاء قول الملأ مفصولًا على طريقة حكاية الحوار، كأنه جواب سؤال: ماذا قالوا حين دعاهم؟ وفي هود والمؤمنون جاءت الفاء لربط اعتراضهم بالدعوة السابقة وتصوير مبادرتهم إلى التكذيب. ومن خصوص سياق المؤمنون أنهم وجهوا الكلام إلى قومهم لتحريضهم، لا إلى نوح مباشرة. فترك الفاء في الأعراف لا يعني أن قولهم لا يصلح لغويًا جوابًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص596، تحت «سر مجيء ﴿قال الملأ﴾ بلا فاء وذكرها في سورة المؤمنون»","url":""}]},{"id":"s7-351","number":351,"surah":7,"verses":[67],"references":[{"surah":7,"verses":[67]}],"verseLabel":"الأعراف: 67","question":"ما بلاغة رد هود بـ﴿ليس بي سفاهة ولكني رسول من رب العالمين﴾؟","answer":"نفى السفاهة عن نفسه نفيًا عامًا من غير أن يقابلهم بمثل إساءتهم، ثم أثبت الرسالة المنافية لما نسبوه إليه. وفي هذا الرد جمع بين الحلم في مخاطبتهم وتفنيد التهمة بالحقيقة التي ينبغي أن يعرفوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص602–603، تحت «بلاغة الرد في قوله تعالى: ﴿ليس بي سفاهة﴾»","url":""}]},{"id":"s7-352","number":352,"surah":7,"verses":[67],"references":[{"surah":7,"verses":[67]}],"verseLabel":"الأعراف: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿رسول من رب العالمين﴾ كما قال نوح؟","answer":"التعبير نفسه يقرر وحدة مصدر الرسالات؛ فهود ونوح لا يدعوان لأنفسهما، وإنما يبلغ كل منهما عن رب العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص603–604، تحت «دلالة تنكير ﴿رسول﴾ وأنه ﴿من رب العالمين﴾»","url":""}]},{"id":"s7-353","number":353,"surah":7,"verses":[68],"references":[{"surah":7,"verses":[68]}],"verseLabel":"الأعراف: 68","question":"ما سرّ تعبير هود بقوله: ﴿أبلغكم رسالات ربي﴾ بالمضارع والجمع؟","answer":"المضارع لاستمرار التبليغ وتجدده، والجمع لتعدد ما يبلغه من أوامر ونواه ووعد ووعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص607–608، تحت «دلالة التعبير بالفعل المضارع: ﴿أبلغكم﴾»","url":""}]},{"id":"s7-354","number":354,"surah":7,"verses":[68],"references":[{"surah":7,"verses":[68]}],"verseLabel":"الأعراف: 68","question":"ما سرّ تعبير هود بقوله: ﴿وأنا لكم ناصح أمين﴾، وتعبير نوح بقوله: ﴿وأنصح لكم﴾؟","answer":"عبّر هود بالجملة الاسمية ﴿وأنا لكم ناصح أمين﴾ لإثبات رسوخ النصح والأمانة، وهو أنسب للرد على اتهامه بالكذب؛ أما نوح فذكر فعل النصح المتجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص610–611، تحت «التشابه بين قول نوح: ﴿أنصح لكم﴾ وقول هود: ﴿وأنا لكم ناصح أمين﴾»","url":""}]},{"id":"s7-355","number":355,"surah":7,"verses":[68],"references":[{"surah":7,"verses":[68]}],"verseLabel":"الأعراف: 68","question":"لماذا جمع هود بين ﴿ناصح﴾ و﴿أمين﴾؟","answer":"﴿ناصح﴾ يثبت إرادة الخير لهم، و﴿أمين﴾ يثبت صدقه في نقل رسالة ربه؛ فانتفى الغش في القصد والخيانة في البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص611، تحت «سر وصف الناصح بالأمانة في هذا الموضع الفريد»","url":""}]},{"id":"s7-356","number":356,"surah":7,"verses":[69],"references":[{"surah":7,"verses":[69]}],"verseLabel":"الأعراف: 69","question":"لماذا تكرر إنكار العجب نفسه في قصة هود؟","answer":"تكرر الإنكار لأن عادًا تعجبوا من الرسالة كما تعجب قوم نوح؛ فوحدة الشبهة اقتضت وحدة نقضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص614–615، تحت «الغرض من افتتاح الجملة بالاستفهام بالهمزة في قوله: ﴿أوعجبتم﴾»","url":""}]},{"id":"s7-357","number":357,"surah":7,"verses":[69],"references":[{"surah":7,"verses":[69]}],"verseLabel":"الأعراف: 69","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿لينذركم﴾ وحذف ﴿ولتتقوا ولعلكم ترحمون﴾؟","answer":"اكتفى بالإنذار لأن التحذير من الخطر أولى في هذا المقام، وحذف ما دل عليه من الغايات؛ فالإنذار يدعوهم إلى التقوى، والتقوى سبب الرحمة. وبذكر أول هذه السلسلة يستدل السامع على ما بعدها، كما صرح به خطاب نوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص618–619، تحت «فائدة تخصيص الإنذار دون التبشير»","url":""}]},{"id":"s7-358","number":358,"surah":7,"verses":[69],"references":[{"surah":7,"verses":[69]}],"verseLabel":"الأعراف: 69","question":"لماذا ذكّر عادًا بأنهم ﴿خلفاء من بعد قوم نوح﴾؟","answer":"ذكّرهم أنهم خلفاء بعد قوم نوح ليجمع لهم النعمة والعبرة: أورثهم الله الأرض بعد الهالكين، فلا يسلكوا طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص619–620، تحت «تلوين الخطاب بذكر النعم بعد ذكر النذارة»","url":""}]},{"id":"s7-359","number":359,"surah":7,"verses":[69],"references":[{"surah":7,"verses":[69]}],"verseLabel":"الأعراف: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿وزادكم في الخلق بسطة﴾؟","answer":"البسطة هي الزيادة في عظم الأجسام والقوة والقدرة؛ فذكّرهم بما خصهم الله به مما يقتضي الشكر لا الاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص621–622، تحت «دلالة لفظ الخلق بين المصدرية والاسمية وأثره في المعنى»","url":""}]},{"id":"s7-360","number":360,"surah":7,"verses":[69],"references":[{"surah":7,"verses":[69]}],"verseLabel":"الأعراف: 69","question":"لماذا كرر الأمر بالذكر: ﴿فاذكروا آلاء الله لعلكم تفلحون﴾؟","answer":"ذكّرهم أولًا بنعمتين مخصوصتين: الاستخلاف وزيادة الخلق، ثم عمم فقال ﴿فاذكروا آلاء الله﴾ ليشمل سائر النعم. فالتكرار توكيد للأمر بالذكر وانتقال من التفصيل إلى الإجمال، لا إعادة للنعمتين وحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص623–624، تحت «غرض تكرار التذكير بالنعم»","url":""}]},{"id":"s7-361","number":361,"surah":7,"verses":[70],"references":[{"surah":7,"verses":[70]}],"verseLabel":"الأعراف: 70","question":"ما سرّ تعبيرهم بقوله: ﴿أجئتنا لنعبد الله وحده﴾، فجعلوا التوحيد مستنكرًا؟","answer":"صاغوا التوحيد في صورة أمر مستنكر لأن ألفتهم للشرك قلبت موازينهم، حتى صار إفراد الخالق بالعبادة موضع تعجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص630–631، تحت «علة استنكارهم عبادة الله وحده دون الرب أو صفة أخرى»","url":""}]},{"id":"s7-362","number":362,"surah":7,"verses":[70],"references":[{"surah":7,"verses":[70]}],"verseLabel":"الأعراف: 70","question":"ما سرّ إسناد العبادة إلى الآباء في قولهم: ﴿ونذر ما كان يعبد آباؤنا﴾؟","answer":"احتجوا بعبادة الآباء بدل الحجة، تعظيمًا للموروث وتقليدًا له؛ فكشف التعبير أن مستندهم عادة السابقين لا سلطان من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص632–633، تحت «سر الإضافة إلى ضمير الجمع في قوله: ﴿يعبد آباؤنا﴾»","url":""}]},{"id":"s7-363","number":363,"surah":7,"verses":[70],"references":[{"surah":7,"verses":[70]}],"verseLabel":"الأعراف: 70","question":"ما سرّ طلبهم ﴿فأتنا بما تعدنا﴾، دون: بما تتوعدنا؟","answer":"سموا العذاب ﴿ما تعدنا﴾ تهكمًا وتحديًا؛ فالوعيد وعد من جهة الإخبار بأمر مستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص634–635، تحت «فائدة استعمال الوعد في الوعيد»","url":""}]},{"id":"s7-364","number":364,"surah":7,"verses":[70],"references":[{"surah":7,"verses":[70]}],"verseLabel":"الأعراف: 70","question":"لماذا قيدوا الطلب بـ﴿إن كنت من الصادقين﴾؟","answer":"علقوا طلب العذاب على صدقه استهزاءً وتكذيبًا: إن كنت صادقًا فيما تخبر به فأنزله بنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص635–636، تحت «نكتة استعمال إن الشرطية في قوله: ﴿إن كنت من الصادقين﴾»","url":""}]},{"id":"s7-365","number":365,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"ما سرّ تعبير هود بالماضي في قوله: ﴿قد وقع عليكم من ربكم رجس وغضب﴾؟","answer":"الماضي في ﴿وقع﴾ لتحقق العذاب ووجوبه وقربه حتى صُوّر كأنه وقع؛ فوعيد الله لا مرد له.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص640–641، تحت «سر العدول بالتعبير عن المستقبل بالفعل الماضي في ﴿قد وقع﴾»","url":""}]},{"id":"s7-366","number":366,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"لماذا جمع بين ﴿رجس وغضب﴾؟","answer":"يحتمل الرجس العذاب أو فساد النفس وخبثها. وعطف الغضب يزيد الوعيد شدة؛ فعلى معنى العذاب يجمع التعبير المؤاخذة وسببها، وعلى معنى خبث النفس يبين ما جرته ضلالتهم من الغضب. فاللفظان متكاملان في تصوير سوء حالهم وعاقبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص642–643، تحت «عطف الغضب على الرجس وتأخيره عليه»","url":""}]},{"id":"s7-367","number":367,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿أتجادلونني في أسماء سميتموها﴾، مع أن الجدال في معبودات؟","answer":"سمّاها أسماء لأنها لا تملك من حقيقة الألوهية إلا الألفاظ التي أطلقوها عليها؛ فالجدال في مسميات جوفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص643–644، تحت «نكتة التعبير عن الأصنام بالأسماء في مقام المجادلة»","url":""}]},{"id":"s7-368","number":368,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"لماذا كرر مادة الاسم: ﴿أسماء سميتموها﴾؟","answer":"تكرار مادة الاسم يفضح منشأها البشري: هي أسماء اخترعتموها أنتم وآباؤكم، ولم يجعل الله لمسمياتها ألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص644–645، تحت «بلاغة الجناس الاشتقاقي بين لفظي ﴿أسماء﴾ و﴿سميتموها﴾»","url":""}]},{"id":"s7-369","number":369,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿ما نزل الله بها من سلطان﴾؟","answer":"ينفي أن تكون لتلك المعبودات حجة منزلة من عند الله تثبت ألوهيتها. وسميت الحجة سلطانًا لقوتها وتسلطها على المعارض؛ فنفي السلطان يكشف أن الجدال قائم على أسماء واصطلاحات بشرية بلا برهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص645–646، تحت «سر إيثار التعبير بسلطان دون حجة»","url":""}]},{"id":"s7-370","number":370,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"لماذا خُتمت المواجهة بـ﴿فانتظروا إني معكم من المنتظرين﴾؟","answer":"هو تهديد بعد تمام الحجة: انتظروا العذاب الذي استعجلتموه، وأنا معكم منتظر لوعد الله، وفيه ثقة بتحققه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص647–648، تحت «بلاغة الفصل في قوله: ﴿إني معكم من المنتظرين﴾»","url":""}]},{"id":"s7-371","number":371,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"ما دلالة صيغة ﴿نزّل﴾ في نفي الحجة عن عبادة الأصنام: ﴿ما نزّل الله بها من سلطان﴾؟","answer":"من توجيه المصدر أن صيغة التفعيل تستحضر تنزيل الوحي وتجدد البيان، فيشمل النفي أن يكون قد جاءهم من الله برهان على ألوهية أصنامهم، دفعة أو متجددًا. فدعواهم لا تستند إلى شيء من الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص645–646، تحت «دلالة صيغة فعّل في قوله: ﴿ما نزّل﴾»","url":""}]},{"id":"s7-372","number":372,"surah":7,"verses":[72],"references":[{"surah":7,"verses":[72]}],"verseLabel":"الأعراف: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿فأنجيناه والذين معه برحمة منا﴾، فصرح بالرحمة؟","answer":"التصريح بـ﴿برحمة منا﴾ يبين أن النجاة فضل من الله ورحمته، لا استحقاقًا مستقلًا بالأعمال، وإن كانت صحبة الإيمان سببًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص652–653، تحت «معنى الباء في قوله: ﴿برحمة منا﴾ وموقع لفظ منا من معناها»","url":""}]},{"id":"s7-373","number":373,"surah":7,"verses":[72],"references":[{"surah":7,"verses":[72]}],"verseLabel":"الأعراف: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿وقطعنا دابر الذين كذبوا﴾؟","answer":"قطع الدابر استئصال آخر القوم وقطع أصلهم؛ فالكناية تصور هلاكًا عامًا لم يبق لهم بقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص653–654، تحت «بلاغة الكناية والعدول عن التعبير بهلاكهم إلى قطع دابرهم»","url":""}]},{"id":"s7-374","number":374,"surah":7,"verses":[72],"references":[{"surah":7,"verses":[72]}],"verseLabel":"الأعراف: 72","question":"لماذا عطف: ﴿وما كانوا مؤمنين﴾ بعد وصفهم بالتكذيب؟","answer":"عطف نفي الإيمان ليقرر أن التكذيب لم يكن عارضًا، بل صدر عن قوم لم يتلبسوا بالإيمان، وفيه بيان رسوخ سبب هلاكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص655–656، تحت «دلالة عطف: ﴿وما كانوا مؤمنين﴾ على ما قبلها»","url":""}]},{"id":"s7-375","number":375,"surah":7,"verses":[72],"references":[{"surah":7,"verses":[72]},{"surah":11,"verses":[58]}],"verseLabel":"الأعراف: 72؛ هود: 58","question":"ما سرّ التعبير في قوله تعالى في الأعراف عن هود: ﴿فأنجيناه﴾، وفي هود: ﴿نجّينا هودًا﴾ بصيغة التفعيل؟","answer":"يلائم التضعيف في ﴿نجّينا﴾ بسورة هود تفصيل النجاة وتكرار ذكرها: ﴿نجينا هودًا﴾ ثم ﴿ونجيناهم من عذاب غليظ﴾. وفي الأعراف ذكرت النجاة مرة واحدة فجاءت ﴿فأنجيناه﴾. والتكرار في هود يبرز عظم النعمة وشدة العذاب؛ ولا يلزم أن تكون الريح والعذاب الغليظ حادثتين منفصلتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص221، تحت «التشابه اللفظي بين آيتي هود والأعراف»","url":""}]},{"id":"s7-376","number":376,"surah":7,"verses":[72],"references":[{"surah":7,"verses":[72]},{"surah":41,"verses":[16]},{"surah":51,"verses":[41,42]},{"surah":69,"verses":[6,7,8]}],"verseLabel":"الأعراف: 72؛ فصلت: 16؛ الحاقة: 6–8؛ الذاريات: 41–42","question":"ما الذي تضيفه صور هلاك عاد المختلفة: ﴿وقطعنا دابر الذين كذبوا﴾ في الأعراف، و﴿ريحًا صرصرًا﴾ في فصلت، و﴿الريح العقيم﴾ في الذاريات، و﴿بريح صرصر عاتية﴾ في الحاقة؟","answer":"في الأعراف تبرز كناية قطع الدابر نتيجة الهلاك: الاستئصال الذي لا يبقي للمكذبين بقية. وفي فصلت تبرز ﴿صرصرًا﴾ شدة الريح وصوتها وبردها. وفي الذاريات تصفها ﴿العقيم﴾ بأنها لا تأتي بخير ولا نماء، وإنما تحمل الهلاك. وفي الحاقة تضيف ﴿عاتية﴾ تجاوزها الحد في القوة، ثم يفصل السياق مدة تسخيرها ومشهد صرعاهم. فالألفاظ تعرض جوانب متكاملة من العذاب ونتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص653–654، تحت «بلاغة الكناية والعدول عن التعبير بهلاكهم إلى قطع دابرهم»","url":""}]},{"id":"s7-377","number":377,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿وإلى ثمود أخاهم صالحًا﴾ على نسق هود؟","answer":"وصف صالح وهود بالأخوة لإبراز اشتراك كل منهما مع قومه في النسب، وفيه استمالة لهم بما بينهم من القرابة والتراحم. فهما يدعوان أقوامهما إلى الخير بلسان الناصح القريب، وليست الأخوة هنا موافقة لهم في الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص659–660، تحت «سر وصف صالح وهود بالأخوة لقومه وعدم وصف نوح بها»","url":""}]},{"id":"s7-378","number":378,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"لم أتبع صالح دعوته إلى التوحيد بقوله: ﴿قد جاءتكم بينة من ربكم﴾؟","answer":"لأن دعوته تقتضي بيان صدق رسالته، فكأنهم يسألون: ما الدليل على أنك مرسل إلينا؟ فجاء الجواب بالبينة المشاهدة، ثم بينها بقوله ﴿هذه ناقة الله لكم آية﴾، فجمعت الآية الدعوة وبرهانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص661–662، تحت «علة فصل قوله تعالى: ﴿قد جاءتكم بينة من ربكم﴾ عما قبله»","url":""}]},{"id":"s7-379","number":379,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"لماذا أضيفت الناقة إلى الله: ﴿ناقة الله﴾؟","answer":"أضيفت إلى الله تشريفًا وتعظيمًا، وإشارة إلى خصوصيتها بوصفها حجة وآية على صدق صالح. فهي آية خصهم الله بها، وفي الإضافة تنبيه إلى حرمتها ووجوب صيانتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص663، تحت «سر الإضافة في ﴿ناقة الله﴾»","url":""}]},{"id":"s7-380","number":380,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿لكم آية﴾ بتقديم ﴿لكم﴾؟","answer":"تقديم ﴿لكم﴾ يبرز اختصاصهم بالانتفاع بهذه الآية وقيام الحجة عليهم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص663–664، تحت «دلالة التخصيص بشبه الجملة ﴿لكم﴾»","url":""}]},{"id":"s7-381","number":381,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]},{"surah":11,"verses":[64]}],"verseLabel":"الأعراف: 73؛ هود: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿فذروها تأكل في أرض الله﴾؟","answer":"في الأعراف: 73: أي اتركوها حرة غير ممنوعة من الرعي؛ ووصف الأرض بأنها أرض الله يقرر ألا حق لهم في التضييق عليها فيما أباحه مالك الأرض.\n\nفي هود: 64: قابل ملكيتهم الضيقة بملك الله للأرض كلها؛ فلا حق لهم في منع آيته من رزقه، والمس بها يستجلب عذابًا قريبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص664–665، تحت «سر إضافة الأرض إلى اسم الله»","url":""}]},{"id":"s7-382","number":382,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"لماذا نُهي عن مجرد مسها بالسوء: ﴿ولا تمسوها بسوء﴾؟","answer":"النهي عن أدنى اتصال بسوء أبلغ في الحماية؛ فإذا حرم مجرد المس المؤذي كان العقر أولى بالتحريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص665–666، تحت «دلالة التعبير بالمس في قوله: ﴿ولا تمسوها بسوء﴾»","url":""}]},{"id":"s7-383","number":383,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿فيأخذكم عذاب أليم﴾، فجعل العذاب آخذًا؟","answer":"صور إصابة العذاب لهم بالأخذ، وهو أبلغ في تصوير تمكنه وإحاطته بهم. وأسند الأخذ إلى العذاب كأنه الآخذ بنفسه، فيقوى التهديد ويستحضر السامع هول المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص666، تحت «بلاغة الاستعارة في قوله: ﴿فيأخذكم﴾»","url":""}]},{"id":"s7-384","number":384,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"ما سرّ اختلاف وصف العذاب في قصة ناقة صالح: ﴿عذاب أليم﴾ في الأعراف، و﴿عذاب قريب﴾ في هود، و﴿عذاب يوم عظيم﴾ في الشعراء؟","answer":"في الأعراف وصف العذاب بالألم لإبراز أثره المؤذي في مقام الوعيد. وفي هود وصف بالقرب، وهو ملائم لقوله بعدها: ﴿تمتعوا في داركم ثلاثة أيام﴾. وفي الشعراء وصف يومه بالعظمة، ويذكر المصدر مناسبة ذكر اليوم لما سبق من تقسيم الشرب: ﴿لها شرب ولكم شرب يوم معلوم﴾؛ فلكل وصف جهة يبرزها من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص301–302، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-385","number":385,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"لماذا ذكّرهم بالاستخلاف من بعد عاد؟","answer":"ذكّرهم بالاستخلاف بعد عاد ليشكروا تمكين الله، وليعتبروا بهلاك من سبقهم حين كفروا وطغوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص676–677، تحت «فائدة ذكر عاد في قوله: ﴿من بعد عاد﴾»","url":""}]},{"id":"s7-386","number":386,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿وبوأكم في الأرض﴾، لا: أسكنكم؟","answer":"التبوئة ليست مجرد الإسكان، بل إنزالهم منازل مهيأة للاستقرار والانتفاع؛ فدل اللفظ على التمكين وحسن الإعداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص677–678، تحت «نكتة التعبير بلفظ: ﴿وبوأكم﴾»","url":""}]},{"id":"s7-387","number":387,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿تتخذون من سهولها قصورًا وتنحتون الجبال بيوتًا﴾؟","answer":"جمع بين القصور في السهول والبيوت المنحوتة في الجبال ليصور سعة تمكينهم وعمرانهم وانتفاعهم بلين الأرض وصلابتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص681–682، تحت «جمال الكناية عن التنعم في الآية»","url":""}]},{"id":"s7-388","number":388,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"لماذا عُدّي اتخاذ القصور بـ﴿من﴾، والنحت بلا حرف مماثل؟","answer":"تحتمل ﴿من﴾ التبعيض، أي يتخذون القصور من بعض السهول أو من مادتها، ويذكر المصدر وجهًا سببيًا أيضًا. أما ﴿تنحتون الجبال﴾ فأسند النحت إلى الجبال مباشرة للمبالغة في قوتهم وتمكنهم، حتى تبدو الجبال كأنها مطاوعة لصناعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص679، تحت «بلاغة استعمال ﴿من﴾ في ﴿من سهولها﴾»","url":""}]},{"id":"s7-389","number":389,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"لماذا تكرر: ﴿فاذكروا آلاء الله﴾ كما في قصة عاد؟","answer":"تكرر الأمر لأن ثمود أنعمت كما أنعمت عاد بالاستخلاف والتمكين؛ فتكرر موجب الشكر والتحذير من عاقبة الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص684–685، تحت «فائدة جمع لفظ ﴿آلاء﴾»","url":""}]},{"id":"s7-390","number":390,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تعثوا في الأرض مفسدين﴾، أليس العثو فسادًا؟","answer":"من توجيهاته أن ﴿مفسدين﴾ حال مؤكدة؛ لأن العثو هو شدة الفساد، فتزيد النهي تقريرًا وتشنيعًا. ويذكر المصدر احتمال أن تكون مقيدة لنوع العثو، فالمعنى ليس محصورًا في وجه إعرابي واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص686–687، تحت «الحال ﴿مفسدين﴾ بين التأكيد والتأسيس»","url":""}]},{"id":"s7-391","number":391,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وتنحتون الجبال بيوتًا﴾، وفي الشعراء: ﴿وتنحتون من الجبال بيوتًا﴾ بزيادة «من»؟","answer":"من توجيهاته أن ﴿من﴾ المذكورة قبلها في الأعراف: ﴿من سهولها قصورًا﴾ أغنت عن تكرارها، فجاء في الشعراء ﴿من الجبال﴾. ويذكر المصدر وجهًا آخر: حذفها في الأعراف يصور تمكنهم من نحت الجبال على سبيل المبالغة، وذكرها في الشعراء يبين أن النحت يقع في بعض الجبل؛ فالوجهان لا يختزلان في تعليل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص683–684، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-392","number":392,"surah":7,"verses":[75,88],"references":[{"surah":7,"verses":[75,88]}],"verseLabel":"الأعراف: 75؛ الأعراف: 88","question":"لماذا وُصف الملأ هنا بـ﴿الذين استكبروا﴾، ولم يقتصر على ﴿الملأ﴾؟","answer":"في الأعراف: 75: وصفهم بالاستكبار لأنه العلة التي صدتهم عن البينة وحملتهم على استضعاف المؤمنين ومجادلتهم.\n\nفي الأعراف: 88: وصفهم بالاستكبار لكشف الدافع إلى تهديد شعيب والمؤمنين؛ فالتعالي منعهم من قبول الحجة وحملهم على الإكراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص693–694، تحت «نكتة التعبير بالاستكبار لا الكفر»","url":""}]},{"id":"s7-393","number":393,"surah":7,"verses":[75],"references":[{"surah":7,"verses":[75]}],"verseLabel":"الأعراف: 75","question":"ما سرّ توجيه الخطاب إلى ﴿لمن آمن منهم﴾، ففرقوا داخل المستضعفين؟","answer":"في العبارة توجيهان بحسب مرجع ﴿منهم﴾: إن عاد إلى المستضعفين، خص الكلام المؤمنين من بينهم؛ وإن عاد إلى القوم، كان ﴿لمن آمن﴾ بيانًا للمستضعفين المقصودين، وهم المؤمنون. فالتركيب يحدد أهل الإيمان الذين وجه إليهم الملأ خطابهم، ولا يوجب وحده أن يكون بعض المستضعفين غير مؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص695، تحت «توجيه إعراب البدل في ﴿لمن آمن منهم﴾»","url":""}]},{"id":"s7-394","number":394,"surah":7,"verses":[75],"references":[{"surah":7,"verses":[75]}],"verseLabel":"الأعراف: 75","question":"ما سرّ سؤالهم: ﴿أتعلمون أن صالحًا مرسل من ربه﴾، دون: أتؤمنون؟","answer":"سؤالهم عن العلم تهكم يراد به زعزعة يقين المؤمنين؛ فسألوا عن ثبوت الرسالة كأنها دعوى بعيدة، لا طلبًا صادقًا للإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص696–697، تحت «غرض الاستفهام في قوله: ﴿أتعلمون﴾»","url":""}]},{"id":"s7-395","number":395,"surah":7,"verses":[75],"references":[{"surah":7,"verses":[75]}],"verseLabel":"الأعراف: 75","question":"ما سرّ جواب المؤمنين: ﴿إنا بما أرسل به مؤمنون﴾، دون الاكتفاء بنعم؟","answer":"أجابوا بجملة مؤكدة تثبت إيمانهم بما أرسل به، لا بمجرد شخصه؛ فكان أبلغ من «نعم» وأقوى في مواجهة الاستهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص698–699، تحت «نكتة العدول بالحديث عن الإيمان بدل الإرسال»","url":""}]},{"id":"s7-396","number":396,"surah":7,"verses":[76],"references":[{"surah":7,"verses":[76]}],"verseLabel":"الأعراف: 76","question":"ما سرّ جواب المستكبرين: ﴿إنا بالذي آمنتم به كافرون﴾؟","answer":"أعلنوا الكفر بنفس الرسالة التي أعلن المؤمنون الإيمان بها، فجاءت الصلة ﴿بالذي آمنتم به﴾ لإظهار المقابلة والعناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص702–703، تحت «دلالة التعبير بالموصول وصلته»","url":""}]},{"id":"s7-397","number":397,"surah":7,"verses":[76],"references":[{"surah":7,"verses":[76]}],"verseLabel":"الأعراف: 76","question":"لم قابل المستكبرون قول المؤمنين ﴿مؤمنون﴾ بقولهم ﴿كافرون﴾؟","answer":"جاء اسم الفاعل ﴿كافرون﴾ في مقابلة ﴿مؤمنون﴾ ليظهر إصرارهم على المناقضة والتحدي؛ فكأنهم يعلنون أن ثبات أولئك على الإيمان يقابله ثباتهم هم على الرفض، من غير مناقشة للحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص704، تحت «علة التعبير بصيغة اسم الفاعل: ﴿كافرون﴾»","url":""}]},{"id":"s7-398","number":398,"surah":7,"verses":[77],"references":[{"surah":7,"verses":[77]}],"verseLabel":"الأعراف: 77","question":"ما سرّ التعبير في قوله تعالى: ﴿فعقروا الناقة وعتوا عن أمر ربهم﴾، فجمع الفعل الحسي والتمرد القلبي؟","answer":"ذكر عقر الناقة أولًا لأنه أبرز مظهر من مظاهر تمردهم، ثم عطف عليه العتو الذي يشمله ويشمل غيره من العصيان. فهو من عطف العام على الخاص، ويبين أن فعلتهم لم تكن حادثة معزولة، بل مظهرًا لإصرارهم على مخالفة أمر ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص709–710، تحت «بلاغة العطف بين فعلي العقر والعتو»","url":""}]},{"id":"s7-399","number":399,"surah":7,"verses":[77,166],"references":[{"surah":7,"verses":[77,166]}],"verseLabel":"الأعراف: 77؛ الأعراف: 166","question":"لماذا عُدّي العتو بـ﴿عن﴾؟","answer":"في الأعراف77: ضمن العتو معنى الإعراض، فناسبه ﴿عن﴾؛ أي تمردوا معرضين عن أمر ربهم، ويذكر المصدر أيضًا وجه المجاوزة.\n\nوفي الأعراف166: يصور ﴿عتوا عن ما نهوا عنه﴾ إصرارهم على المخالفة وتجاوزهم النهي؛ فالمقام يبرز استمرار تمردهم بعد التذكير والتحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص709، تحت «بلاغة التضمين في تعدية الفعل ﴿وعتوا﴾ بحرف عن»","url":""}]},{"id":"s7-400","number":400,"surah":7,"verses":[77],"references":[{"surah":7,"verses":[77]}],"verseLabel":"الأعراف: 77","question":"لماذا نادوا صالحًا باسمه مجردًا: ﴿يا صالح﴾؟","answer":"نادوه باسمه مجردًا استخفافًا وتحديًا، فلم يعترفوا له بوصف الرسالة، ثم استعجلوا ما توعدهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص711، تحت «نكتة نداء صالح بالأداة يا المخصصة للبعيد»","url":""}]},{"id":"s7-401","number":401,"surah":7,"verses":[77],"references":[{"surah":7,"verses":[77]}],"verseLabel":"الأعراف: 77","question":"ما سرّ تكرار تحديهم بقولهم: ﴿ائتنا بما تعدنا﴾ على نسق عاد؟","answer":"كرروا تحدي عاد نفسه، فسمّوا الوعيد وعدًا تهكمًا واستعجالًا للعذاب، وأضافوا ﴿إن كنت من المرسلين﴾ زيادةً في التكذيب بالرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص711–712، تحت «لفظ الوعد بين الاستعارة التهكمية والحقيقة»","url":""}]},{"id":"s7-402","number":402,"surah":7,"verses":[78],"references":[{"surah":7,"verses":[78]}],"verseLabel":"الأعراف: 78","question":"لماذا اختيرت ﴿الرجفة﴾ لعذاب ثمود؟","answer":"تبرز ﴿الرجفة﴾ اضطراب الأرض وزلزلتها الشديدة، وتصويرها آخذة لهم يستحضر إحاطة العذاب بهم. وذكر الصيحة في موضع آخر يعرض جانب الصوت المهلك من الواقعة، فلا يلزم من اختلاف الوصف اختلاف الحادثة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص720–721، تحت «توجيه المتشابه اللفظي في ذكر الرجفة والصيحة والطاغية»","url":""}]},{"id":"s7-403","number":403,"surah":7,"verses":[78],"references":[{"surah":7,"verses":[78]}],"verseLabel":"الأعراف: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿فأصبحوا في دارهم جاثمين﴾، مع تعدد مساكنهم؟","answer":"أُفردت ﴿دارهم﴾ لأن المراد بلدهم أو جنس مساكنهم، فكأن الديار المتعددة دار واحدة جمعهم فيها المصير نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص721–722، تحت «نكتة إفراد الدار في جملة: ﴿فأصبحوا في دارهم﴾»","url":""}]},{"id":"s7-404","number":404,"surah":7,"verses":[78],"references":[{"surah":7,"verses":[78]}],"verseLabel":"الأعراف: 78","question":"لماذا اختير ﴿جاثمين﴾؟","answer":"الجثوم لزوم المكان مع السقوط على الركب أو الصدر؛ فصوّرهم هامدين ملتصقين بالأرض بعد قوتهم وحركتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص724، تحت «بلاغة التعبير بلفظ ﴿جاثمين﴾»","url":""}]},{"id":"s7-405","number":405,"surah":7,"verses":[78],"references":[{"surah":7,"verses":[78]}],"verseLabel":"الأعراف: 78","question":"ما سرّ التعبير في قوله تعالى عن ثمود في الأعراف: ﴿في دارهم جاثمين﴾ بالإفراد، وفي هود: ﴿في ديارهم جاثمين﴾ بالجمع؟","answer":"وحّد ﴿دارهم﴾ في الأعراف مع ذكر الرجفة، وهي زلزلة أرضهم الجامعة؛ وجمع ﴿ديارهم﴾ في هود مع الصيحة الآتية من السماء، إذ كان بلوغها أوسع وأبلغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص722–723، تحت «توجيه المتشابه اللفظي في إفراد الدار وجمعها»","url":""}]},{"id":"s7-406","number":406,"surah":7,"verses":[79,93],"references":[{"surah":7,"verses":[79,93]}],"verseLabel":"الأعراف: 79؛ الأعراف: 93","question":"ما سر خطاب صالح وشعيب قومهما بعد هلاكهم بقولهما: ﴿يا قوم لقد أبلغتكم﴾؟","answer":"في الأعراف79: على حمل الخطاب على ما بعد الهلاك، يتضمن تقريع المكذبين وإظهار انقطاع عذرهم، مع التحسر على أنهم لم يقبلوا البلاغ والنصح.\n\nوفي الأعراف93: يقرر شعيب أنه أدى الرسالة وأخلص النصيحة، فيوبخ قومه على الإعراض ويظهر تمام الحجة عليهم، ثم يبين سبب ترك الأسى عليهم بعدما أصروا على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص725–726، تحت «عنوان القومية ﴿يا قوم﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s7-407","number":407,"surah":7,"verses":[79],"references":[{"surah":7,"verses":[79]}],"verseLabel":"الأعراف: 79","question":"لماذا أفرد ﴿رسالة ربي﴾، بينما قال نوح وهود ﴿رسالات﴾؟","answer":"أفرد ﴿رسالة﴾ لأن أبرز ما حُكي في قصة صالح الأمر المتعلق بالناقة، فكأنها رسالة واحدة؛ أما القصص الأخرى فتعدد فيها المبلغ من الأوامر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص727، تحت «سبب إفراد لفظ الرسالة في ﴿رسالة ربي﴾»","url":""}]},{"id":"s7-408","number":408,"surah":7,"verses":[79],"references":[{"surah":7,"verses":[79]}],"verseLabel":"الأعراف: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكن لا تحبون الناصحين﴾، لا: لم تقبلوا نصحي؟","answer":"لم ينف مجرد قبولهم نصحه، بل أثبت فيهم نفرةً من جنس الناصحين؛ فالمشكلة فساد استعدادهم وكراهتهم لمن يريد لهم الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص728–729، تحت «بلاغة الكناية في جملة: ﴿لا تحبون الناصحين﴾»","url":""}]},{"id":"s7-409","number":409,"surah":7,"verses":[80],"references":[{"surah":7,"verses":[80]}],"verseLabel":"الأعراف: 80","question":"لم سماهم ﴿قومه﴾ في قصة لوط مع أنه لم يكن من نسبهم؟","answer":"أضيفوا إليه لأنه عاش بينهم وأرسل لإصلاحهم، فالعلاقة هنا علاقة معاشرة ورسالة. وفي تسميتهم قومه إبراز لصلته بهم وحرصه على دعوتهم، ولا يلزم أن تكون الإضافة دالة على النسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص734–735، تحت «فائدة إضافة قوم إلى الضمير العائد على لوط»","url":""}]},{"id":"s7-410","number":410,"surah":7,"verses":[80],"references":[{"surah":7,"verses":[80]}],"verseLabel":"الأعراف: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿أتأتون الفاحشة﴾ بالتعريف؟","answer":"من توجيهات التعريف أنه للعهد الذهني: الفعلة المعروفة بينهم. ويذكر المصدر حمله على الجنس مع المبالغة في قبحها، حتى كأنها جامعة لصفات الفحش؛ فالتعريف يحدد الفعل ويقوي التشنيع عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص736–737، تحت «معنى أل في لفظ ﴿الفاحشة﴾»","url":""}]},{"id":"s7-411","number":411,"surah":7,"verses":[80],"references":[{"surah":7,"verses":[80]}],"verseLabel":"الأعراف: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿ما سبقكم بها من أحد من العالمين﴾؟","answer":"نفى أن يكون أحد من العالمين سبقهم إليها، و﴿من﴾ تؤكد استغراق النفي؛ فجمع عليهم قبح الفاحشة وابتداعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص738–739، تحت «دلالة ﴿من﴾ في قوله تعالى: ﴿من أحد﴾»","url":""}]},{"id":"s7-412","number":412,"surah":7,"verses":[81],"references":[{"surah":7,"verses":[81]}],"verseLabel":"الأعراف: 81","question":"لماذا أكد: ﴿إنكم لتأتون الرجال شهوة﴾؟","answer":"في القراءة الخبرية أكد الكلام بإن واللام، فنزلوا منزلة من ينكر قبح فعله؛ لأنهم استمروا عليه غير مبالين بنهي لوط. وجاء التصريح بالفعل بعد إجماله باسم الفاحشة زيادة في التوبيخ والتقريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص742–743، تحت «بلاغة تأكيد الكلام في جملة ﴿إنكم لتأتون﴾»","url":""}]},{"id":"s7-413","number":413,"surah":7,"verses":[81],"references":[{"surah":7,"verses":[81]}],"verseLabel":"الأعراف: 81","question":"لماذا نصب ﴿شهوة﴾، ولم يقل: بشهوة؟","answer":"نُصبت على المفعول لأجله أو الحال؛ أي تأتونهم لأجل الشهوة أو مشتهين، فينكشف أن المحرك شهوة مجردة لا مقصد مشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص744–745، تحت «توجيه نكتة تقييد فعل الإتيان بلفظ ﴿شهوة﴾»","url":""}]},{"id":"s7-414","number":414,"surah":7,"verses":[81],"references":[{"surah":7,"verses":[81]}],"verseLabel":"الأعراف: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿من دون النساء﴾؟","answer":"أي متجاوزين النساء اللاتي جعلهن الله موضعًا للفطرة والإعفاف؛ فالتعبير يبرز العدول عن الطريق المشروع إلى ضده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص745–746، تحت «نكتة التعبير بالظرف دون»","url":""}]},{"id":"s7-415","number":415,"surah":7,"verses":[81],"references":[{"surah":7,"verses":[81]}],"verseLabel":"الأعراف: 81","question":"لماذا أضرب بقوله: ﴿بل أنتم قوم مسرفون﴾؟","answer":"﴿بل﴾ تترك مجرد وصف الفعل إلى كشف أصله في نفوسهم: الإسراف المتجاوز لكل حد هو الذي حملهم على تلك الفاحشة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص746–747، تحت «دلالة حرف الإضراب في قوله: ﴿بل أنتم قوم مسرفون﴾»","url":""}]},{"id":"s7-416","number":416,"surah":7,"verses":[81],"references":[{"surah":7,"verses":[81]}],"verseLabel":"الأعراف: 81","question":"لماذا خُتم إنكار فاحشة قوم لوط في الأعراف بـ﴿قوم مسرفون﴾، وفي النمل بـ﴿قوم تجهلون﴾؟","answer":"في الأعراف يبرز ﴿مسرفون﴾ تجاوزهم الحدود ورسوخ هذا الوصف فيهم، وجاء الاسم ملائمًا للفواصل الاسمية في السياق. وفي النمل يبرز ﴿تجهلون﴾ فساد تصرفهم مع وضوح الحق لهم؛ فالسورة تكثر فيها دلائل العلم، ومع ذلك يعملون عمل الجاهل. والمضارع يصور تجدد هذا التصرف واستمرارهم عليه، مع ملاءمته للفواصل الفعلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص747–748، تحت «سر اختيار مفردة الإسراف في وصف قوم لوط»","url":""}]},{"id":"s7-417","number":417,"surah":7,"verses":[82],"references":[{"surah":7,"verses":[82]}],"verseLabel":"الأعراف: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان جواب قومه إلا أن قالوا أخرجوهم﴾؟","answer":"أسلوب القصر يكشف أن ردهم الوحيد لم يكن حجة، بل قرار إقصاء: لم يجدوا جوابًا إلا إخراج الداعين إلى الطهارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص751–752، تحت «سر تسمية غير الجواب جوابًا»","url":""}]},{"id":"s7-418","number":418,"surah":7,"verses":[82],"references":[{"surah":7,"verses":[82]}],"verseLabel":"الأعراف: 82","question":"لماذا جُمِع لوط ومن معه في ﴿أخرجوهم من قريتكم﴾؟","answer":"جمعوه مع أهله ومن آمن به لأن إنكار الفاحشة والطهارة منها كان موقف جماعة، فصبوا تهديدهم على الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص750–751، تحت «دلالة إسناد الإخراج إلى ضمير الجمع في ﴿أخرجوهم﴾»","url":""}]},{"id":"s7-419","number":419,"surah":7,"verses":[82],"references":[{"surah":7,"verses":[82]}],"verseLabel":"الأعراف: 82","question":"لماذا أضافوا القرية إلى أنفسهم: ﴿قريتكم﴾؟","answer":"إضافتهم القرية إلى أنفسهم ادعاء للسلطان والاستئثار بها، وكأن الطاهرين غرباء لا حق لهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص753، تحت «دلالة الإضافة في قوله: ﴿قريتكم﴾»","url":""}]},{"id":"s7-420","number":420,"surah":7,"verses":[82],"references":[{"surah":7,"verses":[82]}],"verseLabel":"الأعراف: 82","question":"ما سرّ تعبيرهم الساخر: ﴿إنهم أناس يتطهرون﴾؟","answer":"قالوها سخرية وتنقصًا، فجعلوا تنزه لوط ومن معه عن فعلهم سببًا لإخراجهم. ومن مفارقة التعبير أن ما أرادوه ذمًا هو في حقيقته مدح بالطهارة؛ فتكشف عبارتهم فساد المعيار الذي يحاكمون به الداعين إلى الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص754–755، تحت «بلاغة الكناية في قوله: ﴿إنهم أناس يتطهرون﴾»","url":""}]},{"id":"s7-421","number":421,"surah":7,"verses":[82],"references":[{"surah":7,"verses":[82]}],"verseLabel":"الأعراف: 82","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وما كان جواب قومه﴾ بالواو، وفي النمل والعنكبوت: ﴿فما كان جواب قومه﴾ بالفاء؟","answer":"من توجيه المصدر أن الفاء تلائم إبراز تفرع الرد على الكلام السابق؛ ففي النمل ختم الإنكار بالفعلين ﴿تبصرون﴾ و﴿تجهلون﴾، وهما أنسب بتقدير معنى التسبب. وفي العنكبوت تفرع التحدي على تعداد أفعالهم وتقريعهم. أما الأعراف فختمت بالوصف ﴿مسرفون﴾، فجاءت الواو لربط حكاية جوابهم بما قبلها. وهذه مناسبة للسياقات المذكورة، وليست قاعدة تلزم كل اسم أو فعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص756–757، تحت «المتشابه اللفظي»","url":""}]},{"id":"s7-422","number":422,"surah":7,"verses":[82],"references":[{"surah":7,"verses":[82]}],"verseLabel":"الأعراف: 82","question":"ما سرّ التعبير في الأعراف: ﴿أخرجوهم من قريتكم﴾ بالضمير، وفي النمل: ﴿أخرجوا آل لوط من قريتكم﴾ بالاسم الظاهر؟","answer":"في الأعراف عُرف لوط وأهله من السياق فأغنى عن تسميتهم الضمير في ﴿أخرجوهم﴾. وفي النمل زاد تفصيل إنكار أفعال القوم وتقريعهم، فناسبه التصريح بـ﴿آل لوط﴾ في جوابهم؛ فوافق الإيجاز هنا والتصريح هناك بناء كل سياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص756–757، تحت «المتشابه اللفظي»","url":""}]},{"id":"s7-423","number":423,"surah":7,"verses":[83],"references":[{"surah":7,"verses":[83]}],"verseLabel":"الأعراف: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿فأنجيناه وأهله إلا امرأته﴾، دون أن يقال: وزوجه؟","answer":"يلفت المصدر إلى أن لفظ ﴿امرأته﴾ هنا يبرز اختلافها عنه في الدين والموقف، مع بقاء صلة النكاح؛ فهي من أهله في الظاهر، لكنها ليست معهم في الإيمان والنجاة. فالتسمية تلائم هذا الانفصال المعنوي في سياق الاستثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص762–763، تحت «امرأته وزوجه»","url":""}]},{"id":"s7-424","number":424,"surah":7,"verses":[83],"references":[{"surah":7,"verses":[83]}],"verseLabel":"الأعراف: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿كانت من الغابرين﴾، لا: فهلكت؟","answer":"﴿الغابرون﴾ الباقون خلف الراحلين؛ فصورتها ممن تخلف مع قومها عن ركب النجاة فشملها الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص760–761، تحت «بلاغة الاستئناف في ﴿كانت من الغابرين﴾»","url":""}]},{"id":"s7-425","number":425,"surah":7,"verses":[83],"references":[{"surah":7,"verses":[83]}],"verseLabel":"الأعراف: 83","question":"ما سرّ التعبير في قوله تعالى عن امرأة لوط في الأعراف: ﴿كانت من الغابرين﴾، وفي النمل: ﴿قدرناها من الغابرين﴾؟","answer":"﴿كانت﴾ تبين صيرورتها في الهالكين كما سبق في علم الله، و﴿قدرناها﴾ في النمل تصرح بأن ذلك كان بتقدير الله؛ فالثاني يبين منشأ الأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص761–762، تحت «المتشابه اللفظي»","url":""}]},{"id":"s7-426","number":426,"surah":7,"verses":[84],"references":[{"surah":7,"verses":[84]}],"verseLabel":"الأعراف: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿وأمطرنا عليهم مطرًا﴾، فكرر مادة المطر؟","answer":"ذكر المطر نكرة بعد فعل الإمطار لتعظيمه وتهويل نوعه؛ فهو مطر غير مألوف من حجارة العذاب. وفي تسميته مطرًا تصوير لنزول الحجارة متتابعة من السماء كما ينزل المطر، مع اختلاف أثرها المهلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص765–766، تحت «بلاغة الاستعارة في لفظ الإمطار في قوله: ﴿وأمطرنا عليهم مطرًا﴾»","url":""}]},{"id":"s7-427","number":427,"surah":7,"verses":[84],"references":[{"surah":7,"verses":[84]}],"verseLabel":"الأعراف: 84","question":"لماذا عُدّي المطر بـ﴿على﴾؟","answer":"عُدّي بـ﴿على﴾ لأن المطر انصب من فوقهم واستعلى عليهم، وفي الحرف إيحاء بإحاطة العذاب وقهره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص766، تحت «دلالة حرف الاستعلاء في جملة: ﴿عليهم مطرًا﴾»","url":""}]},{"id":"s7-428","number":428,"surah":7,"verses":[84],"references":[{"surah":7,"verses":[84]}],"verseLabel":"الأعراف: 84","question":"لماذا خُتمت القصة بـ﴿فانظر كيف كان عاقبة المجرمين﴾؟","answer":"الخاتمة تحول الخبر إلى عبرة مشاهدة، وتأمر بالنظر في مصير من أجرموا ليحذر المخاطبون طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص766–767، تحت «نوع الاستفهام في قوله: ﴿فانظر كيف كان عاقبة المجرمين﴾»","url":""}]},{"id":"s7-429","number":429,"surah":7,"verses":[84],"references":[{"surah":7,"verses":[84]}],"verseLabel":"الأعراف: 84","question":"لم ختم هلاك قوم لوط في الأعراف بـ﴿فانظر كيف كان عاقبة المجرمين﴾، وفي النمل بـ﴿فساء مطر المنذرين﴾؟","answer":"في الأعراف سبقت الإشارة إلى أنهم ابتدعوا الفاحشة: ﴿ما سبقكم بها من أحد من العالمين﴾، فناسبها وصفهم بالإجرام والأمر بالاعتبار بعاقبتهم. وفي النمل تتابع الإنذار والوعظ وتقريعهم مع إبصارهم ووضوح قبح فعلهم، فناسب وصفهم بالمنذرين وذم المطر الذي نزل بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص767–768، تحت «توجيه المتشابه بين الأعراف والنمل»","url":""}]},{"id":"s7-430","number":430,"surah":7,"verses":[85],"references":[{"surah":7,"verses":[85]}],"verseLabel":"الأعراف: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿وإلى مدين أخاهم شعيبًا﴾؟","answer":"الأخوة أخوة نسب وقوم، وفيها تقريب للنصح وإقامة للحجة بلسان رجل يعرفونه، لا أخوة موافقة في العقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص772–773، تحت «نكتة التعبير بلفظ الأخوة»","url":""}]},{"id":"s7-431","number":431,"surah":7,"verses":[85],"references":[{"surah":7,"verses":[85]}],"verseLabel":"الأعراف: 85","question":"لماذا انتقل شعيب من التوحيد إلى ﴿أوفوا الكيل والميزان﴾؟","answer":"بعد تقرير أصل التوحيد انتقل إلى أبرز فساد عملي اشتهروا به؛ لأن صحة العبادة تثمر العدل في معاملات الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص778–779، تحت «مناسبة الترتيب في الأوامر والنواهي»","url":""}]},{"id":"s7-432","number":432,"surah":7,"verses":[85],"references":[{"surah":7,"verses":[85]}],"verseLabel":"الأعراف: 85","question":"لماذا جمع بين الكيل والميزان؟","answer":"جمعهما ليستوعب وسائل تقدير الحقوق: المكيلات والموزونات، فلا يبقى باب للتطفيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص770، تحت «شرح المفردات: ﴿الكيل﴾ و﴿الميزان﴾»","url":""}]},{"id":"s7-433","number":433,"surah":7,"verses":[85],"references":[{"surah":7,"verses":[85]}],"verseLabel":"الأعراف: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تبخسوا الناس أشياءهم﴾، دون أن يقال: أموالهم؟","answer":"﴿أشياءهم﴾ أعم من الأموال؛ فيشمل كل حق مادي أو معنوي يجب توفيته، قليلًا كان أو كثيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص777–778، تحت «نكتة التعبير بلفظ: ﴿أشياءهم﴾»","url":""}]},{"id":"s7-434","number":434,"surah":7,"verses":[85],"references":[{"surah":7,"verses":[85]}],"verseLabel":"الأعراف: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿بعد إصلاحها﴾ كما في الآية 56؟","answer":"نهى عن إفساد الأرض بعد أن أصلحها الله بالشرائع والنظام والأمن، كما سبق في الآية 56؛ فالجريمة أشد بعد قيام الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص779–780، تحت «نكتة التعبير بالقيد: ﴿بعد إصلاحها﴾»","url":""}]},{"id":"s7-435","number":435,"surah":7,"verses":[85],"references":[{"surah":7,"verses":[85]}],"verseLabel":"الأعراف: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلكم خير لكم إن كنتم مؤمنين﴾؟","answer":"الإشارة تجمع التوحيد وإيفاء الحقوق وترك الفساد، وهذه خير لهم في الدنيا والآخرة إن صدق إيمانهم وعملوا بمقتضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص782–783، تحت «مناسبة التذييل بالجملة الشرطية»","url":""}]},{"id":"s7-436","number":436,"surah":7,"verses":[86],"references":[{"surah":7,"verses":[86]}],"verseLabel":"الأعراف: 86","question":"لماذا نهى: ﴿ولا تقعدوا بكل صراط توعدون﴾؟","answer":"نهى عن ترصد الطرق لتخويف الناس ومنعهم من شعيب ودين الله؛ فالقعود تصوير للملازمة والتعمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص786–787، تحت «جملة ﴿ولا تقعدوا﴾ بين الكناية والاستعارة التمثيلية»","url":""}]},{"id":"s7-437","number":437,"surah":7,"verses":[86],"references":[{"surah":7,"verses":[86]}],"verseLabel":"الأعراف: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿بكل صراط﴾ بالإفراد بعد ﴿كل﴾؟","answer":"﴿كل﴾ تضاف إلى المفرد لإفادة العموم، أي لا تقعدوا على أي طريق من الطرق؛ فالإفراد لا يحد المعنى بطريق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص787، تحت «دلالة التعبير بلفظ العموم ﴿بكل﴾»","url":""}]},{"id":"s7-438","number":438,"surah":7,"verses":[86],"references":[{"surah":7,"verses":[86]}],"verseLabel":"الأعراف: 86","question":"ما دلالة العطف في ﴿توعدون وتصدون عن سبيل الله... وتبغونها عوجًا﴾؟","answer":"يجمع العطف وجوهًا متغايرة من فسادهم: تخويف من يريد الإيمان، وصده عن طريق الحق، والطعن في سبيل الله وطلب الزيغ عنه. فالأفعال مترابطة في مقصد الإفساد، مع تميز كل وجه منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص790–791، تحت «دلالة العطف على المغايرة وترابط المعاني»","url":""}]},{"id":"s7-439","number":439,"surah":7,"verses":[86],"references":[{"surah":7,"verses":[86]}],"verseLabel":"الأعراف: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿واذكروا إذ كنتم قليلًا فكثركم﴾؟","answer":"ذكّرهم بنعمة التكثير بعد القلة ليدعوهم إلى الشكر وترك الصد عن الإيمان. ويحتمل التكثير كثرة العدد بعد القلة، والقوة بعد الضعف، والغنى بعد الفقر؛ فالتعبير يستحضر حالهم الأولى وما أنعم الله به عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص791–792، تحت «مناسبة الحديث عن تكثير العدد»","url":""}]},{"id":"s7-440","number":440,"surah":7,"verses":[86],"references":[{"surah":7,"verses":[86]}],"verseLabel":"الأعراف: 86","question":"لماذا خُتمت بـ﴿وانظروا كيف كان عاقبة المفسدين﴾؟","answer":"أمرهم أن يعتبروا بمصائر المفسدين قبلهم؛ فمن سنن الله أن الإفساد بعد الإصلاح ينتهي إلى الخسران والهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص792–793، تحت «سر الدعوة إلى النظر في عاقبة المفسدين»","url":""}]},{"id":"s7-441","number":441,"surah":7,"verses":[87],"references":[{"surah":7,"verses":[87]}],"verseLabel":"الأعراف: 87","question":"لم عبّر عن الفريقين بلفظ ﴿طائفة﴾ في ﴿وإن كان طائفة منكم آمنوا... وطائفة لم يؤمنوا﴾؟","answer":"الطائفة تطلق على جماعة من الناس، وفي اختيارها هنا إشارة إلى كثرة الفريقين؛ فلا يلزم من إيمان طائفة أن يكون الذين لم يؤمنوا قليلين بالنسبة إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص797، تحت «نكتة التعبير بلفظ ﴿طائفة﴾ دون ما يقاربها من الألفاظ»","url":""}]},{"id":"s7-442","number":442,"surah":7,"verses":[87],"references":[{"surah":7,"verses":[87]}],"verseLabel":"الأعراف: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿بِالذي أرسلت به﴾ بالبناء للمجهول؟","answer":"بُني ﴿أرسلت﴾ للمجهول لأن المقصود ما حُمّل من الرسالة لا تعيين المرسِل، وهو معلوم أنه الله من السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص799، تحت «نكتة التعبير بالفعل المبني للمفعول ﴿أرسلت﴾»","url":""}]},{"id":"s7-443","number":443,"surah":7,"verses":[87],"references":[{"surah":7,"verses":[87]}],"verseLabel":"الأعراف: 87","question":"لماذا أمر الفريقين بالصبر: ﴿فاصبروا حتى يحكم الله بيننا﴾؟","answer":"على توجيه الخطاب إلى الفريقين، يكون الصبر للمؤمنين على ما يصيبهم، ويكون في حق المكذبين بمعنى الانتظار والوعيد؛ حتى يفصل الله بينهما. ويذكر المصدر أيضًا قولًا بتخصيص الخطاب بالكافرين، فلا يجزم بأن الأمر موجه إلى الجميع على وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص799–800، تحت «فعل ﴿فاصبروا﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s7-444","number":444,"surah":7,"verses":[87],"references":[{"surah":7,"verses":[87]}],"verseLabel":"الأعراف: 87","question":"لماذا خُتمت بـ﴿وهو خير الحاكمين﴾؟","answer":"الخاتمة تثبت عدل الحكم وكماله وتطمئن المؤمنين؛ فلا حاكم أصدق ولا أعلم ولا أعدل من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص801–802، تحت «بلاغة التذييل بقوله: ﴿وهو خير الحاكمين﴾»","url":""}]},{"id":"s7-446","number":446,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا قدّموا إخراج شعيب على إعادته في ملتهم: ﴿لنخرجنك... أو لتعودن﴾؟","answer":"قدموا الإخراج لأنه العقوبة العاجلة التي يملكونها، ثم جعلوا الرجوع في ملتهم بديلًا يمنعها؛ فخيّروهم بين الوطن والعقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص17، تحت «نكتة تقديم القسم»","url":""}]},{"id":"s7-447","number":447,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا أكّدوا التهديد باللام والنون: ﴿لنخرجنك﴾ و﴿لتعودن﴾؟","answer":"اللام والنون الثقيلة توكد تصميمهم على إنفاذ أحد الأمرين، وتصور شدة التهديد والتسلط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص17، تحت «بلاغة حشد المؤكدات»","url":""}]},{"id":"s7-448","number":448,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"ما النكتة البلاغية في توسيط النداء باسم شعيب الظاهر؟","answer":"خصّوا شعيبًا بالاسم لأنه أصل الدعوة ومقدم المؤمنين، وجاء نداؤه باسمه في سياق التغليظ والتهديد وقلة الاحترام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص16–17، تحت «نكتة توسيط النداء بالاسم الظاهر لنبيهم»","url":""}]},{"id":"s7-1606","number":1606,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا قالوا: ﴿والذين آمنوا معك﴾، ولم يذكروا متعلق الإيمان؟","answer":"لأن خصوم شعيب لا يعترفون برسالته، فحذفوا متعلق الإيمان وعدلوا إلى وصف المصاحبة بقولهم ﴿معك﴾، مع إبراز ارتباط أتباعه به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص18، تحت «سر حذف متعلق الفعل ﴿آمنوا﴾»","url":""}]},{"id":"s7-449","number":449,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا حُذف متعلَّق ﴿آمنوا﴾، فلم يقل: آمنوا بك؟","answer":"لأن القائلين من خصوم شعيب لا يعترفون بالإيمان به، فاستعاضوا عن التصريح بمتعلق الإيمان بذكر المصاحبة في ﴿معك﴾. ويذكر المصدر أيضًا أن المتعلق معلوم من السياق، وأن حذفه يناسب مقام إنكارهم واستهجانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص18، تحت «سر حذف متعلق الفعل ﴿آمنوا﴾»","url":""}]},{"id":"s7-450","number":450,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"ما وجه قولهم لشعيب: ﴿لتعودن في ملتنا﴾ مع أنه نبي لم يكن على ملتهم؟","answer":"من استعمالات العود معنى الصيرورة، فيكون المراد: لتصيرن في ملتنا وتدخلن فيها، ولا يلزم أن يكون شعيب قد كان عليها من قبل. ويلائم ذلك تعديته بـ﴿في﴾ التي تصور الملة وعاءً يحيط بالداخل فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص17، تحت «سر تعدية لفظ العود بـ﴿في﴾»","url":""}]},{"id":"s7-451","number":451,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا عُدّي ﴿لتعودن﴾ بـ﴿في﴾: ﴿في ملتنا﴾؟","answer":"عُدّي العود بـ﴿في﴾ لتصوير الملة كالحيز المحيط بمن يدخل فيها ويتمكن منها، وفيه بيان إرادتهم دمج المؤمنين في باطلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص17، تحت «سر تعدية لفظ العود بـ﴿في﴾»","url":""}]},{"id":"s7-452","number":452,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا أجابهم شعيب باستفهام: ﴿أولو كنا كارهين﴾؟","answer":"الاستفهام إنكاري: أتجبروننا على ملتكم ولو كنا شديدي الكراهة لها؟ فهو رفض للإكراه وإظهار لبطلان عرضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص18–19، تحت «بلاغة الاستفهام في ﴿أولو﴾»","url":""}]},{"id":"s7-453","number":453,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا اختيرت ﴿لو﴾ في ﴿أولو كنا كارهين﴾، وحُذف جوابها؟","answer":"على جعل ﴿لو﴾ وصلية، تذكر الحالة التي كان ينبغي أن تمنع إجبارهم، وهي كراهتهم للملة؛ فيكون المعنى: أتردوننا إليها ولو كنا كارهين؟ وحذف جوابها لدلالة ما قبلها عليه، فيبالغ الاستفهام في إنكار الإكراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص19، تحت «نكتة التعبير بـ﴿لو﴾ في الفاصلة»","url":""}]},{"id":"s7-454","number":454,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"ما دلالة صيغة اسم الفاعل في ﴿أولو كنا كارهين﴾؟","answer":"تفيد صيغة ﴿كارهين﴾ ثبوت كراهيتهم للإذعان إلى ملة قومهم ودوامها، وتنزلها منزلة الخصلة المستقرة؛ فهي كراهة راسخة، لا انفعال عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص20، تحت «دلالة صيغة اسم الفاعل»","url":""}]},{"id":"s7-455","number":455,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿قد افترينا على الله كذبًا﴾، فجمع بين الافتراء والكذب؟","answer":"الافتراء هو اختلاق الكذب عمدًا ونسبته إلى الله؛ فذكر ﴿كذبًا﴾ يصرح بحقيقة الافتراء ويبالغ في تقبيحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص29، تحت «بلاغة مصدرية الكذب وتنكيره»","url":""}]},{"id":"s7-456","number":456,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لماذا جاء الشرط بـ﴿إن عدنا﴾ مع أن الخصوم قالوا: ﴿لتعودن﴾؟","answer":"جاء الشرط لبيان المحال المترتب على فرض رجوعهم: إن وقع العود الذي تطلبونه فقد افترينا؛ وليس فيه تردد في ثباتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص29–30، تحت «بلاغة الربط بين الشرط وجوابه»","url":""}]},{"id":"s7-457","number":457,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما دلالة ضمائر المتكلمين في جواب شعيب: ﴿افترينا﴾ و﴿عدنا﴾ و﴿نجانا﴾؟","answer":"يضم شعيب المؤمنين إلى نفسه في الجواب، فيظهر شدة اتباعهم له ومشاركتهم إياه في الثبات على الإيمان. وفي جمعهم بضمير واحد تواضع لهم وتأكيد أن دعوتهم ليست لمصلحة شخصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص28–29، تحت «علة التعبير بضمير المتكلم»","url":""}]},{"id":"s7-458","number":458,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿بعد إذ نجانا الله منها﴾، دون أن يقال: بعد أن خرجنا منها؟","answer":"سمّى مفارقة الملة نجاةً لأن الشرك هلاك، ولأن الخروج من سلطانه وفتنته فضل من الله لا مجرد انتقال بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص30، تحت «بلاغة الكناية في فعل الإنجاء»","url":""}]},{"id":"s7-459","number":459,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما دلالة التناوب بين اسم الجلالة ولفظ ﴿ربنا﴾ في جواب شعيب؟","answer":"يرسخ ذكر اسم الجلالة الإقرار بألوهية الله ووحدانيته، ويستحضر وصف ﴿ربنا﴾ ولايته للمؤمنين وتدبيره أمرهم. وفي الجمع بينهما رد على أهل الشرك الذين يتعلقون بغير الله ويعتمدون على أنفسهم وقوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص33، تحت «تناوب التعبير بأسماء الله وصفاته»","url":""}]},{"id":"s7-460","number":460,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يكون لنا أن نعود فيها﴾ بدل «ولن نعود فيها»؟","answer":"هذا التركيب ينفي الاستحقاق والإمكان اللائق بهم، لا مجرد نية مستقبلية؛ أي لا يصح ولا يستقيم لنا أن نعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص31، تحت «فائدة لام الجحود»","url":""}]},{"id":"s7-461","number":461,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لماذا استثنى: ﴿إلا أن يشاء الله ربنا﴾ بعد التصريح باستحالة العود؟","answer":"في الاستثناء تفويض الأمر إلى الله وتأدب معه، وإقرار بأن الدوام على الإيمان بتثبيته ومشيئته. فهو افتقار إليه وسؤال للثبات، مع البراءة من الاتكال على النفس، ويجري على أدب الأنبياء في تعليق أمرهم بعلم الله وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص31–32، تحت «سر التعبير بالمشيئة دون غيرها»","url":""}]},{"id":"s7-462","number":462,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لماذا وصف الله هنا بـ﴿ربنا﴾؟","answer":"اسم الرب يستحضر الولاية والتربية والحفظ؛ فهو الذي نجاهم ويتولى تثبيتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص32، تحت «فائدة إيثار لفظ الربوبية في قوله: ﴿إلا أن يشاء الله ربنا﴾»","url":""}]},{"id":"s7-463","number":463,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لماذا كرر ﴿ربنا﴾ في ﴿إلا أن يشاء الله ربنا وسع ربنا كل شيء علمًا﴾؟","answer":"في تكرار ﴿ربنا﴾ مضافًا إلى ضميرهم إظهار للافتقار إلى ربهم، وتلذذ بذكره واستحضار لربوبيته. ويؤكد هذا الإظهار تضرعهم وتفويضهم أمر الثبات إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص32–33، تحت «إيثار لفظ الرب مضافًا»","url":""}]},{"id":"s7-464","number":464,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿وسع ربنا كل شيء علمًا﴾، فجعل العلم تمييزًا للسعة؟","answer":"نُصب ﴿علمًا﴾ تمييزًا يفسر جهة السعة: ليست سعة مكان، بل إحاطة علم بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص33–34، تحت «بلاغة المجاز في لفظ السعة»","url":""}]},{"id":"s7-465","number":465,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لماذا قدّم الجار والمجرور في ﴿على الله توكلنا﴾؟","answer":"قدم ﴿على الله﴾ لإفادة الاختصاص والاهتمام: عليه وحده اعتمدنا في الثبات والحماية والحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص34، تحت «نكتة تقديم الجار والمجرور»","url":""}]},{"id":"s7-466","number":466,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿ربنا افتح بيننا وبين قومنا بالحق﴾، واختار «افتح» بمعنى احكم؟","answer":"الفتح أصله إزالة الإغلاق والفصل بين شيئين، فاستعير للحكم الذي يكشف الحق ويفصل النزاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص37–38، تحت «الفتح والفصل»","url":""}]},{"id":"s7-467","number":467,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لم كرر ﴿بين﴾ في ﴿ربنا افتح بيننا وبين قومنا بالحق﴾؟","answer":"يزيد التكرار تأكيد التباعد بين المؤمنين وقومهم بعد إصرار المكذبين على الكفر. ويقابله قوله السابق ﴿حتى يحكم الله بيننا﴾ حيث كان مقام الدعوة والمحاورة لا يزال قائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص35، تحت «فائدة تكرار الظرف ﴿بين﴾»","url":""}]},{"id":"s7-468","number":468,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لماذا خُتم الدعاء بـ﴿وأنت خير الفاتحين﴾ لا «خير الحاكمين» كما في الآية 87؟","answer":"لما دعا بلفظ ﴿افتح﴾ ناسبت الخاتمة ﴿خير الفاتحين﴾، أما الآية 87 فذكرت الحكم صراحة فختمت بـ﴿خير الحاكمين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص35–36، تحت «سر ختام جملة الفاصلة بالمصدر والجمع»","url":""}]},{"id":"s7-469","number":469,"surah":7,"verses":[90],"references":[{"surah":7,"verses":[90]}],"verseLabel":"الأعراف: 90","question":"لماذا أعيد وصف القادة بـ﴿الملأ الذين كفروا من قومه﴾ بعد وصفهم بالاستكبار؟","answer":"أعاد وصف الكفر لتسجيل حقيقة موقفهم بعد تهديدهم، ولأن خطابهم التالي تحريض عقدي يصد الناس عن اتباع شعيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص41، تحت «سر إيثار الوصف بالكفر دون غيره»","url":""}]},{"id":"s7-470","number":470,"surah":7,"verses":[90],"references":[{"surah":7,"verses":[90]}],"verseLabel":"الأعراف: 90","question":"ما دلالة صيغة الافتعال في قولهم: ﴿لئن اتبعتم شعيبًا﴾؟","answer":"تشير صيغة الاتباع هنا إلى الانقياد والمطاوعة، وقد جاء تهديد الملأ في مقام حمل قومهم على ترك مطاوعة شعيب والاستمرار على باطلهم. فالتعبير يتعلق بالاستجابة لدعوته واتباع طريقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص41–42، تحت «بلاغة صيغة الافتعال في فعل الاتباع»","url":""}]},{"id":"s7-471","number":471,"surah":7,"verses":[90,92],"references":[{"surah":7,"verses":[90,92]}],"verseLabel":"الأعراف: 90؛ الأعراف: 92","question":"ما أثر التعريف بالموصول في ﴿الملأ الذين كفروا من قومه﴾، ثم في ﴿الذين كذبوا شعيبًا﴾؟","answer":"في الأعراف: 90 يسجل وصف الملأ بالكفر حالهم الذميمة التي صدر عنها تهديد المؤمنين. وفي الأعراف: 92 يربط وصفهم بتكذيب شعيب بين جرمهم وهلاكهم وخسرانهم، فيبين سبب الحكم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص53، تحت «بلاغة التعريف بالموصول»","url":""}]},{"id":"s7-472","number":472,"surah":7,"verses":[90],"references":[{"surah":7,"verses":[90]}],"verseLabel":"الأعراف: 90","question":"لماذا أكدوا جوابهم بـ﴿إنكم إذًا لخاسرون﴾؟","answer":"أكدوا بـ﴿إن﴾ واللام، وجاءت ﴿إذًا﴾ جزاءً للاتباع المزعوم؛ فصوّروا الخسران نتيجة محققة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص42، تحت «بلاغة حشد المؤكدات»","url":""}]},{"id":"s7-473","number":473,"surah":7,"verses":[90],"references":[{"surah":7,"verses":[90]}],"verseLabel":"الأعراف: 90","question":"لماذا وصفوا المؤمنين بالخاسرين مع أن الخاسرين الحقيقيين هم المكذبون في الآية 92؟","answer":"سموا المؤمنين خاسرين لقلب الحقائق وتخويفهم من فوات مصالح الدنيا؛ ثم رد السياق القصر عليهم فأثبت أن المكذبين هم الخاسرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص52–53، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-474","number":474,"surah":7,"verses":[91],"references":[{"surah":7,"verses":[91]}],"verseLabel":"الأعراف: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿فأخذتهم الرجفة﴾، فجعل الرجفة آخذة لهم؟","answer":"جُعلت الرجفة آخذةً استعارةً لشدة إحاطتها بهم وتمكنها منهم، كآخذ لا يترك مأخوذه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص46، تحت «بلاغة المجاز في لفظ الأخذ»","url":""}]},{"id":"s7-475","number":475,"surah":7,"verses":[91],"references":[{"surah":7,"verses":[91]}],"verseLabel":"الأعراف: 91","question":"لماذا اختيرت ﴿الرجفة﴾ لعذاب قوم شعيب؟","answer":"ذكر الرجفة يلائم تهديدهم شعيبًا ومن آمن معه بالإخراج من أرضهم؛ فجاءهم ما زعزع الأرض تحتهم. ويذكر المصدر أن الرجفة والصيحة متلازمتان في هذا العذاب، وأن اختيار كل تعبير يناسب سياقه، فلا يدل اختلاف اللفظ على تناقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص46–47، تحت «توجيه التشابه في التعبير عن العذاب»","url":""}]},{"id":"s7-476","number":476,"surah":7,"verses":[91],"references":[{"surah":7,"verses":[91]}],"verseLabel":"الأعراف: 91","question":"كيف يصور لفظ ﴿فأصبحوا﴾ ظهور أثر العذاب في ﴿فأصبحوا في دارهم جاثمين﴾؟","answer":"يبرز التعبير ظهور هلاكهم في الصباح أمام الناس للعظة والاعتبار. ويشرح المصدر نظير العبارة بأن ﴿أصبحوا﴾ تحتمل معنى صاروا جاثمين وقت الصباح، أو دخلوا في الصباح وهم على تلك الحال؛ فلا يقتضي وجه الصيرورة إلغاء الدلالة على الصباح.","sources":[{"label":"[نظير العبارة في الأعراف: 78] موسوعة التفسير البلاغي، ج13، ص720، تحت «سر استعمال لفظ ﴿فأصبحوا﴾»","url":""}]},{"id":"s7-477","number":477,"surah":7,"verses":[91],"references":[{"surah":7,"verses":[91]}],"verseLabel":"الأعراف: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿في دارهم﴾ بالإفراد مع أنهم جماعة؟","answer":"أُفردت الدار بمعنى البلد أو جنس المساكن، فوحد المصير مساكن الجماعة كأنها دار واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص48–49، تحت «قصدية التعبير بلفظ الدار مفردًا»","url":""}]},{"id":"s7-478","number":478,"surah":7,"verses":[91],"references":[{"surah":7,"verses":[91]}],"verseLabel":"الأعراف: 91","question":"لماذا صُوّر هلاكهم بقوله: ﴿جاثمين﴾؟","answer":"الجثوم لزوم الأرض بلا حركة؛ فصور أجسادهم ساقطة هامدة بعد قوتهم وتهديدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص49–50، تحت «بلاغة الاستعارة في لفظ ﴿جاثمين﴾»","url":""}]},{"id":"s7-479","number":479,"surah":7,"verses":[91],"references":[{"surah":7,"verses":[91]}],"verseLabel":"الأعراف: 91","question":"ما مناسبة ﴿جاثمين﴾ لتهديدهم شعيبًا بالإخراج من القرية؟","answer":"توعدوا شعيبًا والمؤمنين بإخراجهم من القرية، فانقلب الأمر عليهم؛ صار المهددون أنفسهم جثثًا هامدة في مساكنهم. وتصور ﴿جاثمين﴾ زوال حركتهم وقوتهم بعد ما أظهروه من السلطان والتهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص49، تحت «بلاغة الاستعارة في لفظ ﴿جاثمين﴾»","url":""}]},{"id":"s7-480","number":480,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"لماذا أعيد الموصول: ﴿الذين كذبوا شعيبًا﴾ مرتين؟","answer":"تكرار الموصول يثبت الحكمين للفئة نفسها ويشهر سبب مصيرها: تكذيب شعيب، لا عارض آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص54، تحت «نكتة تكرار جملة ﴿الذين كذبوا شعيبًا﴾»","url":""}]},{"id":"s7-482","number":482,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"لماذا شُبّهوا بمن لم يقيموا في الديار: ﴿كأن لم يغنوا فيها﴾؟","answer":"مُحيت آثارهم وانقطع أنسهم بالديار حتى صار حالها كأنهم لم يقيموا فيها يومًا، بعد ادعائهم ملك القرية والتمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص54، تحت «بلاغة التشبيه في الآية»","url":""}]},{"id":"s7-483","number":483,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"كيف يسهم معنى ﴿يغنوا﴾ في تصوير مصير المكذبين؟","answer":"معنى ﴿يغنوا﴾ هنا يقيموا ويعيشوا؛ فنفيه يصور زوالهم عن الديار حتى كأنهم لم يكونوا من أهلها ولم يقيموا فيها. وبه يشتد تصوير انقطاع حياتهم واندثار مقامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص52، تحت «شرح المفردات: ﴿يغنوا﴾»","url":""}]},{"id":"s7-484","number":484,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"ما سر تقديم الموصول في قوله: ﴿الذين كذبوا شعيبًا كانوا هم الخاسرين﴾؟","answer":"تقديم الموصول يقوي الحكم بالخسران عليهم، وتجيء الجملة الاسمية بما يفيد ثبوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص54، تحت «سر تقديم الموصول»","url":""}]},{"id":"s7-1607","number":1607,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"ما دلالة ضمير الفصل في قوله: ﴿كانوا هم الخاسرين﴾؟","answer":"يؤكد ضمير الفصل اختصاص المكذبين بالخسران في مقابل المؤمنين، ردًا على دعواهم أن أتباع شعيب هم الخاسرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص55، تحت «بديع التعبير بضمير الفصل»","url":""}]},{"id":"s7-485","number":485,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"لماذا أُتي بضمير الفصل ﴿هم﴾؟","answer":"ضمير الفصل ﴿هم﴾ يفيد القصر والتوكيد: هم الخاسرون حقًا، لا المؤمنون الذين رموهم بالخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص55، تحت «بديع التعبير بضمير الفصل»","url":""}]},{"id":"s7-486","number":486,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"لماذا خُتمت القصة بـ﴿الخاسرين﴾ بعد أن نسبوا الخسران إلى أتباع شعيب؟","answer":"جاءت الخاتمة ردًا مطابقًا لمقالتهم؛ فقلبت دعواهم وأثبتت أن من فقد نفسه ودياره هو الخاسر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص54–55، تحت «نكتة تكرار جملة ﴿الذين كذبوا شعيبًا﴾»","url":""}]},{"id":"s7-487","number":487,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"ما علة إيثار الفاء في قوله: ﴿فتولى عنهم﴾؟","answer":"تفيد الفاء ترتيب توليه على ما تقدم وتعقيبه له.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص59، تحت «علة إيثار الفاء في مطلع الآية»","url":""}]},{"id":"s7-1608","number":1608,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"ما وجه المجاز في لفظ التولي في قوله: ﴿فتولى عنهم﴾؟","answer":"يحتمل التولي المفارقة الحسية عقب العقوبة، ويحتمل الإعراض عن نصحهم قبل الرجفة؛ فالتعبير يصور انصرافه عن قوم أعرضوا عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص60، تحت «وجه المجاز في لفظ التولي»","url":""}]},{"id":"s7-489","number":489,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"ما سرّ تعبير شعيب بالماضي ﴿أبلغتكم﴾، وتعبير نوح بالمضارع ﴿أبلغكم﴾؟","answer":"ورد مضارع نوح ﴿أبلغكم﴾ في سياق عرضه مهمة تبليغ الرسالة واستمرارها، أما ماضي شعيب ﴿أبلغتكم﴾ فورد في ختام قصته لتقرير أنه قد أدى البلاغ. فاختلاف الصيغة يناسب موضع الكلام من عرض الدعوة أو تسجيل تمام أدائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص61–62، تحت «براعة عطف الأفعال، والأسماء»","url":""}]},{"id":"s7-490","number":490,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿رسالات ربي﴾ بالجمع، وقال صالح: ﴿رسالة ربي﴾ بالإفراد؟","answer":"من توجيهات المصدر أن جمع ﴿رسالات﴾ عند شعيب يناسب تعدد ما بلغه من أوامر ونواهٍ، كالتوحيد والوفاء بالكيل والميزان وترك البخس. وأفردت رسالة صالح، على أحد الأوجه، لأن أمر الناقة كان أبرز ما أرسل به إلى قومه؛ ويذكر المصدر للجمع والإفراد توجيهات أخرى أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص62، تحت «علة جمع لفظ ﴿رسالات﴾»","url":""}]},{"id":"s7-491","number":491,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"لماذا أضاف الرب إلى نفسه: ﴿ربي﴾، بينما قال في الآية 89: ﴿ربنا﴾؟","answer":"قال ﴿ربي﴾ في مقام شهادته على أداء رسالته الخاصة، وقال ﴿ربنا﴾ حين جمع نفسه والمؤمنين في الدعاء والتوكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص62–63، تحت «توجيه الإضافة في لفظ الرب»","url":""}]},{"id":"s7-492","number":492,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"لماذا عُدّي ﴿نصحت﴾ باللام: ﴿ونصحت لكم﴾؟","answer":"اللام تبين أن نصحه خالص لمنفعتهم ومصلحتهم، لا طلبًا لحظ نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص63، تحت «سر تعدية فعل النصيحة باللام»","url":""}]},{"id":"s7-493","number":493,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿فكيف آسى﴾ بالاستفهام لا «فلا آسى»؟","answer":"الاستفهام إنكاري بمعنى انتفاء الأسى بعد قيام الحجة وإصرارهم على الكفر؛ وكيف يحزن على من اختار سبب هلاكه؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص61، تحت «بلاغة مقابلة الصيغ»","url":""}]},{"id":"s7-494","number":494,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"لماذا صدّر الاستفهام بالفاء: ﴿فكيف آسى﴾؟","answer":"الفاء تفرع انتفاء الأسى على ما قبلها: لقد بلّغ ونصح فكذبوا، فكيف يبقى موضع للحزن عليهم بعد ذلك؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص63، تحت «دلالة الفاء في مطلع الاستفهام»","url":""}]},{"id":"s7-495","number":495,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"لماذا عبّر بالمضارع ﴿آسى﴾ بعد الأفعال الماضية: تولى، أبلغت، نصحت؟","answer":"يناسب المضارع تأكيد عدم تحقق الأسى واستمرار هذا الموقف، بينما سجلت الأفعال الماضية ما تم من البلاغ والنصح. ويجيز المصدر حمل المضارع على حكاية الحال الماضية، فيستحضر موقفه عند إعراضه عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص63–64، تحت «نكتة التعبير عن الأسى بالمضارع»","url":""}]},{"id":"s7-496","number":496,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿على قوم كافرين﴾ فنكّر «قومًا» ووصفهم بالكفر؟","answer":"التنكير مع وصف الكفر يذمهم بهذا الوصف ويبين أن سبب عدم الأسى ليس القرابة، بل كونهم قومًا راسخين في الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص64، تحت «علة تنكير القوم ونسبته»","url":""}]},{"id":"s7-497","number":497,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"لماذا انتقل السياق من قصة شعيب إلى قاعدة عامة: ﴿وما أرسلنا في قرية من نبي﴾؟","answer":"بعد عرض نماذج الرسل وأقوامهم انتقل إلى السنة العامة التي تجمعها: الابتلاء بالبأساء والضراء لعل أهل القرى يتضرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص65، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-498","number":498,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿في قرية﴾ لا «إلى قرية»؟","answer":"﴿في قرية﴾ تصور بعثة النبي وقيامه داخل مجتمعها ومخالطته أهلها، لا مجرد توجيه رسالة من خارجها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص68–69، تحت «نكتة تعدية فعل الإرسال بـ﴿في﴾»","url":""}]},{"id":"s7-499","number":499,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿من نبي﴾ بزيادة ﴿من﴾؟","answer":"﴿من﴾ زائدة لتوكيد الاستغراق بعد النفي: ما أرسل الله نبيًا واحدًا في قرية إلا جرت سنته المذكورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص69، تحت «معنى حرف الجر ﴿من﴾»","url":""}]},{"id":"s7-500","number":500,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا أخذنا أهلها﴾ فجاء الاستثناء عقب نفي الإرسال؟","answer":"الاستثناء يبين سنة ملازمة لإرسال الرسل إلى المكذبين: لا يقع إرسال نبي في قرية إلا أعقبته تربية أهلها بالشدة لعلهم يضرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص69–70، تحت «سر التعبير بالاستثناء المفرغ»","url":""}]},{"id":"s7-501","number":501,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"ما دلالة المجاز في ﴿إلا أخذنا أهلها بالبأساء والضراء﴾؟","answer":"الأخذ هنا مجاز عن التأثير والإصابة؛ أي إصابتهم بالشدة والضر ليظهر افتقارهم ويتذكروا. فتجعل صورة الأخذ أثر الابتلاء واقعًا عليهم متمكنًا منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص69، تحت «بلاغة المجاز في لفظ الأخذ»","url":""}]},{"id":"s7-503","number":503,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"ما الفرق البياني بين ﴿البأساء﴾ و﴿الضراء﴾؟","answer":"يذكر المصدر من وجوه التفريق أن البأساء مصائب تمس البدن كالأمراض، والضراء ما يصيب الأموال والأنفس من فقر وحاجة، ويذكر توجيهًا آخر للبأساء بالشدة في الأبدان والأموال والأولاد، وللضراء بالآلام والمخاوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص69–70، تحت «سر إتباع البأساء بالضراء»","url":""}]},{"id":"s7-504","number":504,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"لماذا خُتم الابتلاء بقوله: ﴿لعلهم يضرعون﴾؟","answer":"جعل غاية الأخذ أن يتذللوا لله ويرجعوا إليه؛ فالابتلاء تربية وإنذار قبل أن يكون عقوبة استئصال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص70–71، تحت «فائدة التعبير بـ﴿لعل﴾»","url":""}]},{"id":"s7-505","number":505,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"ما دلالة التضرع في ﴿لعلهم يضرعون﴾؟","answer":"التضرع تذلل وتخشع، وهو هنا كناية عن الاعتراف بالذنب والتوبة منه. فالمطلوب أن يحملهم الابتلاء على الانكسار لله والرجوع إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص71، تحت «بلاغة الكناية في لفظ التضرع»","url":""}]},{"id":"s7-506","number":506,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"لماذا افتتحت الآية بـ﴿ثم﴾: ﴿ثم بدلنا﴾؟","answer":"تفيد ﴿ثم﴾ التراخي وعدم تعجيل الأخذ، وفيه إمهال لهم وتمكين للاستدراج بالرخاء بعد الشدة. فامتداد المهلة والتبديل كانا فرصة للاعتبار والتضرع، ثم لم ينتفعوا بهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص77، تحت «وجه الاستفتاح بـ﴿ثم﴾»","url":""}]},{"id":"s7-507","number":507,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿بدلنا مكان السيئة الحسنة﴾، دون أن يقال: بدلنا السيئة بالحسنة؟","answer":"جعل الحسنة في مكان السيئة يصور إحلال الرخاء محل الشدة إحلالًا تامًا، كأن موضع البلاء نفسه شُغل بالنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص77–78، تحت «إيثار لفظ المكان لجر السيئة بدل الباء»","url":""}]},{"id":"s7-508","number":508,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"لماذا سمّى الشدة ﴿السيئة﴾ والرخاء ﴿الحسنة﴾؟","answer":"سميت الشدة سيئة لأنها تسوءهم، والرخاء حسنة لأنه يحسن عندهم ويسرهم؛ فالتسمية بالنظر إلى أثرهما في الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص74–75، تحت «شرح المفردات: ﴿السيئة﴾ و﴿الحسنة﴾»","url":""}]},{"id":"s7-509","number":509,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى عفوا﴾، وما دلالة «عفوا» هنا؟","answer":"﴿عفوا﴾ أي كثروا في العدد والمال ونموا، ومن أصل العفو الزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص75–76، تحت «شرح المفردات: ﴿عفوا﴾»","url":""}]},{"id":"s7-510","number":510,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"لماذا جعل كثرتهم ورخاءهم غاية للتبديل بـ﴿حتى﴾؟","answer":"جعل الكثرة غاية لأن الاختبار بالرخاء بلغ مداه عندها؛ وكان المنتظر أن يشكروا، لكنهم غفلوا ونسبوا الأمر إلى العادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص79، تحت «وجه التعريف في ﴿الحسنة﴾ و﴿السيئة﴾»","url":""}]},{"id":"s7-511","number":511,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"ما سرّ تعبيرهم بقولهم: ﴿قد مس آباءنا الضراء والسراء﴾، واختيارهم لفظ ﴿مس﴾؟","answer":"قالوا ﴿مس آباءنا﴾ لأنهم لم ينظروا إلى الضراء والسراء باعتبارهما ابتلاءً مقصودًا؛ حسبوهما أحوالًا تتداولها الأزمنة كما جرت لآبائهم. فاختيار المس في كلامهم يكشف استخفافهم بالعبرة وإعراضهم عنها، ولا يقتضي أن الشدة نفسها كانت خفيفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص79–80، تحت «إيثار التعبير بالمس دون الأخذ»","url":""}]},{"id":"s7-512","number":512,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"لماذا قدّموا ﴿الضراء﴾ على ﴿السراء﴾؟","answer":"قدموا الضراء لأنها الأقرب إلى دفع ما أصابهم أولًا من البأساء والضراء، ثم أتبعوها السراء التي جاءت بعد التبديل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص80، تحت «علة تأخير السراء عن الضراء»","url":""}]},{"id":"s7-513","number":513,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"لماذا نسبوا تداول الشدة والرخاء إلى عادة الآباء؟","answer":"زعموا أن الشدة والرخاء عادة تتكرر في الأجيال كما وقعت لآبائهم، فلم يعدوهما تنبيهًا يدعو إلى التوبة والشكر. وبذلك قابلوا نعمة السراء بالغفلة، كما لم ينتفعوا بإنذار الضراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص76–77، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-514","number":514,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"لماذا عُطف ﴿فأخذناهم﴾ بالفاء بعد ﴿عفوا وقالوا﴾؟","answer":"الفاء تفيد أن الأخذ جاء عقب اكتمال الغفلة والقول الباطل؛ فلما لم ينتفعوا بالشدة ولا الرخاء جاء الجزاء سريعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص80، تحت «دلالة الفاء المصاحبة للفظ الأخذ»","url":""}]},{"id":"s7-515","number":515,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿بغتة وهم لا يشعرون﴾، فجمع بين المفاجأة ونفي الشعور؟","answer":"﴿بغتة﴾ تثبت وقوع الأخذ فجأة، و﴿وهم لا يشعرون﴾ تصف حالهم المستمرة من الغفلة وعدم توقع العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص80–81، تحت «الإخبار عن البغتة بالمصدر»","url":""}]},{"id":"s7-516","number":516,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"ما الفرق بين خاتمة ﴿لا يشعرون﴾ هنا و﴿وهم نائمون﴾ و﴿وهم يلعبون﴾ بعدها؟","answer":"﴿لا يشعرون﴾ أعم في نفي إدراك مقدمات العذاب، و﴿نائمون﴾ يصور غفلة الليل وعجزه، و﴿يلعبون﴾ يصور غفلة النهار مع الانشغال باللهو.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص81، تحت «بديع التعبير بالجملة الاسمية»","url":""}]},{"id":"s7-517","number":517,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"ما دلالة ﴿القرى﴾ في ﴿ولو أن أهل القرى آمنوا واتقوا﴾ بعد ﴿وما أرسلنا في قرية من نبي﴾؟","answer":"على حمل التعريف على العهد، ترجع القرى إلى القرى المهلكة المشار إليها من قبل؛ فإن ﴿قرية﴾ السابقة نكرة في سياق النفي فتفيد العموم. ويحتمل التعريف الجنس فيشمل أهل القرى أينما كانوا، ويذكر المصدر أيضًا احتمال الإشارة إلى مكة وما حولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص89، تحت «دلالة تعريف الألف واللام»","url":""}]},{"id":"s7-518","number":518,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا اقترنت ﴿لو﴾ بـ﴿أن﴾: ﴿ولو أن أهل القرى آمنوا﴾؟","answer":"تؤكد ﴿أن﴾ مضمون الشرط، ويؤول ما دخلت عليه بمصدر؛ أي لو حصل إيمان أهل القرى وتقواهم. فيعلق فتح البركات على تحقق هذا الإيمان، مع ما في التركيب من تقرير الصلة بين الشرط وجوابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص88، تحت «دلالة اقتران الشرط بـ﴿أن﴾»","url":""}]},{"id":"s7-519","number":519,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا أضيف ﴿أهل﴾ إلى ﴿القرى﴾ بدل أن يقال: ولو أن القرى آمنت؟","answer":"تجعل الإضافة الحكم شاملًا لسكان القرى الذين أرسلت إليهم الرسل، فتسجل حالهم من الإيمان أو الكفر. وفي التعبير تعريض بمن كذبوا من المخاطبين، وبشارة لأهل القرى الذين يؤمنون، بحسب ما يبينه السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص88، تحت «نكتة إضافة ﴿أهل﴾ إلى ﴿القرى﴾»","url":""}]},{"id":"s7-520","number":520,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا جمع بين الإيمان والتقوى؟","answer":"الإيمان تصديق القلب وأصل الاستجابة، والتقوى امتثال عملي وترك للمعصية؛ فلا تتم أسباب البركة بأحدهما دون الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص89، تحت «سر العطف في الآية»","url":""}]},{"id":"s7-521","number":521,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا عُطف ﴿واتقوا﴾ على ﴿آمنوا﴾ بالواو؟","answer":"الواو تجمع الشرطين من غير جعل أحدهما بدل الآخر؛ فالمطلوب اجتماع الإيمان والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص89، تحت «سر العطف في الآية»","url":""}]},{"id":"s7-522","number":522,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿لفتحنا عليهم بركات﴾، فاستعار الفتح للبركات؟","answer":"صُورت البركات كخزائن مغلقة يفتحها الله فتفيض؛ وفي الفتح معنى السعة بعد المنع وتتابع الخيرات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص89–90، تحت «دلالة الاستعارة في لفظ الفتح»","url":""}]},{"id":"s7-523","number":523,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا عُدّي الفتح بـ﴿على﴾: ﴿لفتحنا عليهم﴾؟","answer":"﴿على﴾ تصور البركات نازلةً عليهم من فوق ومحيطةً بهم، وفيها إيحاء بالفيض والشمول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص91، تحت «توجيه تعدي الفتح بـ﴿على﴾»","url":""}]},{"id":"s7-524","number":524,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا جمع ﴿بركات﴾ ونكّرها؟","answer":"جُمعت لتعدد أنواعها في الدين والدنيا، ونُكرت للتعظيم والتكثير: بركات كثيرة واسعة لا يحيط بها العد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص91–92، تحت «فائدة تنكير البركات وجمعها»","url":""}]},{"id":"s7-525","number":525,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿من السماء والأرض﴾ فجمع جهتي العلو والسفل؟","answer":"جمع الجهتين يوسع صورة العطاء، فيدل على خير يأتيهم من كل جهة؛ ومن أبرز أمثلته المطر من السماء والنبات من الأرض. فالتعبير لا يقصر البركات على نوع واحد، بل يصور سعة الفضل مع الإيمان والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص90–91، تحت «سر إطلاق فعل الفتح دون قيد»","url":""}]},{"id":"s7-526","number":526,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"ما دلالة الاستدراك بـ﴿ولكن كذبوا﴾ بعد الوعد بفتح البركات؟","answer":"يقابل الاستدراك بين ما كان يترتب على إيمانهم وبين ما وقع منهم فعلًا؛ فقد كذبوا، فلم يتحقق شرط فتح البركات، وجاء أخذهم نتيجة لتكذيبهم وما كسبوه من الذنوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص92، تحت «بلاغة الاستثناء بـ﴿ولكن﴾»","url":""}]},{"id":"s7-527","number":527,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا قابل ﴿لفتحنا عليهم﴾ بـ﴿فأخذناهم﴾؟","answer":"قابل الفتح بالأخذ: الإيمان يطلق أبواب الخير، والتكذيب يجعلهم في قبضة العقاب؛ فالصورتان متضادتان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص92–93، تحت «إيثار فعل الأخذ»","url":""}]},{"id":"s7-528","number":528,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿بما كانوا يكسبون﴾ لا «بما كسبوا»؟","answer":"﴿كانوا يكسبون﴾ يدل على تكرر الذنوب واستمرار اتخاذها كسبًا وعادة، لا على فعل ماض منفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص92–93، تحت «توجيه اقتران الماضي بالمضارع»","url":""}]},{"id":"s7-529","number":529,"surah":7,"verses":[97,98],"references":[{"surah":7,"verses":[97,98]}],"verseLabel":"الأعراف: 97–98","question":"لماذا تكرر الاستفهام: ﴿أفأمن أهل القرى﴾ ثم ﴿أوأمن أهل القرى﴾؟","answer":"كرر الاستفهام ليحيط بزمني الغفلة: الليل والنهار؛ فلا يأمن أهل القرى بأس الله في أي حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص99، تحت «بلاغة الإطناب في الآيات»","url":""}]},{"id":"s7-530","number":530,"surah":7,"verses":[97],"references":[{"surah":7,"verses":[97]}],"verseLabel":"الأعراف: 97","question":"لماذا دخلت الفاء بين همزة الاستفهام و﴿أمن﴾: ﴿أفأمن﴾؟","answer":"الفاء تعطف الإنكار على ما سبق من أخذ المكذبين؛ أفبعد هذه السنن والوقائع أمن اللاحقون؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص97، تحت «دلالة حرف الفاء»","url":""}]},{"id":"s7-531","number":531,"surah":7,"verses":[97],"references":[{"surah":7,"verses":[97]}],"verseLabel":"الأعراف: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يأتيهم بأسنا﴾ فجعل البأس آتيًا؟","answer":"صُور البأس كقادم يتحرك نحوهم، فيفاجئهم من حيث لا يملكون دفعه، وفي ذلك تشخيص للوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص99، تحت «بلاغة الاستعارة في الآية»","url":""}]},{"id":"s7-532","number":532,"surah":7,"verses":[97],"references":[{"surah":7,"verses":[97]}],"verseLabel":"الأعراف: 97","question":"لماذا اختير ﴿بياتًا﴾ لا «ليلًا»؟","answer":"البيات يدل هنا على إتيان العذاب ليلًا، في وقت المبيت والدعة والأمن. وإذا حمل البأس على صورة بأس الحرب، أوحى البيات بمباغتة العدو في وقت غفلته؛ فتقوى صورة الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص95، تحت «شرح المفردات: ﴿بياتًا﴾»","url":""}]},{"id":"s7-533","number":533,"surah":7,"verses":[97],"references":[{"surah":7,"verses":[97]}],"verseLabel":"الأعراف: 97","question":"لماذا خُتمت بـ﴿وهم نائمون﴾ مع أن «بياتًا» يدل على الليل؟","answer":"ذكر النوم بعد البيات لتصوير تمام الغفلة والعجز عند مجيء العذاب، لا لمجرد تحديد الليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص98–99، تحت «بلاغة حالية الفاصلة»","url":""}]},{"id":"s7-534","number":534,"surah":7,"verses":[98],"references":[{"surah":7,"verses":[98]}],"verseLabel":"الأعراف: 98","question":"لماذا عطف الاحتمال الثاني بـ﴿أو﴾: ﴿أوأمن أهل القرى﴾؟","answer":"على قراءة ﴿أو﴾ بالسكون، يعطف السياق أحد الحالين على الآخر: مجيء العذاب ليلًا أو نهارًا، فينكر أمنهم في أي منهما. ويذكر المصدر أيضًا القراءة بواو العطف مع همزة الاستفهام، وفيها إنكار الأمن من الحالين جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص102–103، تحت «توجيه قراءة العطف بـ﴿أو﴾»","url":""}]},{"id":"s7-535","number":535,"surah":7,"verses":[98],"references":[{"surah":7,"verses":[98]}],"verseLabel":"الأعراف: 98","question":"لماذا كرر ﴿أهل القرى﴾ ولم يضمرهم؟","answer":"أعيد الاسم الظاهر لإبلاغ الوعيد وتجديد التوبيخ والتعظيم والتهويل. وتكرار ﴿أهل القرى﴾ يسترعي الأسماع إلى الحكم عليهم، ويناسب تفصيل وجهي مجيء البأس في الليل والنهار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص102–103، تحت «بلاغة التكرار في الآية»","url":""}]},{"id":"s7-536","number":536,"surah":7,"verses":[98],"references":[{"surah":7,"verses":[98]}],"verseLabel":"الأعراف: 98","question":"لماذا قابل ﴿بياتًا﴾ بـ﴿ضحى﴾ لا بـ«نهارًا»؟","answer":"الضحى وقت ارتفاع النهار وانتشار الحركة والاطمئنان، فقابل البيات لا بمجرد النهار بل بوقت الغفلة في النشاط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص104–105، تحت «بلاغة الطباق في الآية»","url":""}]},{"id":"s7-537","number":537,"surah":7,"verses":[98],"references":[{"surah":7,"verses":[98]}],"verseLabel":"الأعراف: 98","question":"لماذا خُتمت بـ﴿وهم يلعبون﴾ لا «وهم مستيقظون»؟","answer":"﴿يلعبون﴾ يذم حالهم؛ فهم مستيقظون قادرون على الاعتبار لكنهم مشتغلون بما لا ينفع، وهذا أشد من مجرد اليقظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص104، تحت «جملة الفاصلة بين المجاز والاستعارة»","url":""}]},{"id":"s7-538","number":538,"surah":7,"verses":[98],"references":[{"surah":7,"verses":[98]}],"verseLabel":"الأعراف: 98","question":"ما سر المقابلة بين ﴿وهم نائمون﴾ و﴿وهم يلعبون﴾؟","answer":"المقابلة تستوعب غفلتين: غفلة اضطرارية بالنوم ليلًا، وغفلة اختيارية باللهو نهارًا؛ فلا زمان يمنع بأس الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص104–105، تحت «سر التعبير باسم الفاعل، والفعل المضارع»","url":""}]},{"id":"s7-539","number":539,"surah":7,"verses":[99],"references":[{"surah":7,"verses":[99]}],"verseLabel":"الأعراف: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿أفأمنوا مكر الله﴾ بعد تكرار ﴿أفأمن أهل القرى﴾؟","answer":"بعد إنكار أمنهم مجيء البأس في الليل والنهار جمع ذلك كله في إنكار أصل الأمن من تدبير الله الخفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص108–109، تحت «التعبير بـ﴿أفأمنوا مكر الله﴾ دون غيرها»","url":""}]},{"id":"s7-540","number":540,"surah":7,"verses":[99],"references":[{"surah":7,"verses":[99]}],"verseLabel":"الأعراف: 99","question":"لماذا سُمّي أخذ الله لهم ﴿مكر الله﴾؟","answer":"يصور التعبير استدراجهم بالإمهال والنعمة، ثم مجيء العقوبة من حيث لا يتوقعون، كحال من يستدرج عدوه حتى يقع في قبضته. فالمراد هنا تدبير العقوبة والجزاء العادل، لا الظلم أو الغدر المذموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص106–107، تحت «شرح المفردات: ﴿مكر﴾»","url":""}]},{"id":"s7-541","number":541,"surah":7,"verses":[99],"references":[{"surah":7,"verses":[99]}],"verseLabel":"الأعراف: 99","question":"لماذا كرر ﴿مكر الله﴾ ظاهرًا في الجملتين ولم يقل: فلا يأمنه؟","answer":"أعيد ﴿مكر الله﴾ لتحقيق الوعيد وتأكيده، وإثارة العظة وتفخيم المهابة. وفي إعادة الاسم الظاهر ترسيخ لعظم قدرة الله على إصابة من يشاء بما يشاء، فلا مانع لحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص109–110، تحت «نكتة تكرار لفظ المكر»","url":""}]},{"id":"s7-542","number":542,"surah":7,"verses":[99],"references":[{"surah":7,"verses":[99]}],"verseLabel":"الأعراف: 99","question":"لماذا عبّر بالفعل أولًا ﴿أفأمنوا﴾ ثم بالمضارع ﴿فلا يأمن﴾؟","answer":"الماضي ﴿أفأمنوا﴾ ينكر وقوع الأمن منهم، والمضارع ﴿لا يأمن﴾ يقرر قاعدة مستمرة لكل زمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص110–111، تحت «براعة نفي المضارع بـ﴿لا﴾»","url":""}]},{"id":"s7-543","number":543,"surah":7,"verses":[99],"references":[{"surah":7,"verses":[99]}],"verseLabel":"الأعراف: 99","question":"لماذا جاءت الفاء في ﴿فلا يأمن مكر الله﴾؟","answer":"الفاء تفريع للقاعدة على الإنكار السابق: لما كان أمنهم باطلًا ثبت أن من يأمن هذا الأمن من الخاسرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص110، تحت «بلاغة التذييل في المختتم»","url":""}]},{"id":"s7-544","number":544,"surah":7,"verses":[99],"references":[{"surah":7,"verses":[99]}],"verseLabel":"الأعراف: 99","question":"لماذا قصر الأمن من مكر الله على ﴿القوم الخاسرون﴾؟","answer":"حصر الأمن في الخاسرين لأنه يفضي إلى ترك الحذر والتوبة حتى يفجأ العذاب؛ فلا يصدر إلا عمن خسر بصيرته وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص110–111، تحت «فائدة الاستثناء المفرغ»","url":""}]},{"id":"s7-545","number":545,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"لم قيل ﴿أولم يهد للذين يرثون الأرض﴾ باللام، مع أن الهداية قد تتعدى بـ«إلى»؟","answer":"تدل اللام على اختصاص هؤلاء بالبيان والإرشاد الذي كان ينبغي أن ينتفعوا به. ويذكر المصدر تضمين ﴿يهد﴾ معنى يبين؛ فالمعنى: ألم يتبين لهم من مصائر من سبقهم ما يرشدهم إلى الاعتبار؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص116–117، تحت «نكتة تعدية الفعل ﴿يهدي﴾ باللام»","url":""}]},{"id":"s7-546","number":546,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"لماذا وصف اللاحقين بأنهم ﴿يرثون الأرض﴾؟","answer":"وصفهم بالوراثة لأنهم سكنوا أرض من هلك قبلهم وانتقلت إليهم من غيرهم، فكان في ذلك نعمة وعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص117، تحت «لفظ الإرث بين الحقيقة والمجاز»","url":""}]},{"id":"s7-547","number":547,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"أي أرض يستحضرها قوله ﴿يرثون الأرض من بعد أهلها﴾؟","answer":"تستحضر ﴿الأرض﴾ أرض الأقوام الذين مضوا ومنازلهم وقراهم؛ فبقاء اللاحقين فيها بعد زوال أهلها شاهد يدعوهم إلى الاعتبار. ويحتمل التعريف الجنس، فيعم من يخلف أمة في أرضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص117، تحت «دلالة الألف واللام في لفظ ﴿الأرض﴾»","url":""}]},{"id":"s7-548","number":548,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"لماذا جاء التركيب ﴿أن لو نشاء﴾؟","answer":"﴿أن﴾ هنا مخففة من الثقيلة، واسمها ضمير شأن مقدر، وهي تؤكد مضمون الخبر. ثم يبين الشرط أن إصابتهم بذنوبهم تحت مشيئة الله؛ أي ينبغي أن يتضح لهم أنه لو شاء أصابهم كما أصاب من قبلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص117–118، تحت «نكتة التعبير بالمصدر المنسبك؛ دلالة فعل الشرط على الماضي»","url":""}]},{"id":"s7-549","number":549,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿أصبناهم بذنوبهم﴾ لا «عذبناهم»؟","answer":"الإصابة هنا بمعنى الإهلاك؛ فتصور حلول الجزاء بهم وتمكن أثره فيهم، والباء في ﴿بذنوبهم﴾ تبين سببه. ويذكر المصدر أيضًا توجيهًا على تقدير: أصبنا أمثالهم، تنبيهًا لهم بمصير من سبقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص120، تحت «بلاغة المجاز في لفظ الإصابة»","url":""}]},{"id":"s7-550","number":550,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"ما دلالة الباء في ﴿بذنوبهم﴾؟","answer":"الباء سببية: أصبناهم بسبب ذنوبهم؛ فلا يقع الأخذ اعتباطًا ولا ظلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص118، تحت «دلالة الباء في لفظ ﴿بذنوبهم﴾»","url":""}]},{"id":"s7-551","number":551,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"لماذا عدل من الشرط ﴿لو نشاء أصبناهم﴾ إلى المضارع ﴿ونطبع﴾؟","answer":"من توجيهات المصدر أن ﴿ونطبع﴾ استئناف يخبر باستمرار الطبع وتجدد أثره، بعد ذكر الإصابة في جواب الشرط بصيغة الماضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص118–119، تحت «دلالة الاستئناف بالمضارع»","url":""}]},{"id":"s7-552","number":552,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿نطبع على قلوبهم﴾، فجعل القلوب موضع الختم؟","answer":"الطبع ختم يمنع نفوذ الحق، وجعل محله القلوب لأنها موضع الإدراك والقبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص121–122، تحت «بلاغة الاستعارة في لفظ الطبع»","url":""}]},{"id":"s7-553","number":553,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"لماذا فرّع على طبع القلوب قوله: ﴿فهم لا يسمعون﴾؟","answer":"الفاء تجعل عدم سماع الحق نتيجة للطبع؛ فالمختوم على قلبه يسمع الصوت لكنه لا يسمع سماع قبول وانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص121، تحت «سر وصل جملة ﴿فهم لا يسمعون﴾»","url":""}]},{"id":"s7-554","number":554,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"لماذا نفى السماع لا الفهم أو الإيمان؟","answer":"لأن المنفي سماع القبول والانتفاع بالمواعظ، لا مجرد إدراك الأصوات؛ فاختيار السمع يصور انغلاق طريق التلقي الذي يقيم الحجة ويدعو إلى الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص121–122، تحت «علة إيثار لفظ السمع على العقل»","url":""}]},{"id":"s7-555","number":555,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]},{"surah":9,"verses":[87]},{"surah":63,"verses":[3]}],"verseLabel":"الأعراف: 100؛ التوبة: 87؛ المنافقون: 3","question":"ما سرّ اختلاف الخاتمة بعد الطبع على القلوب: ﴿فهم لا يسمعون﴾ في الأعراف، و﴿فهم لا يفقهون﴾ في التوبة والمنافقون؟","answer":"في الأعراف يجيء نفي السماع بعد ذكر الإصابة بالذنوب والطبع على القلوب، فيصور انقطاع سماع القول الحق والانتفاع به. وفي التوبة يتصل نفي الفقه برضاهم بالقعود وترك صحبة الرسول والجهاد، فلم يدركوا ما فاتهم من الخير. وفي المنافقون جاء بعد إيمانهم ثم كفرهم، فصور فقد إدراك حقائق الإيمان والتمييز النافع؛ وتلتقي المواضع في أثر الإعراض مع اختلاف ما يبرزه السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص18، تحت «الغرض من التعبير بالجملة الاسمية ﴿فهم لا يفقهون﴾»","url":""}]},{"id":"s7-556","number":556,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿تلك القرى﴾ باسم الإشارة للبعيد؟","answer":"يشير البعد إلى عظم شأن القرى المذكورة ومصائرها، فيدعو إلى التعجب والاعتبار بما حل بها. ويذكر المصدر وجهًا آخر هو أن البعد يوقع التعظيم في نفس السامع، فتكون الإشارة إلى حال أهلها في قوتهم ومكانتهم ثم هلاكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص127–128، تحت «التعبير بـ﴿تلك﴾ دون غيرها»","url":""}]},{"id":"s7-557","number":557,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما أثر افتتاح الكلام بـ﴿تلك القرى﴾ قبل قوله ﴿نقص عليك من أنبائها﴾؟","answer":"يعين افتتاح الكلام القرى المذكورة ويستحضرها في ذهن السامع قبل الحديث عن أنبائها. وعلى جعل ﴿القرى﴾ خبرًا لـ﴿تلك﴾، يكون في الإخبار بالاسم تعظيم لشأنها والتنبيه إلى ما في هلاكها من العظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص128، تحت «بلاغة الإخبار بالاسم والفعل»","url":""}]},{"id":"s7-558","number":558,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"لماذا عبّر بالمضارع ﴿نقص عليك﴾ عن قصص وقع في الماضي؟","answer":"يذكر المصدر أن المضارع يعبر عن القص الذي سبق، مع وعد بزيادة القصص فيما يأتي؛ ففيه دلالة على تجدد عرض الأنباء واستمراره للموعظة والتخويف، لا مجرد تسجيل رواية انتهت.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص128–129، تحت «علة التعبير عن القص بالمضارع»","url":""}]},{"id":"s7-559","number":559,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما الذي تضيفه جملة ﴿نقص عليك من أنبائها﴾ إلى عرض مصائر القرى؟","answer":"فيها امتنان على النبي بإطلاعه على أنبائها وتثبيت له، كما يستدل بهذه المعرفة على نبوته؛ إذ أعلمه الله من أخبار الأمم ما لم يسبق له علم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص128، تحت «دلالة الحالية في جملة القص»","url":""}]},{"id":"s7-560","number":560,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما الذي تفيده ﴿من﴾ في ﴿نقص عليك من أنبائها﴾؟","answer":"﴿من﴾ للتبعيض؛ فما قصه القرآن من أنبائها هو القدر المختار للعبرة، لا جميع تفاصيل تاريخها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص129–130، تحت «دلالة حرف الجر ﴿من﴾»","url":""}]},{"id":"s7-561","number":561,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد جاءتهم رسلهم﴾ مع أن الجملة تفسر أنباء القرى؟","answer":"الجملة تبين أهم أنبائها وتؤكد باللام وقد أن الرسل بلغوهم فعلًا، فلا عذر لهم في التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص129، تحت «بيان وجه العطف بجملة ﴿ولقد جاءتهم﴾»","url":""}]},{"id":"s7-562","number":562,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"لم قيل ﴿جاءتهم رسلهم﴾ بضمير الجماعة بعد ذكر ﴿تلك القرى﴾؟","answer":"عاد الضمير على أهل القرى، فهم الذين جاءتهم الرسل وخوطبوا بالبينات. فالكلام ينتقل من ذكر القرى إلى بيان حال سكانها، وهو المقصود من أخبارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص130، تحت «دلالة الضمير ومغزى تأنيثه»","url":""}]},{"id":"s7-563","number":563,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"لماذا جمع ﴿البينات﴾؟","answer":"جُمعت لتعدد الحجج والمعجزات والدلائل التي جاء بها الرسل، فلم يكن التكذيب بعد بينة واحدة خفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص130، تحت «توجيه تعريف البينات وجمعها»","url":""}]},{"id":"s7-564","number":564,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿فما كانوا ليؤمنوا﴾ بدل «فلم يؤمنوا»؟","answer":"اللام في ﴿ليؤمنوا﴾ لام الجحود بعد ﴿ما كان﴾؛ فالتعبير ينفي صلاحية الإيمان ووقوعه منهم بعد رسوخ التكذيب، وهو أبلغ من مجرد ﴿لم يؤمنوا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص131، تحت «بلاغة التعبير بجملة ﴿فما كانوا ليؤمنوا﴾»","url":""}]},{"id":"s7-565","number":565,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿بما كذبوا من قبل﴾، وما المراد بـ«من قبل»؟","answer":"أي لم يكونوا ليصدقوا عند مجيء الرسل بما سبق أن كذبوا به حين أخذ عليهم الميثاق أو عند أول مجيء البينات؛ فالتكذيب السابق أورث الإصرار اللاحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص132، تحت «سر التعبير بالجار ﴿من قبل﴾»","url":""}]},{"id":"s7-566","number":566,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"لماذا خُتمت بـ﴿كذلك يطبع الله على قلوب الكافرين﴾ بعد قوله قبلها: ﴿ونطبع على قلوبهم﴾؟","answer":"الخاتمة تحول أخبار القرى إلى سنة عامة: مثل ذلك الطبع الناشئ عن الإصرار يطبع الله على قلوب كل كافر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص133–134، تحت «التعبير بـ﴿يطبع الله﴾ دون غيره»","url":""}]},{"id":"s7-567","number":567,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"لماذا أظهر اسم الله في ﴿يطبع الله﴾ بعد ضمير التعظيم ﴿نطبع﴾؟","answer":"في الانتقال من ﴿ونطبع﴾ إلى ﴿يطبع الله﴾ إظهار للاسم الجليل يزيد التهويل والوعيد، ويقرر أن الحكم صادر عن الله. ويلفت السامع إلى شمول سنة الجزاء للمكذبين بعد عرض مصائر القرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص134–135، تحت «بلاغة الالتفات من المتكلم إلى الغائب»","url":""}]},{"id":"s7-568","number":568,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الأعراف: ﴿كذلك يطبع الله﴾ بالاسم الظاهر، وقوله تعالى في يونس في القصة النظيرة: ﴿كذلك نطبع﴾ بنون العظمة؟","answer":"سبق في يونس إسناد النجاة والبعث إلى ضمير العظمة، مثل ﴿فنجيناه﴾ و﴿بعثنا﴾، فجاء ﴿كذلك نطبع﴾ موافقًا له. أما الأعراف فسبق فيها ﴿ولقد جاءتهم رسلهم بالبينات﴾، فناسب الإظهار أن يقال ﴿كذلك يطبع الله﴾؛ إذ لم يجر المقطع على ضمير المتكلم في الإحسان السابق كما في يونس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص133–134، تحت «التعبير بـ﴿يطبع الله﴾ دون غيره»","url":""}]},{"id":"s7-569","number":569,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿بما كذبوا من قبل﴾، وفي يونس: ﴿بما كذبوا به﴾؟","answer":"سبق في الأعراف التصريح بالإيمان بالذي أرسل به النبي، فحذف ﴿به﴾ من ﴿بما كذبوا من قبل﴾ للإيجاز اعتمادًا على ما تقدم ودفعًا للتكرار. أما يونس فلم يسبق في موضع المقارنة ما يقوم مقامه، فذكر ﴿به﴾ لربط الصلة بالموصول. ويذكر المصدر للأعراف أيضًا وجهًا في سعة التكذيب وعدم تقييده بمتعلق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص132–133، تحت «توجيه المتشابه اللفظي في تعدية فعل التكذيب»","url":""}]},{"id":"s7-570","number":570,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"ما سر تأكيد استغراق النفي في قوله: ﴿وما وجدنا لأكثرهم من عهد﴾؟","answer":"تؤكد ﴿من﴾ استغراق النفي، فلا يفيد التعبير مجرد إخلال عارض بالعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص140، تحت «سر تأكيد الاستغراق»","url":""}]},{"id":"s7-1609","number":1609,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"ما وجه البلاغة في نفي الوجدان بقوله: ﴿وما وجدنا﴾؟","answer":"نفي الوجدان كناية عن انتفاء الوفاء بالعهد؛ فما ثبت وجوده ظهر أثره، فلما انتفى الوفاء عُبر عنه بأنه لم يوجد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص142–143، تحت «بلاغة الكناية في نفي الوجدان»","url":""}]},{"id":"s7-571","number":571,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿لأكثرهم﴾ ولم يعمم الحكم على الجميع؟","answer":"قال ﴿لأكثرهم﴾ إنصافًا؛ إذ بقي من وفى بالعهد وآمن، فلا يعمم الذم على الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص141–142، تحت «علة التعبير بالأكثر دون غيره»","url":""}]},{"id":"s7-572","number":572,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"لماذا زيدت ﴿من﴾ في ﴿من عهد﴾؟","answer":"﴿من﴾ زائدة في سياق النفي لتوكيده واستغراق جنس العهد: لم يوجد لأكثرهم شيء من الوفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص143، تحت «وجه تعريف العهد»","url":""}]},{"id":"s7-573","number":573,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"ما المراد بـ﴿عهد﴾ هنا: الوصية الفطرية أم الوفاء بما عاهدوا عليه؟","answer":"يشمل عهد الفطرة والتوحيد وما أخذه الله عليهم، كما يشمل وفاءهم بما عاهدوا الرسل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص138–139، تحت «شرح المفردات: ﴿عهد﴾»","url":""}]},{"id":"s7-574","number":574,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"لماذا قابل النفي بـ﴿وإن وجدنا أكثرهم لفاسقين﴾؟","answer":"قابل عدم وجدان العهد بإثبات الفسق ليبين أن السبب خروجهم المتكرر عن الطاعة، لا خفاء الحق عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص144–145، تحت «بلاغة التعبير بـ﴿وما وجدنا لأكثرهم﴾ ﴿وإن وجدنا أكثرهم﴾»","url":""}]},{"id":"s7-575","number":575,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"لماذا اختلف معنى ﴿وجدنا﴾ في الموضعين المتجاورين؟","answer":"الأول بمعنى ألفينا: لم يوجد لأكثرهم وفاء بالعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص144، تحت «بلاغة التعبير بـ﴿وما وجدنا لأكثرهم﴾ ﴿وإن وجدنا أكثرهم﴾»","url":""}]},{"id":"s7-576","number":576,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"لماذا أكد الخبر بـ﴿إن﴾ واللام: ﴿وإن وجدنا أكثرهم لفاسقين﴾؟","answer":"على الوجه الذي تكون فيه ﴿إن﴾ مخففة من الثقيلة، تؤكد الجملة علم الله بحالهم، وتأتي اللام فارقة بينها وبين النافية. وفي اجتماع التقرير والتوكيد تسجيل لرسوخ خروج أكثرهم عن الطاعة، لا مجرد وصف عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص143–144، تحت «دلالة الخبر في جملة الوجدان»","url":""}]},{"id":"s7-577","number":577,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"لماذا اختيرت خاتمة ﴿لفاسقين﴾ بعد الحديث عن العهد؟","answer":"الفسق خروج عن الطاعة والعهد؛ فناسب ختام الآية التي نفت الوفاء وأثبتت النقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص144–145، تحت «بلاغة التعبير بـ﴿وما وجدنا لأكثرهم﴾ ﴿وإن وجدنا أكثرهم﴾»","url":""}]},{"id":"s7-578","number":578,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"لماذا بدأت قصة موسى بـ﴿ثم بعثنا﴾ مع أن بعث الرسل متعاقب؟","answer":"تفيد ﴿ثم﴾ مهلة بين بعثة موسى ومن سبقه، ويلائم ذلك انتقال السياق إلى قصة ذات شأن بعد تلك القصص. ويذكر المصدر أن مهلة التراخي الرتبي ملازمة هنا، ولو اختلف مقدار الفاصل الزمني بين موسى وبعض السابقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص151، تحت «دلالة العطف بـ﴿ثم﴾»","url":""}]},{"id":"s7-579","number":579,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعدهم﴾، وإلى من يعود الضمير؟","answer":"يعود إلى الرسل المذكورين أو إلى الأمم والقرى المتقدمة؛ أي بعد أولئك السابقين بعث الله موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص151، تحت «توجيه عود الضمير ﴿هم﴾»","url":""}]},{"id":"s7-580","number":580,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"لماذا قدّم ﴿من بعدهم﴾ على ﴿موسى﴾؟","answer":"قدم ﴿من بعدهم﴾ للاعتناء بتأخر هذه البعثة عن السابقين، ولتشويق السامع إلى الرسول الذي سيذكر بعدها. فيتصل الخبر بما سبقه قبل أن يصرح باسم موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص151، تحت «نكتة تقديم شبه الجملة»","url":""}]},{"id":"s7-581","number":581,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿بعثنا... موسى﴾، دون أن يقال: أرسلنا موسى؟","answer":"البعث نوع من الإرسال يتضمن الإنهاض والإثارة لمهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص150–151، تحت «متشابه التعبير عن لفظي الإرسال والبعث حذفًا وذكرًا»","url":""}]},{"id":"s7-582","number":582,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿بآياتنا﴾ قبل ذكر الجهة المبعوث إليها؟","answer":"تقديم ﴿بآياتنا﴾ يبرز عدة موسى وحجته قبل ذكر الخصم؛ فهو مبعوث مؤيد بالآيات لا داخل المواجهة بقوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص152، تحت «سر تقديم الآيات»","url":""}]},{"id":"s7-583","number":583,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما دلالة الباء في ﴿بآياتنا﴾؟","answer":"تفيد الملابسة والمصاحبة؛ أي بعث موسى ملتبسًا بآيات الله ومؤيدًا بها. ويجعل المصدر ﴿بآياتنا﴾ متعلقًا بحال من موسى، أو بوصف لمصدر البعث، فيبرز اقتران الرسالة بدليلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص151–152، تحت «بلاغة الإيجاز بالحذف»","url":""}]},{"id":"s7-584","number":584,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى فرعون وملئه﴾ لا «إلى فرعون وقومه»؟","answer":"خُص فرعون وملؤه لأنهم مركز السلطة والتدبير وقادة التكذيب، ومن ورائهم يتبع عامة القوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص152، تحت «علة إيثار لفظ الملأ»","url":""}]},{"id":"s7-585","number":585,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"لم انتقل السياق من ﴿بعثنا... بآياتنا﴾ إلى ﴿فظلموا بها﴾ دون تفصيل جميع الآيات هنا؟","answer":"أجمل الآيات في هذا الموضع وأوجز القصة؛ فالتقدير أنه جاءهم بها فكفروا، ثم تأتي تفاصيل المواجهة بعد ذلك. فيهيئ الإجمال السامع للعبرة من عاقبتهم قبل عرض مشاهد القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص151–152، تحت «بلاغة الإيجاز بالحذف»","url":""}]},{"id":"s7-586","number":586,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فظلموا بها﴾، فعُدّي الظلم بالباء؟","answer":"ضمن ﴿ظلموا﴾ معنى كفروا أو كذبوا، فعدي بالباء ليدل على جحودهم الآيات مع ما فيه من ظلم بوضعها موضع الإنكار. ويذكر المصدر وجهًا آخر يجعل الباء سببية؛ أي ظلموا بسبب موقفهم من الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص152–153، تحت «بلاغة التضمين في قوله: ﴿فظلموا بها﴾»","url":""}]},{"id":"s7-587","number":587,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"لماذا حُذف مفعول ﴿ظلموا﴾؟","answer":"حذف المفعول ليعم ظلمهم أنفسهم وموسى وقومه والحق، فلا يحصر فسادهم في جهة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص152–153، تحت «بلاغة التضمين في قوله: ﴿فظلموا بها﴾»","url":""}]},{"id":"s7-588","number":588,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فانظر﴾ بالفاء مباشرة بعد ظلمهم؟","answer":"تفرع الفاء الأمر بالنظر على ما أجمل من كفرهم وظلمهم، مع إيجاز ما ترتب عليه من الهلاك؛ كأنه قيل: فكفروا فجرى عليهم ما جرى، فانظر عاقبتهم. وهي دعوة إلى نظر الاعتبار في سبب الهلاك ونتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص153–154، تحت «دلالة الفاء في لفظ النظر»","url":""}]},{"id":"s7-589","number":589,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿كيف كان عاقبة المفسدين﴾ لا «ما عاقبتهم»؟","answer":"الاستفهام بـ﴿كيف﴾ يلفت إلى هيئة العاقبة وفظاعتها لا إلى مجرد حصولها، فيستدعي نظرًا واعتبارًا أعمق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص154، تحت «سر التعبير بـ﴿كيف﴾»","url":""}]},{"id":"s7-590","number":590,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"لماذا سمّاهم ﴿المفسدين﴾ بعد وصف فعلهم بالظلم؟","answer":"في وصفهم بالمفسدين بيان أن الكفر والظلم اللذين ارتكبوهما سبب سوء العاقبة، وأن الظلم يستلزم الإفساد. ويبرز المصدر فساد الاعتقاد والقلب الذي ينشأ عنه فساد الأعمال؛ فالإظهار يربط المصير بالوصف الذي استحقوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص154–155، تحت «علة إيثار لفظ المفسدين وإظهاره»","url":""}]},{"id":"s7-591","number":591,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"ما سرّ نداء موسى فرعون باسمه السلطاني: ﴿يا فرعون﴾؟","answer":"فرعون لقب الملك في قومه، وفي مناداته به مراعاة للعرف في الخطاب واستجلاب لحسن استماعه. ويربط المصدر هذا النداء بالأمر الإلهي بالقول اللين، مع بقاء موسى ثابتًا في إعلان رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص159، تحت «دلالة التصريح باسم فرعون»","url":""}]},{"id":"s7-592","number":592,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"لم جاء ﴿وقال موسى﴾ بالواو بعد إجمال بعثته وظلم فرعون وملئه؟","answer":"بدأت القصة بإجمال النتيجة، ثم جاء قول موسى تفصيلًا لمقدماتها. فناسب الواو التي تجمع التفصيل إلى الإجمال، ولم تناسب الفاء الدالة على التعقيب؛ لأن ابتداء الحوار سابق على النتيجة التي أجملت.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص157–158، تحت «بلاغة الوصل في الآية»","url":""}]},{"id":"s7-593","number":593,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"لماذا بدأ موسى كلامه بالتوكيد: ﴿إني رسول﴾؟","answer":"أكد بـ﴿إن﴾ لأن فرعون مظنة الإنكار والتكذيب، ولإعلان حقيقة الرسالة بثبات أمام سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص159–160، تحت «سر التوكيد في حكاية كلام موسى»","url":""}]},{"id":"s7-594","number":594,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿رسول من رب العالمين﴾ لا «رسول الله»؟","answer":"﴿من رب العالمين﴾ تهدم دعوى فرعون للربوبية وتبين أن مرسل موسى هو رب الجميع، أما ﴿رسول الله﴾ فلا تظهر هذه المقابلة بالقدر نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص160، تحت «وجه إيثار صفة ﴿رب العالمين﴾»","url":""}]},{"id":"s7-595","number":595,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"لم جعل موسى إعلان رسالته عنوان كلامه: ﴿إني رسول من رب العالمين﴾؟","answer":"لأن إعلانه أنه مرسل من رب العالمين يقرر مصدر سلطانه في الخطاب، ويستدعي قبول ما جاء به. وفي ذلك إلقاء للمهابة في نفوس المخاطبين؛ فهو يبلغ عن ربهم، ولا يتكلم من تلقاء نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص160، تحت «علة إخبار النبي بالرسالة»","url":""}]},{"id":"s7-596","number":596,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿من رب العالمين﴾ بـ﴿من﴾؟","answer":"﴿من﴾ لابتداء الغاية؛ فرسالته صادرة من رب العالمين ووحيه من عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص159–160، تحت «سر التوكيد في حكاية كلام موسى»","url":""}]},{"id":"s7-597","number":597,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"ما مناسبة وصف الله بـ﴿رب العالمين﴾ في مواجهة فرعون؟","answer":"وصفه برب العالمين في مواجهة فرعون لنفي ربوبيته المزعومة وإثبات أن موسى وفرعون وكل الخلق تحت تدبير رب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص160–161، تحت «وجه إيثار صفة ﴿رب العالمين﴾»","url":""}]},{"id":"s7-598","number":598,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لماذا بدأ وصف نفسه بـ﴿حقيق على أن لا أقول على الله إلا الحق﴾ قبل إظهار المعجزة؟","answer":"قدم صدقه وأمانته في القول على المعجزة لأن دلالة الآية لا تنفصل عن دعوى حاملها؛ فهو ملتزم ألا ينسب إلى الله إلا الحق ثم يقيم البينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص165–166، تحت «سر إيثار لفظ ﴿حقيق﴾ على غيره»","url":""}]},{"id":"s7-599","number":599,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لماذا عُدّي ﴿حقيق﴾ بـ﴿على﴾ في قراءة الجمهور؟","answer":"من أوجه قراءة ﴿حقيق على أن لا أقول﴾ أن ﴿على﴾ بمعنى الباء؛ أي جدير بألا يقول على الله إلا الحق، أو أن ﴿حقيق﴾ ضمن معنى حريص فعدي بعلى. ويذكر المصدر أوجهًا أخرى، فلا تخلط هذه القراءة بقراءة ﴿حقيق عليَّ﴾ ذات ياء المتكلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص164–165، تحت «دلالة توجيه قراءة ﴿على﴾»","url":""}]}]);
